/* Sesión de la cuenta (jugador o empleado), aparte de la del organizador: se guarda en el navegador para no tener que
   ingresar cada vez, y se renueva sola antes de vencer */
const JUGADOR_STORAGE_KEY = "sp:jugador";
function readStoredJugador() {
  try { return JSON.parse(localStorage.getItem(JUGADOR_STORAGE_KEY) || "null"); } catch { return null; }
}
function writeStoredJugador(value) {
  try {
    if (value) localStorage.setItem(JUGADOR_STORAGE_KEY, JSON.stringify(value));
    else localStorage.removeItem(JUGADOR_STORAGE_KEY);
  } catch {}
}

function useJugador() {
  const [jugador, setJugadorState] = useState(null); // { id, email, perfil, accessToken, refreshToken, expiresAt }
  const ref = useRef(null);
  const setJugador = useCallback((j) => {
    ref.current = j;
    setJugadorState(j);
    writeStoredJugador(j ? { refreshToken: j.refreshToken } : null);
  }, []);
  const fromAuth = useCallback(async (auth) => {
    const base = { id: auth.user.id, email: auth.user.email || null, phone: auth.user.phone || null, ...authFields(auth) };
    const rows = await supabaseTable(`jugadores?id=eq.${base.id}&select=*`, { accessToken: base.accessToken });
    return { ...base, perfil: rows?.[0] || null };
  }, []);

  useEffect(() => {
    const stored = readStoredJugador();
    if (!stored?.refreshToken) return;
    supabaseRefreshOnce(stored.refreshToken).then(fromAuth).then(setJugador).catch((err) => { if (err.expired) writeStoredJugador(null); });
  }, [fromAuth, setJugador]);

  /* Token vigente para llamar a la base como el jugador */
  const token = useCallback(async () => {
    const j = ref.current;
    if (!j) throw Object.assign(new Error("sin_sesion"), { code: "sin_sesion" });
    if (Date.now() < j.expiresAt - 6 * 60000) return j.accessToken;
    try {
      const next = { ...j, ...authFields(await supabaseRefreshOnce(j.refreshToken)) };
      setJugador(next);
      return next.accessToken;
    } catch (err) {
      if (err.expired) setJugador(null);
      throw Object.assign(err, { code: "sin_sesion" });
    }
  }, [setJugador]);

  const login = useCallback(async (auth) => { const j = await fromAuth(auth); setJugador(j); return j; }, [fromAuth, setJugador]);
  const savePerfil = useCallback(async (perfil) => {
    const accessToken = await token();
    const rows = await supabaseTable("jugadores?on_conflict=id", {
      method: "POST", accessToken, prefer: "resolution=merge-duplicates,return=representation",
      body: { id: ref.current.id, ...perfil },
    });
    setJugador({ ...ref.current, perfil: rows[0] });
  }, [token, setJugador]);
  // Después de completar la cuenta (ver completar_cuenta): vuelve a leer sus datos
  const recargarPerfil = useCallback(async () => {
    const accessToken = await token();
    const rows = await supabaseTable(`jugadores?id=eq.${ref.current.id}&select=*`, { accessToken });
    const next = { ...ref.current, perfil: rows?.[0] || null };
    setJugador(next);
    return next;
  }, [token, setJugador]);
  const logout = useCallback(() => {
    const j = ref.current;
    setJugador(null);
    if (j) fetch(`${SUPABASE_URL}/auth/v1/logout`, { method: "POST", headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${j.accessToken}` } }).catch(() => {});
  }, [setJugador]);

  return useMemo(() => ({ jugador, token, login, savePerfil, recargarPerfil, logout }), [jugador, token, login, savePerfil, recargarPerfil, logout]);
}

/* Link de WhatsApp con un mensaje ya escrito */
const waLink = (telefono, texto) => `https://wa.me/${telefono}?text=${encodeURIComponent(texto)}`;

const INSCRIPCION_ERRORES = {
  inscripciones_cerradas: "Las inscripciones de este torneo están cerradas.",
  categoria_invalida: "Elegí una categoría válida.",
  cupo_completo: "El cupo de esa categoría ya está completo.",
  datos_invalidos: "Revisá los nombres: tienen que tener entre 3 y 80 letras.",
  telefono_invalido: "Revisá el WhatsApp: tiene que ser un número de Argentina con característica.",
  duplicada: "Ya hay una inscripción con ese WhatsApp en esta categoría.",
  no_autorizado: "No tenés permiso para esta inscripción.",
  ya_resuelta: "Esta inscripción ya fue aceptada o rechazada.",
  partidos_generados: "Los partidos de esa categoría ya están generados: no se pueden sumar inscriptos.",
  torneo_no_encontrado: "No se encontró el torneo de esta inscripción.",
  disponibilidad_invalida: "Marcá al menos un día en que puedan jugar, con un horario válido.",
};
const inscripcionErrorText = (e) => INSCRIPCION_ERRORES[e?.code] || "No se pudo completar. Probá de nuevo en un rato.";

/* WhatsApp argentino a formato internacional sin signos (549 + característica + número), el que usa
   wa.me. Acepta cómo lo escribe la gente: con +54, con 9, con 0 adelante o con 15. Devuelve null si
   no se puede armar un número válido. */
function normalizeArPhone(input) {
  let d = String(input || "").replace(/\D/g, "");
  if (d.startsWith("549") && d.length === 13) return d;
  if (d.startsWith("54")) d = d.slice(2);
  if (d.startsWith("9") && d.length === 11) d = d.slice(1);
  if (d.startsWith("0")) d = d.slice(1);
  if (d.length === 12) {
    for (const pos of [2, 3, 4]) {
      if (d.slice(pos, pos + 2) === "15") { d = d.slice(0, pos) + d.slice(pos + 2); break; }
    }
  }
  return d.length === 10 ? "549" + d : null;
}

function formatArPhone(normalized) {
  return normalized ? `+54 9 ${normalized.slice(3)}` : "";
}

/* Cupo de una categoría (el Súper 8 es siempre de 8); null = sin límite */
function categoryCupo(category) {
  if (isSuper8(category)) return SUPER8_SIZE;
  return Number.isInteger(category.cupo) && category.cupo > 0 ? category.cupo : null;
}

/* Un Súper 8 con los partidos ya generados no admite más inscriptos */
function categoryAcceptsRegistrations(category) {
  return !(isSuper8(category) && categoryGroupsCount(category) > 0);
}

/* Parejas anotadas y grupos armados de una categoría. En la parte pública, la portada trabaja con el
   resumen de cada torneo (ver tournamentSummary), que trae las cuentas pero no las parejas. */
function categoryPairsCount(category) {
  return category._pairsCount ?? (category.pairs || []).length;
}
function categoryGroupsCount(category) {
  return category._groupsCount ?? (category.groups || []).length;
}

/* Lugares libres: cuentan todas las parejas anotadas (a mano o aceptadas). null = sin límite */
function categorySpotsLeft(category) {
  const cupo = categoryCupo(category);
  return cupo == null ? null : Math.max(0, cupo - categoryPairsCount(category));
}

/* Abre o cierra las inscripciones de un torneo. Si se cierran después de haber estado abiertas,
   queda marcado (inscripcionesCerradas) para mostrar el cartel "Inscripciones cerradas" en lugar
   del botón; un torneo que nunca las tuvo no muestra nada. */
function withRegistrationOpen(t, open) {
  return { ...t, inscripcionesAbiertas: open, inscripcionesCerradas: !open && !!(t.inscripcionesAbiertas || t.inscripcionesCerradas) };
}

/* Estado de las inscripciones de un torneo para la vista pública: "abierto", "completo" (todas las
   categorías llenas), "cerradas" (el organizador las cerró: cartel) o "cerrado" (nunca tuvo, o ya
   terminó: no se muestra nada) */
function registrationStatus(t0) {
  if (isInfoOnly(t0)) return "cerrado";
  const t = withAutoStatus(t0); // empezado el torneo, las inscripciones quedan cerradas
  if (t.status === STATUS.FINALIZADO) return "cerrado";
  // Tuvo inscripciones y el organizador las cerró: se muestra el cartel "Inscripciones cerradas"
  if (!t.inscripcionesAbiertas) return t.inscripcionesCerradas ? "cerradas" : "cerrado";
  const categories = (t.categories || []).filter(categoryAcceptsRegistrations);
  if (categories.length === 0) return "cerrado";
  return categories.some((c) => categorySpotsLeft(c) !== 0) ? "abierto" : "completo";
}

/* Subida de imágenes (logos, publicidades, portadas de torneo) a Supabase Storage.
   El bucket "images" tiene que existir y ser público (ver instrucciones de configuración). */
const IMAGES_BUCKET = "images";
const MAX_IMAGE_BYTES = 5 * 1024 * 1024; // 5 MB

/* Achica una foto antes de subirla: como mucho maxAncho de ancho, en JPEG (en PNG si puede tener transparencia). Así una portada ancha o una
   foto de la galería se ve nítida y carga rápido en el celular. Los GIF y SVG se suben como están. */
async function achicarImagen(file, maxAncho) {
  if (!maxAncho || /gif|svg/.test(file.type) || typeof createImageBitmap !== "function") return file;
  const bitmap = await createImageBitmap(file).catch(() => null);
  if (!bitmap) return file;
  if (bitmap.width <= maxAncho && file.size <= 1.5 * 1024 * 1024) { bitmap.close?.(); return file; }
  const escala = Math.min(1, maxAncho / bitmap.width);
  const canvas = document.createElement("canvas");
  canvas.width = Math.round(bitmap.width * escala);
  canvas.height = Math.round(bitmap.height * escala);
  canvas.getContext("2d").drawImage(bitmap, 0, 0, canvas.width, canvas.height);
  bitmap.close?.();
  // Los PNG y WEBP pueden tener fondo transparente (logos): se guardan en PNG para no quedar con fondo negro
  const conAlfa = /png|webp/.test(file.type);
  const tipo = conAlfa ? "image/png" : "image/jpeg";
  const blob = await new Promise((res) => canvas.toBlob(res, tipo, 0.85));
  return blob ? new File([blob], (file.name || "foto").replace(/\.[^.]+$/, "") + (conAlfa ? ".png" : ".jpg"), { type: tipo }) : file;
}

async function uploadImageToSupabase(original, accessToken, folder = "misc", { maxAncho = null } = {}) {
  if (!accessToken) throw new Error("Tenés que iniciar sesión de nuevo para subir imágenes.");
  if (!original.type || !original.type.startsWith("image/")) throw new Error("El archivo tiene que ser una imagen.");
  if (original.size > (maxAncho ? 20 : 5) * 1024 * 1024) throw new Error(`La imagen pesa demasiado (máximo ${maxAncho ? 20 : 5} MB).`);
  const file = await achicarImagen(original, maxAncho);
  if (file.size > MAX_IMAGE_BYTES) throw new Error("La imagen pesa demasiado (máximo 5 MB).");
  const extMatch = /\.([a-zA-Z0-9]+)$/.exec(file.name || "");
  const ext = (extMatch ? extMatch[1] : "jpg").toLowerCase().replace(/[^a-z0-9]/g, "") || "jpg";
  const path = `${folder}/${uid()}${Date.now().toString(36)}.${ext}`;
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/${IMAGES_BUCKET}/${path}`, {
    method: "POST",
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": file.type,
      "x-upsert": "false",
    },
    body: file,
  });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data.message || data.error || "No se pudo subir la imagen.");
  }
  return `${SUPABASE_URL}/storage/v1/object/public/${IMAGES_BUCKET}/${path}`;
}

const STATUS = {
  PROXIMO: "Próximo",
  EN_CURSO: "En curso",
  FINALIZADO: "Finalizado",
};


/* ---------- Tipo de torneo ---------- */

/* Cada torneo es de uno de tres tipos, que se elige al crearlo (y se puede cambiar después):
   - Clásico: zonas + llave final, partidos por sets, con grilla de horarios.
   - Súper 8: cada categoría es un cuadro fijo de 8 jugadores sueltos (Individual) u 8 parejas
     (Por Parejas) que termina en tabla de posiciones. Un solo set a los games que elija el organizador.
   - Americano: zonas + llave final en un solo día, con un set único a 7 o a 9 games. Usa la grilla
     de horarios (canchas, horario de arranque y tiempo entre partidos se piden al crearlo).
   El Súper 8 no usa la grilla de horarios: los partidos se juegan uno atrás del otro.
   En los formatos de set único, si llegan a N-1 iguales se define con un tie break a 7 puntos con
   diferencia de 2 y el set queda N a N-1 (7-6 jugando a 7, 9-8 jugando a 9). */
const TOURNAMENT_TYPE_LABEL = { clasico: "Clásico", super8: "Súper 8", americano: "Americano" };
const SUPER8_MODE_LABEL = { individual: "Individual", parejas: "Por Parejas" };
const SUPER8_GAMES_OPTIONS = [4, 5, 6, 7, 8, 9];
const AMERICANO_GAMES_OPTIONS = [7, 9];

function singleSetMatchFormat(type, games) {
  return { type, setsToPlay: 1, gamesPerSet: games, setTiebreak: true, finalSuperTiebreak: false };
}

function isSingleSetFormat(format) {
  return format?.type === "americano" || format?.type === "super8";
}

/* Torneos creados antes de que existiera el tipo: son Clásicos, salvo los que ya tenían el
   formato de partido Americano. */
function tournamentType(t) {
  return t.type || (t.matchFormat?.type === "americano" ? "americano" : "clasico");
}

function tournamentUsesSchedule(t) {
  return tournamentType(t) !== "super8";
}

/* Configuración elegible del tipo de torneo: { type, super8Mode, games } */
function tournamentConfig(t) {
  const type = tournamentType(t);
  return { type, super8Mode: type === "super8" ? t.super8Mode : null, games: isSingleSetFormat(t.matchFormat) ? t.matchFormat.gamesPerSet : null };
}

function tournamentConfigIsComplete(config) {
  if (config.type === "super8") return !!config.super8Mode && SUPER8_GAMES_OPTIONS.includes(config.games);
  if (config.type === "americano") return AMERICANO_GAMES_OPTIONS.includes(config.games);
  return config.type === "clasico";
}

/* Formato de las categorías de un torneo según su tipo (ver CATEGORY_FORMAT_LABEL) */
function categoryFormatForConfig(config) {
  return config.type === "super8" ? `super8_${config.super8Mode}` : "zonas";
}

function newCategory(name, categoryFormat) {
  return { id: uid(), name, pairs: [], groups: [], bracket: null, ...(categoryFormat !== "zonas" ? { format: categoryFormat, teams: [] } : {}) };
}

/* Aplica una configuración de tipo a un torneo. Si cambia el formato de las categorías (pasar a o
   desde Súper 8, o de Individual a Por Parejas), las categorías se adaptan; eso solo se permite
   mientras ninguna tenga partidos armados (ver tournamentConfigChangeBlocked). */
function withTournamentConfig(t, config) {
  const matchFormat = config.type === "clasico"
    ? (isSingleSetFormat(t.matchFormat) ? { ...DEFAULT_MATCH_FORMAT } : t.matchFormat || { ...DEFAULT_MATCH_FORMAT })
    : singleSetMatchFormat(config.type, config.games);
  const prev = tournamentConfig(t);
  const categoriesChange = prev.type !== config.type || prev.super8Mode !== config.super8Mode;
  const categoryFormat = categoryFormatForConfig(config);
  const categories = !categoriesChange ? t.categories : t.categories.map((c) => {
    if ((c.format || "zonas") === categoryFormat) return c;
    const { format, teams, ...rest } = c;
    return categoryFormat === "zonas" ? rest : { ...rest, format: categoryFormat, teams: [] };
  });
  // Solo el Clásico suma para un circuito
  const circuitId = config.type === "clasico" ? t.circuitId || null : null;
  return { ...t, type: config.type, super8Mode: config.type === "super8" ? config.super8Mode : null, matchFormat, categories, circuitId };
}

/* Cambiar el formato de una categoría con partidos ya armados rompería esos partidos */
function tournamentConfigChangeBlocked(t, config) {
  const categoryFormat = categoryFormatForConfig(config);
  return t.categories.some((c) => (c.format || "zonas") !== categoryFormat && (c.groups.length > 0 || c.bracket));
}

/* ---------- Contenido público que carga el creador ---------- */

/* Torneos "solo información": de organizadores que no usan la plataforma. Los carga el creador y
   no tienen organizador, parejas, grupos, llave, resultados ni inscripciones. Traen infoOnly: true,
   venueLogoUrl, organizerName (opcional) y sus días en playDates. */
function isInfoOnly(t) {
  return !!t?.infoOnly;
}

/* ¿Se ve en la página pública? Los torneos nuevos nacen ocultos (publico: false) y el organizador los
   publica desde Configuración (o el creador desde su panel). Los que ya existían antes de esta opción
   no tienen el campo y siguen públicos. */
const esPublico = (t) => t?.publico !== false;

/* Arranque del torneo: el primer día de juego a su hora de inicio (Argentina); sin días, la fecha del torneo */
function tournamentStartMs(t) {
  const first = [...(t.playDates || [])].filter((d) => d?.date).sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0))[0];
  const date = first?.date || t.date;
  if (!date) return null;
  const ms = Date.parse(`${date}T${first?.from || "00:00"}:00-03:00`);
  return Number.isNaN(ms) ? null : ms;
}

const anyMatch = (t, test) => (t.categories || []).some((c) => (c.groups || []).some((g) => (g.matches || []).some(test)) || (c.bracket || []).some((round) => round.some(test)));

/* ¿Ya empezó? Llegó la hora del primer día, o hay algún resultado o partido en curso */
function tournamentStarted(t, ahora = Date.now()) {
  const start = tournamentStartMs(t);
  return (start != null && ahora >= start) || tournamentProgress(t).played > 0 || tournamentHasScores(t) || anyMatch(t, (m) => m.liveStatus === "en_curso");
}

/* ¿Terminó? Cada categoría jugó su final (o, en el Súper 8, todos sus partidos). Con el resumen de
   la portada no se sabe: lo decide el estado guardado */
function tournamentFinished(t) {
  const cats = t.categories || [];
  if (t._light || cats.length === 0) return false;
  return cats.every((c) => {
    if (isSuper8(c)) {
      const ms = (c.groups || []).flatMap((g) => g.matches || []);
      return ms.length > 0 && ms.every((m) => matchIsPlayed(m, t.matchFormat));
    }
    if (!c.bracket || c.bracket.length === 0) return false;
    const { winners } = walkBracket(c.bracket, t.matchFormat);
    return !!winners[winners.length - 1]?.[0];
  });
}

/* El estado se sigue solo: Próximo pasa a En curso cuando arranca (por la hora o con el primer resultado)
   y a Finalizado cuando se juegan todas las finales. Al empezar se cierran las inscripciones. Lo que el
   organizador elige a mano adelante (En curso antes de hora, Finalizado) se respeta. */
function withAutoStatus(t, ahora = Date.now()) {
  if (!t || isInfoOnly(t)) return t;
  let n = t;
  if (n.status === STATUS.PROXIMO && tournamentStarted(n, ahora)) n = { ...n, status: STATUS.EN_CURSO };
  if (n.status === STATUS.EN_CURSO && tournamentFinished(n)) n = { ...n, status: STATUS.FINALIZADO };
  if (n.inscripcionesAbiertas && n.status !== STATUS.PROXIMO) n = withRegistrationOpen(n, false);
  return n;
}

/* Estado de un torneo para mostrar. Los informativos no los maneja nadie, así que el estado sale de
   sus fechas: antes del primer día es Próximo, hasta el último En curso, después Finalizado. Los
   gestionados, el que eligió el organizador con el avance automático (ver withAutoStatus). */
function tournamentStatusOf(t) {
  if (!isInfoOnly(t)) return withAutoStatus(t).status;
  const dates = (t.playDates || []).map((d) => d.date).sort();
  if (dates.length === 0) return STATUS.PROXIMO;
  const today = todayISO();
  if (today < dates[0]) return STATUS.PROXIMO;
  if (today > dates[dates.length - 1]) return STATUS.FINALIZADO;
  return STATUS.EN_CURSO;
}

/* Días de un torneo informativo en una línea: "Sáb 04/10 · 09:00 a 20:00 — Dom 05/10 · 09:00 a 18:00" */
function playDatesSummary(playDates) {
  return (playDates || []).map((d) => `${formatDateShort(d.date)} · ${d.from} a ${d.to}`).join(" — ");
}

const WEEKDAY_FULL = ["Domingo", "Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado"];
const WEEKDAY_ORDER = [1, 2, 3, 4, 5, 6, 0]; // la semana arranca el lunes

/* Horario semanal de un profe agrupado y legible: los días con el mismo horario van juntos.
   [{weekday:2,...18-21},{weekday:4,...18-21}] → ["Martes y Jueves · 18:00 a 21:00"] */
function weeklyScheduleLines(availability) {
  const groups = new Map();
  [...(availability || [])]
    .sort((a, b) => WEEKDAY_ORDER.indexOf(a.weekday) - WEEKDAY_ORDER.indexOf(b.weekday))
    .forEach((a) => {
      const key = `${a.from} a ${a.to}`;
      groups.set(key, [...(groups.get(key) || []), WEEKDAY_FULL[a.weekday]]);
    });
  const joinDays = (days) => (days.length === 1 ? days[0] : `${days.slice(0, -1).join(", ")} y ${days[days.length - 1]}`);
  return [...groups.entries()].map(([hours, days]) => `${joinDays(days)} · ${hours}`);
}

/* Instagram: acepta usuario (con o sin @) o link, y devuelve { url, handle } */
function instagramLink(input) {
  const raw = String(input || "").trim();
  if (!raw) return null;
  const handle = raw.replace(/^(https?:\/\/)?(www\.)?instagram\.com\//i, "").replace(/^@/, "").replace(/[/?#].*$/, "");
  return handle ? { url: `https://instagram.com/${handle}`, handle: `@${handle}` } : null;
}

/* Un set único a N games está completo y bien cargado si el ganador llegó a N y el otro quedó
   en N-1 o menos (N a N-1 solo se da ganando el tie break en N-1 iguales). */
function singleSetIsValid(a, b, games) {
  const hi = Math.max(a, b), lo = Math.min(a, b);
  return hi === games && lo <= games - 1;
}
const WEEKDAY_LABEL = ["Dom", "Lun", "Mar", "Mié", "Jue", "Vie", "Sáb"];

function formatDateShort(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  return `${WEEKDAY_LABEL[d.getDay()]} ${d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit" })}`;
}

const WEEKDAY_LONG = ["Domingo", "Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado"];
/* "Viernes 30/10", para los títulos de cada día en la página de un evento */
function formatDateLong(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  return `${WEEKDAY_LONG[d.getDay()]} ${d.toLocaleDateString("es-AR", { day: "2-digit", month: "2-digit" })}`;
}

/* "14:00" -> "14 hs", "17:30" -> "17:30 hs" (como en los flyers) */
function formatHour(time) {
  if (!time) return "";
  return `${time.endsWith(":00") ? String(Number(time.slice(0, 2))) : time} hs`;
}

/* Hora de inicio de un torneo: la que cargó el organizador (torneos de un evento) o, en un
   Americano, la de arranque de su único día. null si no tiene. */
function tournamentStartTime(t) {
  if (t.startTime) return t.startTime;
  if (tournamentType(t) === "americano") return t.playDates?.[0]?.from || null;
  return null;
}

/* "Vie 30/10 · 14 hs" (o solo la fecha si no tiene hora) */
function tournamentWhenLabel(t) {
  const time = tournamentStartTime(t);
  return `${formatDateShort(t.date)}${time ? ` · ${formatHour(time)}` : ""}`;
}

/* Orden de los torneos de un evento: por día y después por hora de inicio */
function compareByStart(a, b) {
  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
  return (tournamentStartTime(a) || "") < (tournamentStartTime(b) || "") ? -1 : (tournamentStartTime(a) || "") > (tournamentStartTime(b) || "") ? 1 : 0;
}

/* Nombre de una cancha para mostrar. Un Clásico con varias sedes (t.venues: [{ id, name, courts }])
   numera sus canchas de corrido (sede 1: canchas 1 a 3, sede 2: 4 y 5...) para armar los horarios,
   y acá se traduce: la 4 es "Club Norte · Cancha 1". Sin sedes: "Cancha 4". */
function courtName(t, court, short = false) {
  const label = short ? "C" : "Cancha ";
  if ((t?.venues || []).length < 2) return `${label}${court}`;
  let offset = 0;
  for (const v of t?.venues || []) {
    if (court <= offset + v.courts) return `${v.name} · ${label}${court - offset}`;
    offset += v.courts;
  }
  return `${label}${court}`;
}

/* "Cada grupo en una sola sede": solo tiene sentido con dos sedes o más. Viene activada (como se
   juega en los circuitos grandes) y el organizador la puede apagar en Horarios. */
function groupsInOneVenue(t) {
  return (t?.venues || []).length >= 2 && t.groupsOneVenue !== false;
}

/* Grupos que quedaron repartidos en más de una sede (con "cada grupo en una sola sede" activada no
   entraban en una sola): "6TA Grupo B" */
function groupsSplitAcrossVenues(t) {
  if (!groupsInOneVenue(t)) return [];
  return (t.categories || []).flatMap((c) => (c.groups || [])
    .filter((g) => new Set(g.matches.filter((m) => m.schedule).map((m) => courtVenueIndex(t, m.schedule.court))).size > 1)
    .map((g) => `${c.name} ${g.name}`));
}

/* Sede de cada cancha y días y horarios en que se usa cada sede: ver venueDays.js */

/* Lista de Complejos (la que carga el administrador), para elegir las sedes de un torneo y tomar
   su logo en la imagen del fixture sin pasarla de componente en componente */
const ComplexesContext = React.createContext([]);
/* El plan de la cuenta y de sus complejos (ver mi_plan en 20261034/20261036): { filas, recargar } */
const MiPlanContext = React.createContext({ filas: [], recargar: () => {} });
/* Funciones en prueba (ver 20261037_funciones.sql): las prende el creador. Apagadas, no se ven. */
const FUNCIONES_APAGADAS = { reservas: false, cuentas: false, cantina: false };
const FuncionesContext = React.createContext(FUNCIONES_APAGADAS);
async function fetchFunciones() {
  try {
    const rows = (await supabaseTable("funciones?select=clave,activa")) || [];
    return { ...FUNCIONES_APAGADAS, ...Object.fromEntries(rows.map((r) => [r.clave, !!r.activa])) };
  } catch { return FUNCIONES_APAGADAS; }
}

/* El torneo que se está mostrando, para que las piezas chicas (etiqueta de horario, selector de
   cancha) puedan nombrar las canchas con su sede sin recibir el torneo entero */
const CourtNamesContext = React.createContext(null);
function useCourtName() {
  const t = React.useContext(CourtNamesContext);
  return (court) => courtName(t, court);
}

/* Cambia día, hora de inicio y canchas de un torneo. En el Americano y el Clásico, el día y la
   hora son también los de la grilla de horarios (su primer día de juego). */
function withTournamentStart(t, { date, startTime, courtsCount }) {
  const next = { ...t, date, startTime: startTime || null, courtsCount };
  if (tournamentType(t) !== "super8" && startTime) {
    const [first, ...rest] = t.playDates || [];
    next.playDates = [{ date, from: startTime, to: first?.to || "23:59" }, ...rest.filter((d) => d.date !== date)];
  }
  return next;
}

/* Round robin: todos contra todos dentro de un grupo */
function buildRoundRobin(pairIds) {
  const matches = [];
  for (let i = 0; i < pairIds.length; i++) {
    for (let j = i + 1; j < pairIds.length; j++) {
      matches.push({ id: uid(), pairA: pairIds[i], pairB: pairIds[j], sets: [] });
    }
  }
  return matches;
}

/* Arma los partidos de un grupo. Con 3 parejas (o cualquier tamaño distinto de 4) es todos contra
   todos. Con 4 parejas, se sortean los rivales (A vs B, C vs D) y recién cuando esos dos resultados
   están cargados se arman solos los cruces de ganadores y de perdedores. */
/* Mueve una pareja de un grupo de zona a otro (edición manual post-sorteo) y reconstruye los
   partidos de ambos grupos afectados desde cero (se pierden los resultados ya cargados en esos
   dos grupos, por eso esto solo debe ofrecerse mientras ningún partido de esos grupos esté jugado). */
function moveGroupPair(groups, pairId, fromGroupId, toGroupId) {
  return groups.map((g) => {
    if (g.id === fromGroupId) {
      const pairIds = g.pairIds.filter((id) => id !== pairId);
      const built = buildGroupMatches(pairIds);
      return { ...g, pairIds, format: built.format, matches: built.matches };
    }
    if (g.id === toGroupId) {
      const pairIds = [...g.pairIds, pairId];
      const built = buildGroupMatches(pairIds);
      return { ...g, pairIds, format: built.format, matches: built.matches };
    }
    return g;
  });
}

/* `keepOrder`: el armado automático ya eligió los cruces del grupo de 4 (los dos primeros contra
   sí y los dos últimos contra sí, entre parejas con horario en común), así que no se sortean. */
function buildGroupMatches(pairIds, keepOrder = false) {
  if (pairIds.length === 4) {
    const shuffled = keepOrder ? [...pairIds] : [...pairIds].sort(() => Math.random() - 0.5);
    return {
      format: "bracket4",
      matches: [
        { id: uid(), pairA: shuffled[0], pairB: shuffled[1], sets: [], stage: "r1" },
        { id: uid(), pairA: shuffled[2], pairB: shuffled[3], sets: [], stage: "r1" },
        { id: uid(), pairA: null, pairB: null, sets: [], stage: "ganadores" },
        { id: uid(), pairA: null, pairB: null, sets: [], stage: "perdedores" },
      ],
    };
  }
  return { format: "roundrobin", matches: buildRoundRobin(pairIds) };
}

/* ---------- Formato Súper 8 ---------- */

/* Una categoría puede jugarse con el sistema clásico (zonas + llave) o en alguna de las dos
   variantes del Súper 8: un cuadro fijo de partidos sin eliminación que termina en tabla de posiciones.
   - Individual: 8 jugadores sueltos; las parejas rotan para que cada uno juegue una vez con cada
     otro como compañero y dos veces contra cada otro como rival (14 partidos, 7 rondas de 2).
   - Parejas Fijas: 8 parejas armadas, todos contra todos (28 partidos, 7 rondas de 4). */
const CATEGORY_FORMAT_LABEL = {
  zonas: "Zonas + llave",
  super8_individual: "Súper 8 Individual",
  super8_parejas: "Súper 8 por Parejas Fijas",
};
/* Duración predeterminada de un partido de torneo clásico, en minutos (arma la grilla de horarios) */
const DEFAULT_MATCH_DURATION = 60;
const SUPER8_SIZE = 8;
/* Canchas del Súper 8: con 8 jugadores entran hasta 2 partidos a la vez y con 8 parejas hasta 4.
   Al crearlo se propone 1 cancha para el Individual y 2 para el de Parejas. */
const super8MaxCourts = (mode) => (mode === "individual" ? 2 : 4);
const super8DefaultCourts = (mode) => (mode === "individual" ? 1 : 2);

function isSuper8(category) {
  return category?.format === "super8_individual" || category?.format === "super8_parejas";
}

/* Turnos de juego de un Súper 8 con varias canchas: los partidos de una misma ronda pueden ir a
   la vez (nadie juega dos partidos en la misma ronda), así que cada ronda se reparte en turnos de
   a tantos partidos como canchas haya. En el Individual entran hasta 2 a la vez (8 jugadores = 2
   partidos por ronda) y por Parejas hasta 4. Con 1 cancha queda un partido por turno, uno atrás
   del otro. Devuelve [{ round, matches: [{ m, court }] }]. */
function super8Turns(matches, courtsCount) {
  const rounds = [];
  matches.forEach((m, i) => {
    const r = m.round || i + 1;
    let round = rounds.find((x) => x.round === r);
    if (!round) { round = { round: r, matches: [] }; rounds.push(round); }
    round.matches.push(m);
  });
  const turns = [];
  rounds.forEach(({ round, matches: list }) => {
    const perTurn = Math.max(1, Math.min(courtsCount || 1, list.length));
    for (let i = 0; i < list.length; i += perTurn) {
      turns.push({ round, matches: list.slice(i, i + perTurn).map((m, j) => ({ m, court: j + 1 })) });
    }
  });
  return turns;
}

/* Round robin por el método del círculo: el primero queda fijo y el resto rota un lugar por ronda.
   Devuelve las rondas como listas de cruces [a, b]. Con 8 parejas da 7 rondas de 4 partidos. */
function buildCircleRounds(ids) {
  const n = ids.length;
  let arr = [...ids];
  const rounds = [];
  for (let r = 0; r < n - 1; r++) {
    const round = [];
    for (let i = 0; i < n / 2; i++) round.push([arr[i], arr[n - 1 - i]]);
    rounds.push(round);
    arr = [arr[0], arr[n - 1], ...arr.slice(1, n - 1)];
  }
  return rounds;
}

/* Rondas del Súper 8 Individual para n jugadores (n múltiplo de 4). Cada ronda es una lista de
   partidos [[a1, a2], [b1, b2]] donde juegan todos, y en el total cada jugador es compañero de
   cada otro exactamente una vez y rival exactamente dos veces.
   Construcción cíclica: el jugador 0 queda fijo y los demás se numeran módulo n-1. Se busca una
   ronda base que, sumando 1 a cada número ronda tras ronda, cumpla las dos condiciones. La búsqueda
   recorre siempre el mismo orden, así que para la misma cantidad de jugadores sale siempre la misma
   tabla (con 8 jugadores tarda unos milisegundos). */
function buildSuper8IndividualRounds(ids) {
  const n = ids.length;
  if (n < 4 || n % 4 !== 0) return null;
  const m = n - 1;
  const shift = (x, r) => (x === 0 ? 0 : ((x - 1 + r) % m) + 1);
  const key = (a, b) => (a < b ? a * n + b : b * n + a);
  const develop = (base) => Array.from({ length: m }, (_, r) => base.map(([t1, t2]) => [t1.map((x) => shift(x, r)), t2.map((x) => shift(x, r))]));
  const isValid = (rounds) => {
    const partners = new Set();
    const opponents = new Map();
    for (const round of rounds) {
      for (const [t1, t2] of round) {
        for (const t of [t1, t2]) {
          const k = key(t[0], t[1]);
          if (partners.has(k)) return false;
          partners.add(k);
        }
        for (const x of t1) for (const y of t2) {
          const k = key(x, y), count = (opponents.get(k) || 0) + 1;
          if (count > 2) return false;
          opponents.set(k, count);
        }
      }
    }
    return true;
  };
  // Arma la ronda base de a 4 jugadores (el primero libre + otros 3), probando los 3 repartos de compañeros
  const search = (free, base) => {
    if (free.length === 0) {
      const rounds = develop(base);
      return isValid(rounds) ? rounds : null;
    }
    const [a, ...rest] = free;
    for (let i = 0; i < rest.length; i++) for (let j = i + 1; j < rest.length; j++) for (let k = j + 1; k < rest.length; k++) {
      const quad = [a, rest[i], rest[j], rest[k]];
      const others = rest.filter((_, x) => x !== i && x !== j && x !== k);
      for (const p of [1, 2, 3]) {
        const t1 = [quad[0], quad[p]];
        const t2 = quad.filter((_, x) => x !== 0 && x !== p);
        base.push([t1, t2]);
        const found = search(others, base);
        if (found) return found;
        base.pop();
      }
    }
    return null;
  };
  const rounds = search(Array.from({ length: n }, (_, i) => i), []);
  return rounds && rounds.map((round) => round.map(([t1, t2]) => [t1.map((x) => ids[x]), t2.map((x) => ids[x])]));
}

/* Arma la zona única del Súper 8 con los jugadores/parejas ya numerados (orderedIds[0] = el 1, etc.).
   En el Individual, cada lado de un partido es un "equipo" de 2 jugadores que se guarda en
   category.teams; los partidos apuntan a esos equipos en pairA/pairB, así el resto de la app
   (resultados, WO, horarios) los trata igual que a una pareja. */
function buildSuper8Group(format, orderedIds) {
  const teams = [];
  let matches;
  if (format === "super8_individual") {
    const rounds = buildSuper8IndividualRounds(orderedIds);
    if (!rounds) return null;
    const teamFor = (playerIds) => {
      const team = { id: uid(), playerIds };
      teams.push(team);
      return team.id;
    };
    matches = rounds.flatMap((round, ri) => round.map(([t1, t2]) => ({ id: uid(), pairA: teamFor(t1), pairB: teamFor(t2), sets: [], round: ri + 1 })));
  } else {
    matches = buildCircleRounds(orderedIds).flatMap((round, ri) => round.map(([a, b]) => ({ id: uid(), pairA: a, pairB: b, sets: [], round: ri + 1 })));
  }
  return { group: { id: uid(), name: "Súper 8", pairIds: orderedIds, format: "super8", matches }, teams };
}

/* Parejas/jugadores de la categoría por id, sumando los equipos del Súper 8 Individual (cuyo nombre
   se arma con el de sus dos jugadores, para que un cambio de nombre se refleje solo). */
function categoryEntitiesById(category) {
  const map = Object.fromEntries(category.pairs.map((p) => [p.id, p]));
  (category.teams || []).forEach((t) => {
    map[t.id] = { id: t.id, name: t.playerIds.map((pid) => map[pid]?.name || "—").join(" - ") };
  });
  return map;
}

/* Quiénes juegan de verdad en un lado de un partido: los dos jugadores si es un equipo del Súper 8
   Individual, o la pareja misma en cualquier otro caso. */
function sideParticipantIds(category, sideId) {
  const team = (category?.teams || []).find((t) => t.id === sideId);
  return team ? team.playerIds : [sideId];
}

/* Para la tabla de posiciones del Súper 8 Individual: cada partido de equipos se parte en dos
   "partidos" jugador contra jugador con el mismo resultado, así computeStandings le suma a cada
   jugador lo que hizo su equipo (sin contarlo doble). */
function super8IndividualStandingsGroup(category, group) {
  const teamsById = Object.fromEntries((category.teams || []).map((t) => [t.id, t]));
  const matches = group.matches.flatMap((m) => {
    const tA = teamsById[m.pairA], tB = teamsById[m.pairB];
    if (!tA || !tB) return [];
    return [0, 1].map((i) => ({
      ...m,
      pairA: tA.playerIds[i],
      pairB: tB.playerIds[i],
      walkover: m.walkover ? (m.walkover === m.pairA ? tA.playerIds[i] : tB.playerIds[i]) : null,
      retired: m.retired ? (m.retired === m.pairA ? tA.playerIds[i] : tB.playerIds[i]) : null,
    }));
  });
  return { ...group, matches };
}



/* Avance del torneo: cuántos partidos ya se jugaron sobre el total (grupos + llave con ambas parejas definidas) */
/* ¿Hay algún resultado cargado en el torneo, aunque sea a medias? */
function tournamentHasScores(t) {
  return (t.categories || []).some((c) => (c.groups || []).some((g) => g.matches.some(matchHasScore)) || (c.bracket || []).some((round) => round.some(matchHasScore)));
}

/* Resumen de un torneo para la parte pública (columna resumen de la tabla torneos, ver
   supabase/migrations/20261009_tabla_torneos.sql): el torneo sin las parejas, los grupos ni la
   llave, y con lo que la portada necesita contar. Lo arma la app en cada guardado. Con esto la
   portada, los eventos y los circuitos no bajan los torneos enteros; un torneo se baja entero
   recién cuando alguien lo abre.
   - En cada categoría: _pairsCount, _groupsCount y _placements (nombre de cada pareja y hasta
     dónde llegó, para los puntos del circuito).
   - _stats: avance (jugados / total), partidos publicados por día. */
const HEAVY_CATEGORY_FIELDS = ["pairs", "groups", "bracket", "bracketSeeding", "teams"];
function tournamentSummary(t) {
  const { categories = [], rev, _light, ...top } = t;
  const matchesByDate = {};
  collectScheduleableMatches(t).forEach((m) => {
    if (m.schedule && !m.draft) matchesByDate[m.schedule.date] = (matchesByDate[m.schedule.date] || 0) + 1;
  });
  return {
    ...top,
    categories: categories.map((c) => {
      const light = { ...c };
      HEAVY_CATEGORY_FIELDS.forEach((k) => delete light[k]);
      const names = Object.fromEntries((c.pairs || []).map((p) => [p.id, p.name]));
      const players = Object.fromEntries((c.pairs || []).filter((p) => p.players).map((p) => [p.id, p.players]));
      return {
        ...light,
        _pairsCount: (c.pairs || []).length,
        _groupsCount: (c.groups || []).length,
        _placements: isSuper8(c) || isInfoOnly(t) ? [] : categoryPlacements(c, t.matchFormat).map(({ pairId, tier }) => ({ name: names[pairId], ...(players[pairId] ? { players: players[pairId] } : {}), tier })).filter((p) => p.name),
      };
    }),
    _stats: { progress: tournamentProgress(t), matchesByDate },
  };
}

/* El torneo "liviano" que usan las pantallas públicas a partir de su resumen: las categorías con
   listas vacías (así ninguna cuenta se rompe) y las cuentas en _pairsCount, _stats, etc. Nunca se
   guarda (ver useTournamentSaver). */
function lightTournament(summary, rev) {
  return {
    ...summary,
    rev,
    _light: true,
    categories: (summary.categories || []).map((c) => ({ ...c, pairs: [], groups: [], bracket: null })),
  };
}

function tournamentProgress(t) {
  if (t._stats) return t._stats.progress; // resumen (portada)
  let total = 0, played = 0;
  if (isInfoOnly(t)) return { total, played, pct: 0 }; // los informativos no tienen partidos
  (t.categories || []).forEach((c) => {
    (c.groups || []).forEach((g) => g.matches.forEach((m) => { total++; if (matchIsPlayed(m, t.matchFormat)) played++; }));
    (c.bracket || []).forEach((round) => round.forEach((m) => {
      if (m.pairA && m.pairB) { total++; if (matchIsPlayed(m, t.matchFormat)) played++; }
    }));
  });
  return { total, played, pct: total > 0 ? Math.round((played / total) * 100) : 0 };
}


/* Estado visual de un partido para la tabla de horarios: "finalizado" se calcula solo al cargar
   resultado o walkover; "en_curso" lo marca el organizador a mano mientras no haya resultado. */
function matchDisplayStatus(m, format) {
  if (matchIsPlayed(m, format)) return "finalizado";
  if (m && m.liveStatus === "en_curso") return "en_curso";
  return "pendiente";
}

/* Chequea si una pareja (o jugador del Súper 8 Individual) ya jugó algún partido (de grupos o de la llave) dentro de la categoría */
function pairHasPlayed(category, pairId) {
  const plays = (m) => [m.pairA, m.pairB].some((side) => sideParticipantIds(category, side).includes(pairId));
  const inGroups = (category.groups || []).some((g) => g.matches.some((m) => plays(m) && matchHasScore(m)));
  const inBracket = (category.bracket || []).some((round) => round.some((m) => (m.pairA === pairId || m.pairB === pairId) && matchHasScore(m)));
  return inGroups || inBracket;
}

/* Agrega/actualiza el resultado de un set puntual dentro del array de sets de un partido */
function withSetScore(sets, setIndex, side, value) {
  const next = [...(sets || [])];
  while (next.length <= setIndex) next.push({ a: null, b: null });
  next[setIndex] = { ...next[setIndex], [side]: value };
  return next;
}


/* Cuántas parejas pasan de un grupo a la llave final: lo elige el organizador en cada grupo por
   separado (g.qualifiersCount), nunca más que las parejas que tiene el grupo. Por defecto, como en
   los cuadros FAP: de un grupo de 3 pasan 2 y de uno de 4, 3. */
const defaultQualifiersCount = (pairCount) => (pairCount >= 4 ? 3 : 2);
function groupQualifiersCount(group) {
  return Math.min(group.qualifiersCount || defaultQualifiersCount(group.pairIds.length), group.pairIds.length);
}

/* Número de cada partido de una categoría, como en los cuadros de los circuitos ("Partido 27"):
   primero los de grupos, grupo por grupo y en su orden, y después los de la llave, ronda por ronda
   y de arriba hacia abajo (los byes no se juegan y no llevan número). Se calcula, no se guarda: si
   se rearman los grupos o la llave, se vuelve a numerar. */
function categoryMatchNumbers(category) {
  const nums = new Map();
  let n = 0;
  (category.groups || []).forEach((g) => g.matches.forEach((m) => nums.set(m.id, ++n)));
  if (category.bracket) {
    const { byes } = walkBracket(category.bracket);
    category.bracket.forEach((round, ri) => round.forEach((m, mi) => { if (!isByeMatch(byes, ri, mi)) nums.set(m.id, ++n); }));
  }
  return nums;
}

/* Nombre corto de un grupo para "1A": "Grupo A" → "A" (si el grupo tiene otro nombre, el nombre) */
const groupShortName = (g) => (g.name || "").replace(/^grupo\s+/i, "");

/* De dónde viene cada pareja clasificada a la llave: { pairId: "1A" } = 1° del Grupo A */
function bracketOrigins(category, format) {
  const pairsById = Object.fromEntries((category.pairs || []).map((p) => [p.id, p]));
  const out = {};
  (category.groups || []).forEach((g) => {
    groupQualifiers(g, pairsById, format).forEach((pid, i) => { out[pid] = `${i + 1}${groupShortName(g)}`; });
  });
  return out;
}

/* Clasificados de cada grupo para la llave final: los primeros de la tabla, tantos como eligió el
   organizador (ver groupQualifiersCount). La pareja eliminada por el organizador no clasifica
   aunque el grupo pase a 3 de 4 (un W.O. solo pierde ese partido: si le dan los números, clasifica). */
function groupQualifiers(group, pairsById, format) {
  return computeStandings(group, pairsById, format)
    .filter((row) => !row.eliminated)
    .slice(0, groupQualifiersCount(group))
    .map((row) => row.pairId);
}

/* Cruces de primera ronda de la llave final con las parejas que clasificaron: el cuadro FAP de esa
   configuración (ver bracketFap.js), con cada lugar ("1° Grupo A") ocupado por la pareja que quedó
   ahí. El cuadro no depende de los resultados: es el mismo del esqueleto que se publica antes de
   que terminen los grupos, así no cambian los byes, los cruces ni los horarios. Devuelve pares
   [pairId, pairId | null] (null = bye). */
function buildKnockoutSeeding(groups, pairsById, format) {
  const qualifiers = groups.map((g) => groupQualifiers(g, pairsById, format));
  const slots = fapRound1(qualifiers.map((q) => q.length));
  if (!slots) return [];
  const ids = slots.map((s) => (s ? qualifiers[s.group][s.place - 1] : null));
  const pairs = [];
  for (let i = 0; i < ids.length; i += 2) pairs.push([ids[i], ids[i + 1]]);
  return pairs;
}

/* ¿Cambiaron los clasificados de los grupos desde que se armó la llave? (por ejemplo, porque se
   corrigió un resultado después). Compara con los cruces que daban los grupos al generarla
   (category.bracketSeeding), así los cambios hechos a mano con "Editar cruces" no cuentan; en
   llaves armadas antes de guardar eso, compara solo qué parejas están en la primera ronda.
   Devuelve null si no cambió nada, o { added, removed } con las parejas que entran y salen
   (las dos vacías si son las mismas parejas pero cambió el orden de clasificación). */
function bracketQualifiersChange(category, pairsById, format) {
  if (!category.bracket || category.bracketIsSkeleton || !(category.groups || []).length) return null;
  const current = buildKnockoutSeeding(category.groups, pairsById, format);
  const ids = (rounds) => new Set(rounds.flat().filter(Boolean));
  const before = category.bracketSeeding ? ids(category.bracketSeeding) : ids(category.bracket[0].map((m) => [m.pairA, m.pairB]));
  const now = ids(current);
  const added = [...now].filter((id) => !before.has(id));
  const removed = [...before].filter((id) => !now.has(id));
  if (added.length || removed.length) return { added, removed };
  if (category.bracketSeeding && JSON.stringify(category.bracketSeeding) !== JSON.stringify(current)) return { added: [], removed: [] };
  return null;
}

/* Llave eliminación directa a partir de una lista ordenada de pairIds (o null = BYE) */
function buildBracket(pairIds) {
  let size = 1;
  while (size < pairIds.length) size *= 2;
  const slots = [...pairIds];
  while (slots.length < size) slots.push(null);

  const round1 = [];
  for (let i = 0; i < slots.length; i += 2) {
    round1.push({ id: uid(), pairA: slots[i], pairB: slots[i + 1], sets: [] });
  }
  const rounds = [round1];
  let count = round1.length;
  while (count > 1) {
    count = count / 2;
    rounds.push(Array.from({ length: count }, () => ({ id: uid(), pairA: null, pairB: null, sets: [] })));
  }
  return propagateBracket(rounds);
}

/* Arma un esqueleto de llave SIN saber todavía qué pareja concreta clasifica a cada lugar:
   solo usa los grupos y cuántos clasificados definió el organizador en cada uno. Cada partido de
   ronda 1 lleva un label textual tipo "1° Grupo A vs 2° Grupo B" (guardado en
   placeholderA/placeholderB) en vez de pairA/pairB reales. Es el mismo cuadro FAP que usa la llave
   real (fapRound1), así cada casillero, sus byes y sus horarios siguen iguales cuando después se
   completa con las parejas. */
function buildPlaceholderBracket(groups) {
  if (!groups || groups.length === 0) return null;
  const slots = fapRound1(groups.map(groupQualifiersCount));
  if (!slots) return null;
  const label = (s) => (s ? `${s.place}° ${groups[s.group].name}` : null);
  const round1 = [];
  for (let i = 0; i < slots.length; i += 2) {
    round1.push({ id: uid(), pairA: null, pairB: null, placeholderA: label(slots[i]), placeholderB: label(slots[i + 1]), sets: [] });
  }
  const rounds = [round1];
  let count = round1.length;
  while (count > 1) {
    count = count / 2;
    rounds.push(Array.from({ length: count }, () => ({ id: uid(), pairA: null, pairB: null, sets: [] })));
  }
  return rounds;
}

/* La llave de una categoría con grupos se arma sola, en borrador:
   - Apenas hay grupos, el esqueleto con "1° Grupo A"... y sus horarios (si cambian los grupos y la
     llave todavía no tiene resultados, se vuelve a armar).
   - Cuando termina un grupo, sus lugares se completan con las parejas que clasificaron (y se
     corrigen si cambia un resultado, mientras ese cruce no se haya jugado).
   - Con todos los lugares completos deja de ser esqueleto: desde ahí, si cambian los clasificados,
     avisa y ofrece rearmarla (ver bracketQualifiersChange).
   tournament: el torneo con el que se arman los horarios (con los grupos ya ubicados). */
function withAutoBracket(tournament, category) {
  if (isSuper8(category) || !(category.groups || []).length) return category;
  const format = tournament.matchFormat;
  const hasResults = (category.bracket || []).flat().some(matchHasScore);
  let c = category;
  const skeleton = buildPlaceholderBracket(c.groups);
  if (!skeleton) return c;
  const labels = (rounds) => JSON.stringify(rounds[0].map((m) => [m.placeholderA || null, m.placeholderB || null]));
  const outdated = c.bracket && c.bracketIsSkeleton && !hasResults && labels(c.bracket) !== labels(skeleton);
  if (!c.bracket || outdated) {
    c = autoScheduleBracket(tournament, { ...c, bracket: skeleton, bracketIsSkeleton: true, bracketSeeding: null, bracketPublished: !!c.bracket && !!c.bracketPublished });
  }
  return c.bracketIsSkeleton ? fillSkeletonBracket(c, format) : c;
}

/* Lo que se deduce de los resultados, recalculado al leer un torneo: los cruces de ganadores y
   perdedores de los grupos de 4, el avance en la llave y los lugares de una llave en borrador.
   Los resultados se guardan de a partido (guardar_partidos) y esto no viaja con ellos: así cada
   celular lo calcula igual, sin importar quién cargó qué. */
function withDerivedResults(category, format) {
  if (isSuper8(category)) return category;
  const groups = (category.groups || []).map((g) => (g.format === "bracket4" && g.matches.length >= 4 ? { ...g, matches: propagateGroupBracket4(g.matches, format) } : g));
  let c = { ...category, groups };
  if (c.bracket) c = { ...c, bracket: propagateBracket(c.bracket, format) };
  if (c.bracket && c.bracketIsSkeleton && groups.length > 0) c = fillSkeletonBracket(c, format);
  return c;
}

/* Completa los lugares de la primera ronda de un esqueleto con los clasificados de los grupos que
   ya terminaron (ver withAutoBracket) */
function fillSkeletonBracket(category, format) {
  const pairsById = categoryEntitiesById(category);
  const finished = Object.fromEntries(category.groups
    .filter((g) => g.matches.length > 0 && g.matches.every((m) => matchIsPlayed(m, format)))
    .map((g) => [g.name, groupQualifiers(g, pairsById, format)]));
  const place = (label) => {
    const [, n, name] = /^(\d+)° (.+)$/.exec(label || "") || [];
    return n && finished[name] ? finished[name][Number(n) - 1] || null : null;
  };
  let changed = false;
  const round1 = category.bracket[0].map((m) => {
    if (matchHasScore(m)) return m;
    const pairA = m.placeholderA ? place(m.placeholderA) : m.pairA;
    const pairB = m.placeholderB ? place(m.placeholderB) : m.pairB;
    if (pairA === m.pairA && pairB === m.pairB) return m;
    changed = true;
    return { ...m, pairA, pairB };
  });
  const rounds = changed ? propagateBracket([round1, ...category.bracket.slice(1)], format) : category.bracket;
  const complete = rounds[0].every((m) => (!m.placeholderA || m.pairA) && (!m.placeholderB || m.pairB));
  if (!changed && !complete) return category;
  return complete
    ? { ...category, bracket: rounds, bracketIsSkeleton: false, bracketSeeding: buildKnockoutSeeding(category.groups, pairsById, format) }
    : { ...category, bracket: rounds };
}

/* Como buildBracket, pero a partir de los cruces de ronda 1 que arma buildKnockoutSeeding (las
   parejas con bye van contra un lugar vacío y pasan solas a la ronda siguiente). */
function buildSeededBracket(round1Pairs) {
  return buildBracket(round1Pairs.flat());
}



/* En un grupo de 4 parejas, arma solos los cruces de ganadores y de perdedores apenas se cargan
   los dos primeros resultados (partido 1 y partido 2 del sorteo inicial) */
function propagateGroupBracket4(matches, format) {
  const next = matches.map((m) => ({ ...m }));
  const [m1, m2] = next;
  next[2] = { ...next[2], pairA: winnerOf(m1, format), pairB: winnerOf(m2, format) };
  next[3] = { ...next[3], pairA: loserOf(m1, format), pairB: loserOf(m2, format) };
  return next;
}

/* Nombre real de cada instancia de la llave (Final, Semifinal, Cuartos, Octavos...) según cuántas
   rondas tenga en total esa llave, contando desde el final hacia atrás */
const ROUND_STAGE_NAMES = ["Final", "Semifinal", "Cuartos de Final", "Octavos de Final", "16avos de Final", "32avos de Final"];
function roundStageLabel(totalRounds, roundIndex) {
  const fromEnd = totalRounds - 1 - roundIndex;
  return ROUND_STAGE_NAMES[fromEnd] || `Ronda ${roundIndex + 1}`;
}

/* Intercambia de lugar a dos parejas dentro de la ronda 1 de la llave ya generada (para forzar
   manualmente un cruce distinto al automático). Solo tiene sentido antes de que esos partidos
   se hayan jugado; si alguno de los dos ya tiene resultado cargado, no se debería ofrecer esta
   opción en la interfaz. */
function swapBracketPairs(bracket, pairIdA, pairIdB, format) {
  const rounds = bracket.map((r) => r.map((m) => ({ ...m })));
  rounds[0].forEach((m) => {
    if (m.pairA === pairIdA) m.pairA = pairIdB;
    else if (m.pairA === pairIdB) m.pairA = pairIdA;
    if (m.pairB === pairIdA) m.pairB = pairIdB;
    else if (m.pairB === pairIdB) m.pairB = pairIdA;
  });
  return propagateBracket(rounds, format);
}

/* Completa cada ronda de la llave con los ganadores de la anterior. Solo avanza quien ganó de
   verdad (o pasó por un bye real): un lugar que espera un partido sin jugar no cuenta como bye
   (ver walkBracket) */
function propagateBracket(rounds, format) {
  return walkBracket(rounds, format).rounds;
}

/* Parejas fuera del torneo en una categoría: las que eliminó el organizador y las que se
   retiraron (RET) en algún partido */
function categoryOutPairIds(category) {
  const out = new Set((category.pairs || []).filter((p) => p.eliminated).map((p) => p.id));
  [...(category.groups || []).flatMap((g) => g.matches), ...(category.bracket || []).flat()].forEach((m) => {
    if (m.retired) out.add(m.retired);
  });
  return out;
}

/* Los partidos pendientes de una pareja que quedó fuera pasan solos a W.O. a favor del rival
   (marcados con autoWalkover). Si se la reincorpora o se deshace el RET, esos W.O. automáticos se
   sacan. Se repite hasta que no cambie nada, porque un W.O. puede completar un cruce de un grupo
   de 4 o una ronda de la llave donde esa pareja vuelve a aparecer. En el Súper 8 no se aplica. */
function withForfeits(category, format) {
  if (isSuper8(category)) return category;
  const out = categoryOutPairIds(category);
  const fix = (m) => {
    if (m.autoWalkover && !out.has(m.walkover)) return { ...m, walkover: null, autoWalkover: false };
    if (m.pairA && m.pairB && !matchHasScore(m)) {
      const gone = out.has(m.pairA) ? m.pairA : out.has(m.pairB) ? m.pairB : null;
      if (gone) return { ...m, walkover: gone, autoWalkover: true, sets: [], liveStatus: null };
    }
    return m;
  };
  let current = category;
  for (let pass = 0; pass < 6; pass++) {
    const next = {
      ...current,
      groups: (current.groups || []).map((g) => {
        const matches = g.matches.map(fix);
        return { ...g, matches: g.format === "bracket4" ? propagateGroupBracket4(matches, format) : matches };
      }),
      bracket: current.bracket ? propagateBracket(current.bracket.map((round) => round.map(fix)), format) : current.bracket,
    };
    if (JSON.stringify(next) === JSON.stringify(current)) return current;
    current = next;
  }
  return current;
}

function formatSummary(format) {
  const f = format || DEFAULT_MATCH_FORMAT;
  if (isSingleSetFormat(f)) {
    const tie = f.gamesPerSet - 1;
    const set = f.type === "americano" ? `set único a ${f.gamesPerSet} games, sin ventaja` : `un solo set a ${f.gamesPerSet} games`;
    return `${set} · en ${tie}-${tie} tie break a 7 puntos (diferencia de 2)`;
  }
  const parts = [
    f.setsToPlay === 2 ? "2 sets directos" : "Al mejor de 3 sets",
    `${f.gamesPerSet} games por set`,
  ];
  if (f.setTiebreak) parts.push(`tie break a 7 en ${f.gamesPerSet}-${f.gamesPerSet}`);
  if (f.setsToPlay >= 3) parts.push(f.finalSuperTiebreak ? "super tie-break a 10 en el set decisivo" : "sin super tie-break (se juega el set completo)");
  return parts.join(" · ");
}

/* ---------- Horarios y canchas ---------- */

function timeToMinutes(t) {
  const [h, m] = t.split(":").map(Number);
  return h * 60 + m;
}
function minutesToTime(mins) {
  const h = Math.floor(mins / 60).toString().padStart(2, "0");
  const m = (mins % 60).toString().padStart(2, "0");
  return `${h}:${m}`;
}

/* Junta todos los partidos con ambas parejas ya definidas (de grupos y de la llave) de todas las categorías */
function collectScheduleableMatches(tournament) {
  const list = [];
  if (isInfoOnly(tournament)) return list;
  (tournament.categories || []).forEach((c) => {
    const nums = categoryMatchNumbers(c);
    (c.groups || []).forEach((g) => {
      g.matches.forEach((m) => {
        const isPending4 = g.format === "bracket4" && (m.stage === "ganadores" || m.stage === "perdedores") && !(m.pairA && m.pairB);
        if ((m.pairA && m.pairB) || isPending4) {
          list.push({
            key: `${c.id}:g:${g.id}:${m.id}`, categoryId: c.id, categoryName: c.name,
            location: { type: "group", groupId: g.id }, matchId: m.id, number: nums.get(m.id), label: m.round ? `${g.name} · Ronda ${m.round}` : g.name,
            pairA: m.pairA, pairB: m.pairB, schedule: m.schedule || null, sets: m.sets || [],
            walkover: m.walkover || null, retired: m.retired || null, liveStatus: m.liveStatus || null,
            stage: m.stage || null, groupFormat: g.format || "roundrobin",
            placeholder: isPending4 ? (m.stage === "ganadores" ? "Ganador Partido 1 vs Ganador Partido 2" : "Perdedor Partido 1 vs Perdedor Partido 2") : null,
          });
        }
      });
    });
    // Un bye (la pareja pasa directo) no se juega: no tiene horario y no va en la grilla ni en
    // "Sin horario asignado"
    const byes = c.bracket ? walkBracket(c.bracket).byes : [];
    const nombres = c.bracket ? categoryEntitiesById(c) : {};
    (c.bracket || []).forEach((round, ri) => {
      round.forEach((m, mi) => {
        if (isByeMatch(byes, ri, mi)) return;
        // En un esqueleto precargado, no solo la ronda 1 tiene placeholders de texto propios:
        // TODAS las rondas siguientes (semis, final...) también deben poder programarse de
        // antemano, aunque todavía no tengan ni pairA/pairB ni placeholderA/placeholderB propios
        // (esos se completan recién cuando se resuelve la ronda anterior).
        const isSkeletonSlot = c.bracketIsSkeleton && !(m.pairA && m.pairB);
        let placeholderText = null;
        if (isSkeletonSlot) {
          if (m.placeholderA || m.placeholderB) {
            placeholderText = `${m.placeholderA || "?"} vs ${m.placeholderB || "?"}`;
          } else {
            const prevLabel = roundStageLabel(c.bracket.length, ri - 1);
            placeholderText = `Ganador ${prevLabel} ${mi * 2 + 1} vs Ganador ${prevLabel} ${mi * 2 + 2}`;
          }
        }
        // Una ronda siguiente que ya tiene horario (semis, final…) también va, aunque falte saber quién
        // juega: "Ganador Cuartos 1 vs Ganador Cuartos 2" (o el nombre de la pareja que ya pasó)
        const isPendingScheduled = !isSkeletonSlot && ri > 0 && !!m.schedule && !(m.pairA && m.pairB);
        if (isPendingScheduled) {
          const prevLabel = roundStageLabel(c.bracket.length, ri - 1);
          const lado = (pid, n) => (pid ? nombres[pid]?.name || "?" : `Ganador ${prevLabel} ${n}`);
          placeholderText = `${lado(m.pairA, mi * 2 + 1)} vs ${lado(m.pairB, mi * 2 + 2)}`;
        }
        if ((m.pairA && m.pairB) || isSkeletonSlot || isPendingScheduled) {
          list.push({
            key: `${c.id}:b:${ri}:${m.id}`, categoryId: c.id, categoryName: c.name,
            location: { type: "bracket", roundIndex: ri }, matchId: m.id, number: nums.get(m.id), label: roundStageLabel(c.bracket.length, ri),
            pairA: m.pairA, pairB: m.pairB, schedule: m.schedule || null, sets: m.sets || [],
            walkover: m.walkover || null, retired: m.retired || null, liveStatus: m.liveStatus || null, draft: !c.bracketPublished,
            placeholder: placeholderText,
          });
        }
      });
    });
  });
  return list;
}

/* Publica la llave de una categoría (los jugadores la ven, con sus horarios) o, con
   published = false, la vuelve a borrador */
function publishBracketSchedule(tournament, categoryId, published = true) {
  return {
    ...tournament,
    categories: tournament.categories.map((c) => (c.id === categoryId ? { ...c, bracketPublished: published } : c)),
  };
}

/* Actualiza el horario de un partido puntual dentro de la estructura anidada del torneo */
function withMatchSchedule(tournament, categoryId, location, matchId, schedule) {
  return {
    ...tournament,
    categories: tournament.categories.map((c) => {
      if (c.id !== categoryId) return c;
      if (location.type === "group") {
        return {
          ...c,
          groups: c.groups.map((g) => (g.id !== location.groupId ? g : {
            ...g, matches: g.matches.map((m) => (m.id === matchId ? { ...m, schedule } : m)),
          })),
        };
      }
      return {
        ...c,
        bracket: c.bracket.map((round, ri) => (ri !== location.roundIndex ? round : round.map((m) => (m.id === matchId ? { ...m, schedule } : m)))),
      };
    }),
  };
}

/* Cambia el resultado (sets o WO) de un partido puntual y propaga lo que dependa de él: los cruces
   de ganadores/perdedores en un grupo de 4, o las rondas siguientes de la llave. */
function withMatchResult(tournament, categoryId, location, matchId, change) {
  return {
    ...tournament,
    categories: tournament.categories.map((c) => {
      if (c.id !== categoryId) return c;
      if (location.type === "group") {
        return {
          ...c,
          groups: c.groups.map((g) => {
            if (g.id !== location.groupId) return g;
            const matches = g.matches.map((m) => (m.id === matchId ? change(m) : m));
            return { ...g, matches: g.format === "bracket4" ? propagateGroupBracket4(matches, tournament.matchFormat) : matches };
          }),
        };
      }
      const rounds = c.bracket.map((round, ri) => (ri !== location.roundIndex ? round : round.map((m) => (m.id === matchId ? change(m) : m))));
      return { ...c, bracket: propagateBracket(rounds, tournament.matchFormat) };
    }),
  };
}

/* Rearma la grilla desde cero: saca el horario a todos los partidos que todavía no se jugaron ni
   están en curso, y los vuelve a ubicar con las canchas, el horario y la duración actuales (primero
   los de grupos y después las llaves). Sirve cuando cambia el horario de arranque, la cantidad de
   canchas o el tiempo entre partidos con los horarios ya generados. */
function rescheduleTournament(tournament) {
  const keep = (m) => matchHasScore(m) || m.liveStatus === "en_curso";
  const clear = (m) => (m.schedule && !keep(m) ? { ...m, schedule: null } : m);
  let next = {
    ...tournament,
    categories: tournament.categories.map((c) => ({
      ...c,
      groups: (c.groups || []).map((g) => ({ ...g, matches: g.matches.map(clear) })),
      bracket: c.bracket ? c.bracket.map((round) => round.map(clear)) : c.bracket,
    })),
  };
  next = autoSchedule(next);
  return autoScheduleAllBrackets(next);
}

/* Marca/quita el estado "en curso" a mano en un partido puntual (se usa mientras no tenga resultado cargado) */
function withMatchLiveStatus(tournament, categoryId, location, matchId, liveStatus) {
  return {
    ...tournament,
    categories: tournament.categories.map((c) => {
      if (c.id !== categoryId) return c;
      if (location.type === "group") {
        return {
          ...c,
          groups: c.groups.map((g) => (g.id !== location.groupId ? g : {
            ...g, matches: g.matches.map((m) => (m.id === matchId ? { ...m, liveStatus } : m)),
          })),
        };
      }
      return {
        ...c,
        bracket: c.bracket.map((round, ri) => (ri !== location.roundIndex ? round : round.map((m) => (m.id === matchId ? { ...m, liveStatus } : m)))),
      };
    }),
  };
}

/* Todos los horarios ya reservados en el torneo (de cualquier categoría, sean partidos de grupos
   o de la llave, tengan o no las dos parejas definidas todavía) */
function collectAllSchedules(tournament) {
  const list = [];
  (tournament.categories || []).forEach((c) => {
    (c.groups || []).forEach((g) => g.matches.forEach((m) => { if (m.schedule) list.push(m.schedule); }));
    // Los byes de la llave no se juegan: si les quedó un horario viejo, no ocupa la cancha
    const byes = c.bracket ? walkBracket(c.bracket).byes : [];
    (c.bracket || []).forEach((round, ri) => round.forEach((m, mi) => { if (m.schedule && !isByeMatch(byes, ri, mi)) list.push(m.schedule); }));
  });
  return list;
}

function scheduleEndPoint(schedule, duration) {
  return { date: schedule.date, minutes: timeToMinutes(schedule.time) + duration };
}

/* Día y hora de inicio propios de una categoría (torneo Clásico): { date, time } guardado en
   category.start. Como "piso" para armar horarios: { date, minutes }, o null si no tiene. */
function categoryStartPoint(category) {
  const s = category?.start;
  if (!s?.date) return null;
  return { date: s.date, minutes: s.time ? timeToMinutes(s.time) : 0 };
}

/* "Sáb 24/10 · 15 hs" de una categoría con inicio propio, o null */
function categoryStartLabel(category) {
  const s = category?.start;
  if (!s?.date) return null;
  return `${formatDateShort(s.date)}${s.time ? ` · ${formatHour(s.time)}` : ""}`;
}

/* Para qué es cada día de juego de un Clásico: "grupos", "llaves" o "ambos". Los días de torneos
   de antes no lo tienen y valen como "ambos" (como funcionaban). Al agregar días, el último queda
   para llaves y los demás para grupos (useAuto: lo eligió la app, se recalcula al agregar o quitar
   días hasta que el organizador lo cambie a mano). */
const DAY_USES = [["grupos", "Grupos"], ["llaves", "Llaves"], ["ambos", "Ambos"]];
const dayUse = (d) => d?.use || "ambos";
const isGroupDay = (d) => dayUse(d) !== "llaves";
const isBracketDay = (d) => dayUse(d) !== "grupos";
/* Días en que se juegan los grupos (los únicos en que importa la disponibilidad de las parejas) */
const groupPlayDates = (t) => (t?.playDates || []).filter(isGroupDay);
function withAutoDayUses(dates) {
  const last = dates.length - 1;
  return dates.map((d, i) => (d.useAuto ? { ...d, use: dates.length === 1 ? "ambos" : i === last ? "llaves" : "grupos" } : d));
}

/* "La llave arranca" de una categoría: { date, time } en category.bracketStart. Si lo tiene, la
   primera ronda de su llave puede jugarse ese día desde esa hora, aunque sea un día de grupos; desde
   la segunda ronda, todas las llaves van a los días de llaves. Como "piso": { date, minutes }. */
function bracketStartPoint(category) {
  const s = category?.bracketStart;
  if (!s?.date) return null;
  return { date: s.date, minutes: s.time ? timeToMinutes(s.time) : 0 };
}

function laterPoint(a, b) {
  if (!a) return b;
  if (!b) return a;
  if (a.date !== b.date) return a.date > b.date ? a : b;
  return a.minutes > b.minutes ? a : b;
}

/* Descanso por defecto entre el inicio de un partido de llave de una pareja y el del siguiente */
const DEFAULT_BRACKET_REST = 120;
const BRACKET_REST_OPTIONS = [60, 90, 120, 150, 180];
/* "2 h", "1 h 30" */
const formatRest = (min) => `${Math.floor(min / 60)} h${min % 60 ? ` ${min % 60}` : ""}`;

/* Lo que comparten todas las llaves de un torneo para armar sus horarios (ver bracketSchedule.js):
   días, canchas y sedes, lo que ya está ocupado, el descanso y la franja de cierre (las últimas 3
   horas del último día de llaves) */
function bracketScheduleShared(tournament, excludeCategoryIds = []) {
  const duration = tournament.matchDurationMinutes || DEFAULT_MATCH_DURATION;
  const days = (tournament.playDates || []).map((d) => ({ date: d.date, from: d.from, to: d.to, bracket: isBracketDay(d) }));
  const bracketDays = [...days].filter((d) => d.bracket).sort((a, b) => (a.date < b.date ? -1 : 1));
  const lastDay = bracketDays[bracketDays.length - 1];
  // Ocupado: lo que ya tiene horario y las canchas de sedes que no juegan ese día o a esa hora
  const busy = closedCourtSlots(tournament);
  collectAllSchedules(tournament).forEach((s) => busy.add(`${s.date}|${s.time}|${s.court}`));
  // Finales ya ubicadas de las demás categorías, para repartir la franja de cierre
  const otherFinals = (tournament.categories || [])
    .filter((c) => c.bracket && !excludeCategoryIds.includes(c.id))
    .map((c) => c.bracket[c.bracket.length - 1]?.[0]?.schedule)
    .filter(Boolean)
    .map((s) => ({ date: s.date, time: s.time, venue: courtVenueIndex(tournament, s.court) }));
  return {
    days, duration, courts: tournament.courtsCount || 4, busy, otherFinals,
    venueOf: (court) => courtVenueIndex(tournament, court),
    rest: tournament.bracketRestMinutes || DEFAULT_BRACKET_REST,
    closingFrom: lastDay ? timeToMinutes(lastDay.to) - 180 : 0,
  };
}

/* Lo propio de la llave de una categoría: sus partidos (con los byes marcados y lo que ya tiene
   horario), la hora y sede de la final que eligió el organizador, su inicio, "La llave arranca" y
   los partidos de grupos de quienes pueden llegar a cada lugar de la primera ronda */
function bracketScheduleCategory(tournament, category) {
  const { byes } = walkBracket(category.bracket);
  const rounds = category.bracket.map((round, ri) => round.map((m, mi) => ({ schedule: m.schedule || null, bye: isByeMatch(byes, ri, mi) })));
  const dates = tournament.playDates || [];
  // "La llave arranca" solo cuenta si ese día sigue siendo de grupos
  const ownStartDay = dates.find((d) => d.date === category.bracketStart?.date);
  const ownStart = ownStartDay && !isBracketDay(ownStartDay) ? bracketStartPoint(category) : null;
  const venueIndex = (tournament.venues || []).findIndex((v) => v.id === category.bracketFinal?.venueId);
  const finalPref = category.bracketFinal ? { time: category.bracketFinal.time || null, venue: venueIndex >= 0 ? venueIndex : null } : null;
  // Quiénes pueden llegar a un lugar de la primera ronda: la pareja ya definida, o cualquiera del
  // grupo del lugar ("1° Grupo A"); y los horarios de sus partidos de grupos
  const groupsByName = Object.fromEntries((category.groups || []).map((g) => [g.name, g]));
  const groupMatchesOf = {};
  (category.groups || []).forEach((g) => g.matches.forEach((m) => {
    if (!m.schedule) return;
    // En los cruces de un grupo de 4 sin definir puede jugar cualquiera del grupo
    (m.pairA && m.pairB ? [m.pairA, m.pairB] : g.pairIds).forEach((pid) => (groupMatchesOf[pid] = groupMatchesOf[pid] || []).push(m.schedule));
  }));
  const entrants = (mi) => {
    const m = category.bracket[0][mi];
    return ["A", "B"].flatMap((side) => {
      if (m[`pair${side}`]) return [m[`pair${side}`]];
      return groupsByName[(m[`placeholder${side}`] || "").split("° ")[1]]?.pairIds || [];
    }).flatMap((pid) => groupMatchesOf[pid] || []);
  };
  return { rounds, finalPref, categoryStart: categoryStartPoint(category), ownStart, entrants };
}

/* Pone en la llave los horarios que armó scheduleKnockout(s). Los byes quedan sin horario. */
function withBracketSchedules(category, schedules) {
  return { ...category, bracket: category.bracket.map((round, ri) => round.map((m, mi) => ({ ...m, schedule: schedules[ri][mi] || null }))) };
}

/* Horarios de la llave de una categoría (al armarla, rearmarla o completarla con los clasificados),
   alrededor de lo que ya está ocupado en el torneo: ver bracketSchedule.js */
function autoScheduleBracket(tournament, category) {
  if (!tournamentUsesSchedule(tournament) || (tournament.playDates || []).length === 0 || !category.bracket) return category;
  const shared = bracketScheduleShared(tournament, [category.id]);
  return withBracketSchedules(category, scheduleKnockout({ ...shared, ...bracketScheduleCategory(tournament, category) }));
}

/* Horarios de las llaves de todas las categorías juntas, por etapas desde la final (ver
   scheduleKnockouts): la usa "Rearmar horarios" */
function autoScheduleAllBrackets(tournament) {
  if (!tournamentUsesSchedule(tournament) || (tournament.playDates || []).length === 0) return tournament;
  const withBracket = (tournament.categories || []).filter((c) => c.bracket && !isSuper8(c));
  if (withBracket.length === 0) return tournament;
  const shared = bracketScheduleShared(tournament, withBracket.map((c) => c.id));
  const outs = scheduleKnockouts({ ...shared, categories: withBracket.map((c) => bracketScheduleCategory(tournament, c)) });
  const byId = Object.fromEntries(withBracket.map((c, i) => [c.id, withBracketSchedules(c, outs[i])]));
  return { ...tournament, categories: tournament.categories.map((c) => byId[c.id] || c) };
}

/* Aviso de lugar para las llaves de un Clásico (texto, o null si entran): cuántos partidos de llave
   van a hacer falta en los días de llaves contra los turnos libres que hay, y si alcanzan los
   horarios para jugar las rondas una después de otra. Con llave armada se cuentan sus partidos (sin
   byes); si todavía no, salen de los clasificados de los grupos (n clasificados = n - 1 partidos).
   La primera ronda de una categoría con "La llave arranca" no ocupa los días de llaves. Si la llave
   ya está armada y quedaron partidos sin horario, también lo dice. */
function bracketCapacityNotice(tournament) {
  if (tournamentType(tournament) !== "clasico") return null;
  const dates = tournament.playDates || [];
  if (dates.length === 0) return null;
  const duration = tournament.matchDurationMinutes || DEFAULT_MATCH_DURATION;
  const courts = tournament.courtsCount || 4;
  let needed = 0, rounds = 0, unscheduled = 0;
  (tournament.categories || []).forEach((c) => {
    if (isSuper8(c)) return;
    const startDay = dates.find((d) => d.date === c.bracketStart?.date);
    const earlyFirstRound = !!startDay && !isBracketDay(startDay);
    let total, firstRound, depth;
    if (c.bracket) {
      const { byes } = walkBracket(c.bracket);
      const played = c.bracket.map((round, ri) => round.filter((m, mi) => !isByeMatch(byes, ri, mi)));
      total = played.reduce((s, r) => s + r.length, 0);
      firstRound = played[0]?.length || 0;
      depth = c.bracket.length;
      unscheduled += played.flat().filter((m) => !m.schedule).length;
    } else {
      const n = (c.groups || []).reduce((s, g) => s + groupQualifiersCount(g), 0);
      if (n < 2) return;
      depth = Math.ceil(Math.log2(n));
      total = n - 1;
      firstRound = n - 2 ** (depth - 1);
    }
    needed += total - (earlyFirstRound ? firstRound : 0);
    rounds = Math.max(rounds, depth - (earlyFirstRound ? 1 : 0));
  });
  if (needed === 0) return null;

  const bracketDays = dates.filter(isBracketDay);
  const daysText = bracketDays.map((d) => formatDateShort(d.date)).join(" y ");
  if (bracketDays.length === 0) return `No hay ningún día de llaves: marcá en qué día se juegan (Grupos / Llaves / Ambos, en las fechas del torneo).`;
  // Turnos libres en los días de llaves: los ocupados por partidos de grupos (en un día "Ambos") y
  // las canchas de sedes que no juegan ese día o a esa hora no cuentan
  const groupBusy = closedCourtSlots(tournament);
  (tournament.categories || []).forEach((c) => (c.groups || []).forEach((g) => g.matches.forEach((m) => {
    if (m.schedule) groupBusy.add(`${m.schedule.date}|${m.schedule.time}|${m.schedule.court}`);
  })));
  let capacity = 0, times = 0;
  bracketDays.forEach((d) => dayTimeSlots(d, duration).forEach((time) => {
    times++;
    for (let c = 1; c <= courts; c++) if (!groupBusy.has(`${d.date}|${time}|${c}`)) capacity++;
  }));

  const problems = [];
  if (needed > capacity) problems.push(`las llaves necesitan unos ${needed} partidos y en ${daysText} entran ${capacity}`);
  // Las rondas van una después de otra con el descanso entre partidos de una pareja en el medio
  const rest = Math.max(tournament.bracketRestMinutes || DEFAULT_BRACKET_REST, duration);
  const timesNeeded = rounds > 0 ? (rounds - 1) * Math.ceil(rest / duration) + 1 : 0;
  if (timesNeeded > times) problems.push(`hay llaves de ${rounds} rondas: con ${formatRest(rest)} entre ronda y ronda necesitan ${timesNeeded} horarios y ${daysText} tiene${bracketDays.length > 1 ? "n" : ""} ${times}`);
  if (problems.length === 0 && unscheduled === 0) return null;
  const head = problems.length > 0 ? `${problems.join("; ")}.` : `${unscheduled === 1 ? "1 partido" : `${unscheduled} partidos`} de la llave quedaron sin horario.`;
  return `${head.charAt(0).toUpperCase()}${head.slice(1)} Adelantá la primera ronda de alguna categoría con "La llave arranca" (en las fechas del torneo), o sumá horas o canchas a los días de llaves.`;
}

/* Parejas que en la inscripción dijeron que NO pueden jugar el primer cruce de llave el mismo día
   que terminan la zona, y cuyo partido de la ronda 1 quedó justo ese día. Mientras no se sabe quién
   clasifica, cuenta las del grupo que puede llegar a cada lugar ("1° Grupo A"). Devuelve un texto por
   categoría. */
function sameDayBracketNotices(tournament) {
  const out = [];
  (tournament.categories || []).forEach((c) => {
    if (!c.bracket || isSuper8(c)) return;
    const pairsById = Object.fromEntries(c.pairs.map((p) => [p.id, p]));
    const groupsByName = Object.fromEntries((c.groups || []).map((g) => [g.name, g]));
    // Último día con partidos de grupos de cada pareja
    const lastDay = {};
    (c.groups || []).forEach((g) => g.matches.forEach((m) => {
      if (!m.schedule) return;
      (m.pairA && m.pairB ? [m.pairA, m.pairB] : g.pairIds).forEach((pid) => {
        if (!lastDay[pid] || m.schedule.date > lastDay[pid]) lastDay[pid] = m.schedule.date;
      });
    }));
    const { byes } = walkBracket(c.bracket);
    const named = new Set(), possible = new Set();
    // Hasta 5 nombres y "y N más"
    const list = (ids) => {
      const names = [...ids].map((id) => pairsById[id].name);
      return names.length > 5 ? `${names.slice(0, 5).join(", ")} y ${names.length - 5} más` : names.join(", ");
    };
    let day = null;
    c.bracket[0].forEach((m, mi) => {
      if (!m.schedule || isByeMatch(byes, 0, mi)) return;
      ["A", "B"].forEach((side) => {
        const pid = m[`pair${side}`];
        const said = (id) => pairsById[id]?.sameDayBracket === false && lastDay[id] === m.schedule.date;
        if (pid) { if (said(pid)) { named.add(pid); day = m.schedule.date; } return; }
        const group = groupsByName[(m[`placeholder${side}`] || "").split("° ")[1]];
        (group?.pairIds || []).filter(said).forEach((id) => { possible.add(id); day = m.schedule.date; });
      });
    });
    if (named.size > 0) {
      out.push(`${c.name}: ${list(named)} contestaron que no pueden jugar la llave el mismo día que terminan los grupos, y su partido de la llave quedó ese día (${formatDateShort(day)}).`);
    } else if (possible.size > 0) {
      out.push(`${c.name}: la primera ronda de la llave quedó el ${formatDateShort(day)}, el mismo día que terminan sus grupos, y ${possible.size === 1 ? "1 pareja que puede llegar ahí contestó" : `${possible.size} parejas que pueden llegar ahí contestaron`} que no puede${possible.size === 1 ? "" : "n"} jugarla ese día: ${list(possible)}.`);
    }
  });
  return out;
}

/* Horarios de arranque de la grilla para un día de juego, según la duración de cada partido */
function dayTimeSlots(dateInfo, duration) {
  const times = [];
  for (let t = timeToMinutes(dateInfo.from); t + duration <= timeToMinutes(dateInfo.to); t += duration) times.push(minutesToTime(t));
  return times;
}

/* Orden cronológico de partidos con horario: fecha, hora y cancha */
function compareBySchedule(a, b) {
  if (a.schedule.date !== b.schedule.date) return a.schedule.date < b.schedule.date ? -1 : 1;
  if (a.schedule.time !== b.schedule.time) return a.schedule.time < b.schedule.time ? -1 : 1;
  return a.schedule.court - b.schedule.court;
}

/* El mismo "hoy" que reservas y caja: el día de Argentina, sin importar la zona del dispositivo */
const todayISO = () => hoyArgentina();

/* Partidos ya ubicados (de cualquier categoría) en una fecha/cancha puntual, excluyendo opcionalmente
   uno en particular (el que se está por mover) */
function matchesAtSlot(scheduledMatches, date, time, court, excludeKey) {
  return scheduledMatches.filter((m) => m.key !== excludeKey && m.schedule && m.schedule.date === date && m.schedule.time === time && m.schedule.court === court);
}

/* Busca el próximo horario libre en la MISMA cancha y fecha, a partir de un horario dado (inclusive),
   respetando el rango horario de esa fecha (y, con closed, salteando los turnos en que su sede no se
   usa). Devuelve null si no queda ningún hueco libre ese día. */
function findNextFreeSlotOnCourt(scheduledMatches, dateInfo, court, fromTime, duration, excludeKey, closed = new Set()) {
  if (!dateInfo) return null;
  const end = timeToMinutes(dateInfo.to);
  for (let t = timeToMinutes(fromTime); t + duration <= end; t += duration) {
    const timeStr = minutesToTime(t);
    if (closed.has(`${dateInfo.date}|${timeStr}|${court}`)) continue;
    if (matchesAtSlot(scheduledMatches, dateInfo.date, timeStr, court, excludeKey).length === 0) {
      return { date: dateInfo.date, time: timeStr, court };
    }
  }
  return null;
}

function pairAvailability(tournament, categoryId, pairId) {
  const cat = tournament.categories.find((c) => c.id === categoryId);
  // Equipo del Súper 8 Individual: puede jugar solo cuando coinciden sus dos jugadores
  const team = (cat?.teams || []).find((t) => t.id === pairId);
  if (team) return groupCombinedAvailability(tournament, categoryId, team.playerIds);
  const pair = cat?.pairs.find((p) => p.id === pairId);
  if (pair?.availability && pair.availability.length > 0) return pair.availability;
  // Sin disponibilidad cargada: se toma como disponible todos los días del torneo, en el horario de cada uno
  return (tournament.playDates || []).map((d) => ({ date: d.date, from: d.from, to: d.to }));
}

/* Parejas de un partido de grupo que no pueden jugar en el horario que tiene asignado (según la
   disponibilidad que eligieron). El armado automático nunca las pone así, pero el organizador sí
   puede moverlo a mano (por ejemplo, porque lo habló con ellas): la grilla lo marca con un aviso. */
function pairsOutsideAvailability(tournament, m) {
  if (!m.schedule || m.location?.type !== "group" || !m.pairA || !m.pairB) return [];
  const duration = tournament.matchDurationMinutes || DEFAULT_MATCH_DURATION;
  const start = timeToMinutes(m.schedule.time);
  return [m.pairA, m.pairB].filter((pid) => !pairAvailability(tournament, m.categoryId, pid).some((a) =>
    a.date === m.schedule.date && start >= timeToMinutes(a.from) && start + duration <= timeToMinutes(a.to)));
}

/* Disponibilidad combinada (intersección) de varias parejas de un mismo grupo: sirve para reservar
   de antemano el horario del cruce de ganadores/perdedores de un grupo de 4, antes de saber qué
   pareja concreta lo va a jugar. Solo devuelve fechas en las que TODAS coinciden. */
function groupCombinedAvailability(tournament, categoryId, pairIds) {
  const dates = (tournament.playDates || []).map((d) => d.date);
  const perPair = pairIds.map((pid) => pairAvailability(tournament, categoryId, pid));
  const combined = [];
  dates.forEach((date) => {
    const slots = perPair.map((avail) => avail.find((a) => a.date === date)).filter(Boolean);
    if (slots.length !== perPair.length) return;
    const from = Math.max(...slots.map((s) => timeToMinutes(s.from)));
    const to = Math.min(...slots.map((s) => timeToMinutes(s.to)));
    if (from < to) combined.push({ date, from: minutesToTime(from), to: minutesToTime(to) });
  });
  return combined;
}

/* ---------- Sorteo de grupos y control de una sola categoría por jugador ---------- */

const GROUP_LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

/* Arma grupos por sorteo cuidando que en cada grupo todas las parejas tengan algún horario en común
   entre sí (al menos un turno del largo de un partido, no alcanza con compartir el día). Entre los
   armados posibles prefiere el que deja más turnos en común, así después la grilla tiene de dónde
   elegir. En los grupos de 4 también elige los cruces de la primera ronda entre parejas compatibles.
   `pairs` son objetos {id, name, availability}. */
function autoFormGroups(pairs, playDates, duration = DEFAULT_MATCH_DURATION) {
  const TARGET_SIZE = 3;
  const total = pairs.length;
  if (total === 0) return { groups: [], warnings: [] };
  // Cantidad de grupos fija según el total de parejas: siempre en base a grupos de 3. Lo que sobra
  // al dividir por 3 (0, 1 o 2 parejas) va como cuarto integrante en esa cantidad de grupos.
  // Ej: 12 parejas -> 4 grupos de 3. 13 -> 3 de 3 + 1 de 4. 14 -> 2 de 3 + 2 de 4. Con menos de 6
  // parejas va un solo grupo con todas.
  const groupSizes = total < 6
    ? [total]
    : Array.from({ length: Math.floor(total / TARGET_SIZE) }, (_, i) => TARGET_SIZE + (i < total % TARGET_SIZE ? 1 : 0));

  // Ventanas horarias por pareja y fecha, en minutos. Sin disponibilidad cargada = disponible todos
  // los días del torneo, en el horario general.
  const windowsOf = (p) => {
    const avail = p.availability && p.availability.length > 0 ? p.availability : playDates || [];
    const map = {};
    avail.forEach((a) => { if (a && a.date && a.from && a.to) map[a.date] = { from: timeToMinutes(a.from), to: timeToMinutes(a.to) }; });
    return map;
  };
  const wins = pairs.map(windowsOf);
  // Turnos de un partido en los que pueden jugar todas las parejas indicadas (índices)
  const commonSlots = (idxs) => {
    let n = 0;
    Object.keys(wins[idxs[0]]).forEach((date) => {
      const ws = idxs.map((i) => wins[i][date]);
      if (ws.some((w) => !w)) return;
      const span = Math.min(...ws.map((w) => w.to)) - Math.max(...ws.map((w) => w.from));
      if (span >= duration) n += Math.floor(span / duration);
    });
    return n;
  };
  const slots = pairs.map((_, i) => pairs.map((__, j) => (i === j ? 0 : commonSlots([i, j]))));

  // Puntaje de un grupo (menos es mejor): cada par de parejas sin turno en común pesa muchísimo; en
  // un grupo de 4 también pesa que no haya un turno de las 4 juntas (los cruces de ganadores y de
  // perdedores se programan antes de saber quién los juega). Después, más turnos en común = mejor.
  const groupCost = (g) => {
    let cost = 0;
    for (let a = 0; a < g.length; a++) {
      for (let b = a + 1; b < g.length; b++) {
        const s = slots[g[a]][g[b]];
        cost += s === 0 ? 1000 : -Math.min(s, 4);
      }
    }
    if (g.length === 4 && commonSlots(g) === 0) cost += 300;
    return cost;
  };

  const shuffle = (arr) => {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
    return a;
  };

  // Un armado: sorteo, ubicando primero a las parejas con menos compatibles (las más difíciles) en
  // el grupo donde menos daño hacen, y después intercambios de a dos parejas entre grupos mientras
  // mejore el puntaje total.
  const buildOnce = () => {
    const groups = groupSizes.map(() => []);
    const order = shuffle(pairs.map((_, i) => i))
      .sort((a, b) => slots[a].filter((s) => s > 0).length - slots[b].filter((s) => s > 0).length);
    order.forEach((i) => {
      let best = null, bestDelta = Infinity;
      shuffle(groups.map((_, gi) => gi)).forEach((gi) => {
        if (groups[gi].length >= groupSizes[gi]) return;
        const delta = groupCost([...groups[gi], i]) - groupCost(groups[gi]);
        if (delta < bestDelta) { bestDelta = delta; best = gi; }
      });
      groups[best].push(i);
    });
    let improved = true, guard = 0;
    while (improved && guard++ < 50) {
      improved = false;
      for (let g1 = 0; g1 < groups.length; g1++) {
        for (let g2 = g1 + 1; g2 < groups.length; g2++) {
          for (let x = 0; x < groups[g1].length; x++) {
            for (let y = 0; y < groups[g2].length; y++) {
              const before = groupCost(groups[g1]) + groupCost(groups[g2]);
              const a = [...groups[g1]], b = [...groups[g2]];
              [a[x], b[y]] = [b[y], a[x]];
              if (groupCost(a) + groupCost(b) < before) { groups[g1] = a; groups[g2] = b; improved = true; }
            }
          }
        }
      }
    }
    return { groups, cost: groups.reduce((s, g) => s + groupCost(g), 0) };
  };
  // Varios sorteos y se queda con el mejor
  let best = null;
  for (let k = 0; k < 20; k++) {
    const r = buildOnce();
    if (!best || r.cost < best.cost) best = r;
  }

  // Grupo de 4: los cruces de la primera ronda (0 vs 1, 2 vs 3) entre parejas con turno en común
  const orderForFirstRound = (g) => {
    if (g.length !== 4) return g;
    const [a, b, c, d] = g;
    const options = shuffle([[a, b, c, d], [a, c, b, d], [a, d, b, c]]);
    const bad = (o) => (slots[o[0]][o[1]] === 0 ? 1 : 0) + (slots[o[2]][o[3]] === 0 ? 1 : 0);
    return options.sort((x, y) => bad(x) - bad(y))[0];
  };

  // Aviso: parejas que quedaron con alguien de su grupo sin ningún turno en común
  const warnings = [];
  best.groups.forEach((g) => g.forEach((i) => {
    if (g.some((j) => j !== i && slots[i][j] === 0)) warnings.push(pairs[i].name || "Pareja");
  }));

  const formed = best.groups.map((g, gi) => {
    const pairIds = orderForFirstRound(g).map((i) => pairs[i].id);
    const built = buildGroupMatches(pairIds, true);
    return { id: uid(), name: `Grupo ${GROUP_LETTERS[gi] || gi + 1}`, pairIds, format: built.format, matches: built.matches };
  });
  return { groups: formed, warnings };
}
/* Parejas ya anotadas en el torneo (todas sus categorías), para el aviso de nombres repetidos */
function tournamentPairEntries(tournament) {
  return (tournament.categories || []).flatMap((c) => c.pairs.map((p) => ({ name: p.name, where: c.name, kind: "anotada" })));
}

/* Texto del aviso de nombres repetidos (ver findNameDuplicates). Muestra hasta 3. */
function duplicateNamesText(found) {
  if (found.length === 0) return null;
  const lines = found.slice(0, 3).map((f) => {
    const pending = f.kind === "pendiente";
    if (f.match === "igual") return pending ? `"${f.player}" tiene otra inscripción pendiente en ${f.where}` : `"${f.player}" ya está anotado en ${f.where}`;
    return `"${f.player}" se parece a "${f.other}" (${pending ? "inscripción pendiente" : "anotado"} en ${f.where})`;
  });
  return `Ojo, puede estar repetido: ${lines.join(" · ")}${found.length > 3 ? ` y ${found.length - 3} más` : ""}.`;
}

/* ---------- Circuitos anuales (torneos "fecha" que suman puntos individuales) ---------- */

const DEFAULT_CIRCUIT_POINTS = { campeon: 100, finalista: 70, semifinalista: 50, cuartos: 30, octavos: 20, grupos: 10 };
const CIRCUIT_TIER_LABEL = { campeon: "Campeón", finalista: "Finalista", semifinalista: "Semifinalista", cuartos: "Cuartos de final", octavos: "Octavos de final", grupos: "Fase de grupos" };
const CIRCUIT_TIER_ORDER = ["campeon", "finalista", "semifinalista", "cuartos", "octavos", "grupos"];

/* A partir de la llave final de una categoría, determina en qué instancia quedó eliminada cada pareja.
   Las que nunca entraron a la llave (o no hay llave todavía) quedan en "fase de grupos". */
function categoryPlacements(category, format) {
  const results = []; // { pairId, tier }
  if (category.bracket && category.bracket.length > 0) {
    // Recalculada desde la primera ronda: no se confía en parejas que hayan avanzado de más
    const { rounds: bracket, winners } = walkBracket(category.bracket, format);
    const finalMatch = bracket[bracket.length - 1][0];
    const champion = winners[bracket.length - 1][0];
    [finalMatch.pairA, finalMatch.pairB].filter(Boolean).forEach((pid) => {
      results.push({ pairId: pid, tier: pid === champion ? "campeon" : "finalista" });
    });
    if (bracket.length >= 2) {
      bracket[bracket.length - 2].forEach((m, i) => {
        const w = winners[bracket.length - 2][i];
        [m.pairA, m.pairB].filter(Boolean).forEach((pid) => { if (pid !== w) results.push({ pairId: pid, tier: "semifinalista" }); });
      });
    }
    // Cuartos de Final es exactamente la ronda bracket.length-3
    if (bracket.length >= 3) {
      bracket[bracket.length - 3].forEach((m, i) => {
        const w = winners[bracket.length - 3][i];
        [m.pairA, m.pairB].filter(Boolean).forEach((pid) => { if (pid !== w) results.push({ pairId: pid, tier: "cuartos" }); });
      });
    }
    // Octavos y cualquier ronda anterior (16avos, etc.) se agrupan en "octavos" por no tener escalón propio
    for (let r = 0; r <= bracket.length - 4; r++) {
      bracket[r].forEach((m, i) => {
        const w = winners[r][i];
        [m.pairA, m.pairB].filter(Boolean).forEach((pid) => { if (pid !== w) results.push({ pairId: pid, tier: "octavos" }); });
      });
    }
  }
  const placed = new Set(results.map((r) => r.pairId));
  category.pairs.forEach((p) => { if (!placed.has(p.id)) results.push({ pairId: p.id, tier: "grupos" }); });
  return results;
}

/* Tabla de puntos de un circuito, separada por categoría, sumando por jugador individual
   (no por pareja, porque puede cambiar de compañero entre fechas) */
function computeCircuitStandings(circuit, tournaments) {
  const points = circuit.pointsScale || DEFAULT_CIRCUIT_POINTS;
  const table = {}; // { [categoryName]: [{ players, points }] }, una entrada por pareja y por fecha
  circuit.categoryNames.forEach((cn) => { table[cn] = []; });

  // Un torneo informativo nunca suma puntos, aunque por error quedara asignado a un circuito; uno Próximo
  // tampoco hasta que tenga algún resultado (anotarse no da puntos de "fase de grupos")
  const jugado = (t) => t.status !== STATUS.PROXIMO || tournamentProgress(t).played > 0 || tournamentHasScores(t);
  tournaments.filter((t) => t.circuitId === circuit.id && !isInfoOnly(t) && jugado(t)).forEach((t) => {
    t.categories.forEach((cat) => {
      if (isSuper8(cat)) return; // El Súper 8 no suma puntos de circuito
      const matchName = circuit.categoryNames.find((cn) => cn.trim().toLowerCase() === cat.name.trim().toLowerCase());
      if (!matchName) return;
      // Con el resumen (portada) vienen ya los nombres con su instancia
      const placed = cat._placements || categoryPlacements(cat, t.matchFormat).map(({ pairId, tier }) => {
        const pair = cat.pairs.find((p) => p.id === pairId);
        return { name: pair?.name, players: pair?.players, tier };
      });
      placed.forEach(({ name, players, tier }) => {
        if (!name) return;
        // Por jugador: con su ID si se cargó con teléfono; si no, por nombre ("Ibáñez" e "Ibanez" son
        // la misma persona). Ver rankingPorJugador en jugadores.js
        table[matchName].push({ players: jugadoresConPerfil({ name, players }), points: points[tier] ?? 0 });
      });
    });
  });

  const result = {};
  Object.entries(table).forEach(([cn, entradas]) => {
    result[cn] = rankingPorJugador(entradas);
  });
  return result;
}

/* Arma la grilla de forma automática: solo completa partidos que todavía no tengan horario asignado,
   respetando disponibilidad de parejas, sin repetir cancha ni hacer jugar a una pareja dos veces a la vez */
function autoSchedule(tournament) {
  if (!tournamentUsesSchedule(tournament)) return tournament; // El Súper 8 no tiene grilla
  const courts = tournament.courtsCount || 4;
  const duration = tournament.matchDurationMinutes || DEFAULT_MATCH_DURATION;
  // Los grupos se juegan solo en los días de grupos (o "ambos"), nunca en un día de llaves
  const dates = groupPlayDates(tournament).map((d) => d.date);
  const all = collectScheduleableMatches(tournament);

  // Quiénes no pueden estar en dos canchas a la vez: las dos parejas, o los 4 jugadores en el
  // Súper 8 Individual (ahí las parejas cambian en cada partido, así que se controla por jugador).
  const categoriesById = Object.fromEntries((tournament.categories || []).map((c) => [c.id, c]));
  const participants = (m) => [m.pairA, m.pairB].flatMap((side) => sideParticipantIds(categoriesById[m.categoryId], side));

  // En el cruce de ganadores/perdedores de un grupo de 4 todavía no se sabe quién juega: para la
  // sede cuenta cualquiera de las 4 parejas del grupo
  const venueParticipants = (m) => {
    if (m.pairA && m.pairB) return participants(m);
    return categoriesById[m.categoryId]?.groups.find((g) => g.id === m.location.groupId)?.pairIds || [];
  };

  // Las canchas de sedes que no juegan ese día o a esa hora arrancan ocupadas
  const courtBusy = closedCourtSlots(tournament);
  const pairBusy = new Set();
  // Partidos de cada pareja por día, con su sede: `${fecha}|${pareja}` -> [{ t: minutos, venue }]
  const pairDay = {};
  const addPairDay = (date, time, court, ids) => ids.forEach((pid) => {
    (pairDay[`${date}|${pid}`] = pairDay[`${date}|${pid}`] || []).push({ t: timeToMinutes(time), venue: courtVenueIndex(tournament, court) });
  });
  all.filter((m) => m.schedule).forEach((m) => {
    const { date, time, court } = m.schedule;
    courtBusy.add(`${date}|${time}|${court}`);
    participants(m).forEach((pid) => pairBusy.add(`${date}|${time}|${pid}`));
    addPairDay(date, time, court, venueParticipants(m));
  });
  // Una pareja con dos partidos seguidos (sin un turno libre en el medio) los juega en la misma
  // sede: si el primero se demora, no llega a otra.
  const venueAllowed = (ids, date, t, venue) => ids.every((pid) => (pairDay[`${date}|${pid}`] || []).every((e) => {
    const gap = e.t < t ? t - (e.t + duration) : e.t - (t + duration);
    return gap < 0 || gap >= duration || e.venue === venue;
  }));
  // Entre las canchas posibles, mejor una sede donde esas parejas ya juegan ese día
  const playsAtVenue = (ids, date, venue) => ids.some((pid) => (pairDay[`${date}|${pid}`] || []).some((e) => e.venue === venue));

  // "Cada grupo en una sola sede": el primer partido que se ubica de un grupo define su sede (y su
  // cancha, que se prefiere para los demás). Los grupos nuevos van a la sede con menos grupos.
  const oneVenue = groupsInOneVenue(tournament);
  const groupVenue = {}, groupCourt = {}, venueGroups = {};
  const setGroupPlace = (key, court) => {
    if (groupVenue[key] != null) return;
    groupVenue[key] = courtVenueIndex(tournament, court);
    groupCourt[key] = court;
    venueGroups[groupVenue[key]] = (venueGroups[groupVenue[key]] || 0) + 1;
  };
  all.filter((m) => m.schedule && m.location.type === "group").forEach((m) => setGroupPlace(`${m.categoryId}:${m.location.groupId}`, m.schedule.court));

  let updated = tournament;

  // En un grupo de 4, el cruce de ganadores y el de perdedores no pueden arrancar hasta que
  // terminen los dos partidos del sorteo inicial (r1). Guardamos esos horarios por grupo para
  // poder calcular ese piso, y procesamos primero los partidos r1 para tenerlo disponible.
  const groupR1Schedules = {}; // `${categoryId}:${groupId}` -> [schedule, ...]
  all.filter((m) => m.schedule && m.location.type === "group" && m.stage === "r1").forEach((m) => {
    const key = `${m.categoryId}:${m.location.groupId}`;
    (groupR1Schedules[key] = groupR1Schedules[key] || []).push(m.schedule);
  });

  // Disponibilidad de los dos lados de un partido. En el cruce de ganadores/perdedores de un grupo
  // de 4 todavía no se sabe quién juega, así que vale el horario en que coinciden las 4 parejas.
  const sidesAvailability = (m) => {
    if (!m.pairA || !m.pairB) {
      const group = categoriesById[m.categoryId]?.groups.find((g) => g.id === m.location.groupId);
      const combined = groupCombinedAvailability(tournament, m.categoryId, group?.pairIds || []);
      return [combined, combined];
    }
    return [pairAvailability(tournament, m.categoryId, m.pairA), pairAvailability(tournament, m.categoryId, m.pairB)];
  };
  // Cuántos turnos (sin mirar canchas ni otros partidos) podría ocupar un partido
  const slotOptions = (m) => {
    const [availA, availB] = sidesAvailability(m);
    let n = 0;
    dates.forEach((date) => {
      const aSlot = availA.find((a) => a.date === date), bSlot = availB.find((a) => a.date === date);
      if (!aSlot || !bSlot) return;
      const span = Math.min(timeToMinutes(aSlot.to), timeToMinutes(bSlot.to)) - Math.max(timeToMinutes(aSlot.from), timeToMinutes(bSlot.from));
      if (span >= duration) n += Math.floor(span / duration);
    });
    return n;
  };

  // Primero los partidos con menos turnos posibles (parejas que pueden un solo día o pocas horas) y
  // al final los más flexibles, que se acomodan en lo que queda: si no, los flexibles llenan el
  // primer día y las parejas que solo pueden ese día se quedan sin lugar. Los cruces de un grupo de
  // 4 van siempre después de su primera ronda (necesitan saber cuándo termina).
  const rank = (x) => (x.groupFormat === "bracket4" && x.stage !== "r1" ? 1 : 0);
  const toSchedule = all
    .filter((m) => !m.schedule && m.location.type === "group")
    .map((m) => ({ m, options: slotOptions(m) }))
    .sort((a, b) => rank(a.m) - rank(b.m) || a.options - b.options)
    .map((x) => x.m);

  // Solo se auto-programan partidos de grupos: las parejas únicamente informan disponibilidad
  // para esa fase. Los partidos de la llave final los agenda siempre el organizador a mano.
  toSchedule.forEach((m) => {
    const groupKey = `${m.categoryId}:${m.location.groupId}`;
    // Ninguna categoría juega antes de su día y hora de inicio (si el organizador cargó uno)
    let floor = categoryStartPoint(categoriesById[m.categoryId]);
    if (m.groupFormat === "bracket4" && m.stage !== "r1") {
      (groupR1Schedules[groupKey] || []).forEach((s) => { floor = laterPoint(floor, scheduleEndPoint(s, duration)); });
    }

    const isPlaceholder = !m.pairA || !m.pairB;
    const [availA, availB] = sidesAvailability(m);
    // Con "cada grupo en una sola sede", primero se busca solo en la sede del grupo; si ahí no entra,
    // en cualquiera (y el grupo queda repartido: la pestaña Horarios lo avisa)
    const ownVenue = oneVenue ? groupVenue[groupKey] : null;
    const findSlot = (onlyVenue) => {
      for (const date of dates) {
        if (floor && date < floor.date) continue;
        const aSlot = availA.find((a) => a.date === date);
        const bSlot = availB.find((a) => a.date === date);
        if (!aSlot || !bSlot) continue;
        const start = Math.max(timeToMinutes(aSlot.from), timeToMinutes(bSlot.from));
        const end = Math.min(timeToMinutes(aSlot.to), timeToMinutes(bSlot.to));
        for (let t = start; t + duration <= end; t += duration) {
          if (floor && date === floor.date && t < floor.minutes) continue;
          const time = minutesToTime(t);
          // Para el cruce de ganadores/perdedores todavía no sabemos qué pareja concreta juega,
          // así que solo evitamos pisar otra cancha (no hay pareja puntual que chequear todavía).
          if (!isPlaceholder && participants(m).some((pid) => pairBusy.has(`${date}|${time}|${pid}`))) continue;
          const ids = venueParticipants(m);
          const freeCourts = [];
          for (let c = 1; c <= courts; c++) {
            const venue = courtVenueIndex(tournament, c);
            if (onlyVenue != null && venue !== onlyVenue) continue;
            if (!courtBusy.has(`${date}|${time}|${c}`) && venueAllowed(ids, date, t, venue)) freeCourts.push(c);
          }
          if (freeCourts.length === 0) continue;
          const sameCourt = oneVenue ? freeCourts.find((c) => c === groupCourt[groupKey]) : undefined;
          // Grupo sin sede todavía: la sede con menos grupos entre las que tienen lugar
          const leastUsed = oneVenue && ownVenue == null
            ? [...freeCourts].sort((a, b) => (venueGroups[courtVenueIndex(tournament, a)] || 0) - (venueGroups[courtVenueIndex(tournament, b)] || 0))[0]
            : undefined;
          const freeCourt = sameCourt ?? freeCourts.find((c) => playsAtVenue(ids, date, courtVenueIndex(tournament, c))) ?? leastUsed ?? freeCourts[0];
          return { date, time, court: freeCourt };
        }
      }
      return null;
    };
    const placed = (ownVenue != null ? findSlot(ownVenue) : null) || findSlot(null);
    if (placed) {
      if (oneVenue) setGroupPlace(groupKey, placed.court);
      courtBusy.add(`${placed.date}|${placed.time}|${placed.court}`);
      if (!isPlaceholder) participants(m).forEach((pid) => pairBusy.add(`${placed.date}|${placed.time}|${pid}`));
      addPairDay(placed.date, placed.time, placed.court, venueParticipants(m));
      if (m.stage === "r1") (groupR1Schedules[groupKey] = groupR1Schedules[groupKey] || []).push(placed);
      updated = withMatchSchedule(updated, m.categoryId, m.location, m.matchId, placed);
    }
  });
  return updated;
}

/* ---------- Fuentes ---------- */
function useBrandFonts() {
  useEffect(() => {
    if (document.getElementById("sp-fonts")) return;
    const link = document.createElement("link");
    link.id = "sp-fonts";
    link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Archivo+Black&family=Work+Sans:wght@400;500;600;700&display=swap";
    document.head.appendChild(link);
  }, []);
}

const F = { display: { fontFamily: "'Archivo Black', sans-serif" }, body: { fontFamily: "'Work Sans', sans-serif" } };

/* Colores de marca, tomados del logo */
const BRAND = { bgStart: "#14181f", bgEnd: "#1b2027", lime: "#9fe022", limeText: "#14181f", ink: "#f2f5f8", cyan: "#22d3ee", logoLime: "#c1ef26" };

/* Fondo general: azul petróleo muy oscuro con un brillo suave arriba */
const APP_BACKGROUND = "radial-gradient(120% 60% at 50% 0%, #0f2f3a 0%, #0b1c24 45%, #081218 100%)";

/* Borde de neón con resplandor, para tarjetas y botones destacados */
function neonStyle(color, strong = false) {
  return {
    border: `1.5px solid ${color}${strong ? "" : "cc"}`,
    boxShadow: `0 0 ${strong ? 22 : 12}px ${color}${strong ? "80" : "4d"}, inset 0 0 18px ${color}14`,
  };
}

/* Fondo de cancha genérico (sin foto): vidrio oscuro con líneas de luz, para cuando el organizador
   todavía no subió su foto de portada */
const COURT_FALLBACK_BACKGROUND = [
  "linear-gradient(115deg, transparent 0 38%, rgba(159,224,34,0.18) 38.5%, transparent 40%)",
  "repeating-linear-gradient(90deg, rgba(148,163,184,0.07) 0 1px, transparent 1px 22px)",
  "repeating-linear-gradient(0deg, rgba(148,163,184,0.07) 0 1px, transparent 1px 22px)",
  "radial-gradient(80% 70% at 50% 30%, #12313b 0%, #0a1a21 100%)",
].join(", ");

/* ---------- Componentes chicos ---------- */

/* Logo: la "S" con el trazo de la pelota (imagen con fondo transparente), del alto indicado. Con
   withWordmark suma "SMASH POINT / EVENTOS DE PADEL" escrito como texto, para que se vea nítido
   en cualquier tamaño. */
function Logo({ size = 40, withWordmark = false }) {
  const mark = <img src={logoMarkUrl} alt="Smash Point" style={{ height: size, width: "auto" }} className="shrink-0" />;
  if (!withWordmark) return mark;
  return (
    <div className="flex flex-col items-center">
      {mark}
      <span className="mt-2 text-2xl" style={{ ...F.display, color: BRAND.logoLime, letterSpacing: "1px" }}>SMASH POINT</span>
      <span className="text-[11px]" style={{ ...F.body, color: BRAND.logoLime, letterSpacing: "4px" }}>EVENTOS DE PADEL</span>
    </div>
  );
}

/* Publicidad, igual en toda la app: una cuadrícula de 4 anuncios (2×2 en el celular, 4 en fila en
   la compu) que va rotando de a 4 cada 6 segundos. Los puntitos muestran la tanda actual y se
   pueden tocar para pasar a otra. No se muestra nada si no hay anuncios activos. */
const ADS_PAGE_SIZE = 4;

function AdBanner({ ads, className = "" }) {
  const active = (ads || []).filter((a) => a.active);
  const pages = [];
  for (let i = 0; i < active.length; i += ADS_PAGE_SIZE) pages.push(active.slice(i, i + ADS_PAGE_SIZE));
  const [page, setPage] = useState(0);

  useEffect(() => {
    if (pages.length < 2) return;
    const id = setInterval(() => setPage((p) => (p + 1) % pages.length), 6000);
    return () => clearInterval(id);
  }, [pages.length, page]); // al tocar un puntito se reinicia la cuenta

  if (active.length === 0) return null;
  const current = page % pages.length;

  return (
    <section className={className} aria-label="Publicidad">
      <div key={current} className="grid gap-3 grid-cols-2 sm:grid-cols-4 sp-fade-in">
        {pages[current].map((ad, i) => {
          const color = (Math.floor(i / 2) + i) % 2 === 0 ? BRAND.lime : BRAND.cyan;
          return (
            <a
              key={ad.id}
              href={ad.linkUrl || "#"}
              onClick={() => { if (ad.linkUrl) contarClic(ad.id); }}
              target="_blank"
              rel="noopener noreferrer"
              className="block relative rounded-2xl overflow-hidden"
              style={neonStyle(color)}
            >
              <img src={ad.imageUrl} alt={ad.name || "Publicidad"} className="w-full aspect-[4/3] object-cover" />
              <span className="absolute top-2 right-2 text-[10px] px-2 py-0.5 rounded-full" style={{ backgroundColor: "rgba(8,18,24,0.8)", color: "#cbd5e1", ...F.body }}>Publicidad</span>
            </a>
          );
        })}
      </div>
      {pages.length > 1 && (
        <div className="flex gap-2 justify-center mt-3">
          {pages.map((_, i) => (
            <button
              key={i}
              type="button"
              onClick={() => setPage(i)}
              aria-label={`Publicidades ${i + 1} de ${pages.length}`}
              className="w-2.5 h-2.5 rounded-full transition"
              style={{ backgroundColor: i === current ? BRAND.lime : "#1e3a45" }}
            />
          ))}
        </div>
      )}
    </section>
  );
}

/* Logo del organizador en un círculo (o su inicial si no subió logo) */
function OrganizerAvatar({ organizer, size = 48, color = BRAND.cyan }) {
  const style = { width: size, height: size, ...neonStyle(color), backgroundColor: "#081218" };
  if (organizer?.logoUrl) return <img src={organizer.logoUrl} alt={organizer.name} className="rounded-full object-cover shrink-0" style={style} />;
  return (
    <span className="rounded-full flex items-center justify-center shrink-0" style={{ ...style, ...F.display, color, fontSize: size * 0.4 }}>
      {(organizer?.name || "?").trim().charAt(0).toUpperCase()}
    </span>
  );
}

/* Formulario público de inscripción, en una hoja que sube desde abajo (en la compu, centrada).
   Sin cuenta: se guarda como "pendiente" y el organizador la acepta o rechaza desde su panel.
   Trae un campo trampa (honeypot) oculto para frenar bots y el botón se bloquea mientras envía. */
function RegistrationSheet({ tournament, organizer, onClose, jugadorApi = null }) {
  const categories = tournament.categories.filter(categoryAcceptsRegistrations);
  const [categoryId, setCategoryId] = useState(categories.length === 1 ? categories[0].id : "");
  // Cada jugador por separado (apellido, nombre y teléfono) y a quién le escribe el organizador.
  // Con los teléfonos, cada jugador queda con su perfil para el ranking (ver 20261039_inscripcion_perfiles.sql)
  // Con la sesión iniciada (cuenta de teléfono con sus datos), el jugador 1 es el que entró; "Anotar a
  // otros" vuelve a pedir los dos jugadores
  const cuenta = jugadorApi?.jugador;
  const yo = cuenta?.phone && cuenta.perfil ? { apellido: cuenta.perfil.apellido, nombre: cuenta.perfil.nombre, tel: cuenta.phone.slice(3) } : null;
  const [anotarOtros, setAnotarOtros] = useState(false);
  const vacio = { apellido: "", nombre: "", tel: "" };
  const [jugador1, setJugador1] = useState(() => yo || vacio);
  const usoMiCuenta = !!yo && !anotarOtros;
  const cambiarAnotarOtros = (otros) => { setAnotarOtros(otros); setJugador1(otros || !yo ? vacio : yo); };
  const [jugador2, setJugador2] = useState({ apellido: "", nombre: "", tel: "" });
  const [contacto, setContacto] = useState(1);
  const [website, setWebsite] = useState(""); // honeypot: una persona nunca lo ve ni lo completa
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");
  const [done, setDone] = useState(false);

  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape" && !sending) onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose, sending]);

  // Torneos clásicos: disponibilidad por cada día que cargó el organizador (nunca se asume qué días
  // son) y si pueden jugar el primer cruce de llave el mismo día que termina la zona
  // Solo los días de grupos: la disponibilidad no se usa para la llave
  const playDates = tournamentType(tournament) === "clasico" ? groupPlayDates(tournament) : [];
  const askAvailability = playDates.length > 0;
  const [availability, setAvailability] = useState(() => Object.fromEntries(playDates.map((d) => [d.date, { on: true, from: d.from, to: d.to }])));
  const [sameDayBracket, setSameDayBracket] = useState(null); // null = sin responder
  const setDay = (date, patch) => setAvailability((a) => ({ ...a, [date]: { ...a[date], ...patch } }));
  const chosenDays = playDates.filter((d) => availability[d.date]?.on).map((d) => ({ date: d.date, from: availability[d.date].from, to: availability[d.date].to }));
  const availabilityOk = !askAvailability || (chosenDays.length > 0 && chosenDays.every((d) => d.from && d.to && d.from < d.to) && sameDayBracket !== null);

  const category = categories.find((c) => c.id === categoryId);
  // Con varias categorías arranca sin ninguna elegida: el formato sale de las categorías del torneo
  // (en un Súper 8 Individual son todas individuales), así no pide dos jugadores mientras tanto
  const individual = category
    ? category.format === "super8_individual"
    : categories.length > 0 && categories.every((c) => c.format === "super8_individual");
  const full = category ? categorySpotsLeft(category) === 0 : false;
  const completo = (j) => j.apellido.trim() && j.nombre.trim() && normalizeArPhone(j.tel);
  const datosOk = completo(jugador1) && (individual || completo(jugador2));
  const ready = category && !full && datosOk && availabilityOk;

  const submit = async (e) => {
    e.preventDefault();
    if (!ready || sending) return;
    setSending(true);
    setError("");
    const disponibilidad = askAvailability ? { p_disponibilidad: chosenDays, p_cruce_mismo_dia: sameDayBracket } : {};
    const params = {
      p_torneo_id: tournament.id,
      p_categoria_id: category.id,
      p_j1_apellido: jugador1.apellido.trim(), p_j1_nombre: jugador1.nombre.trim(), p_j1_telefono: normalizeArPhone(jugador1.tel),
      ...(individual ? {} : { p_j2_apellido: jugador2.apellido.trim(), p_j2_nombre: jugador2.nombre.trim(), p_j2_telefono: normalizeArPhone(jugador2.tel), p_contacto: contacto }),
      p_honeypot: website,
      ...disponibilidad,
    };
    try {
      try {
        await supabaseRpc("inscribir_pareja", params);
      } catch (err) {
        // Si la base todavía no tiene la inscripción nueva, se inscribe como antes (sin perfiles)
        if (err.pgCode !== "PGRST202") throw err;
        const quien = (j) => nombreJugador(j);
        const contactoTel = normalizeArPhone((!individual && contacto === 2 ? jugador2 : jugador1).tel);
        await supabaseRpc("crear_inscripcion", { p_torneo_id: tournament.id, p_categoria_id: category.id, p_jugador1: quien(jugador1), p_jugador2: individual ? null : quien(jugador2), p_telefono: contactoTel, p_honeypot: website, ...disponibilidad });
      }
      setDone(true);
    } catch (err) {
      setError(inscripcionErrorText(err));
    } finally {
      setSending(false);
    }
  };

  const input = "w-full px-3 py-3 rounded-lg border outline-none text-base focus:border-lime-400";
  const inputStyle = { backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" };
  const label = "block text-xs text-teal-300 mb-1";
  const spotsText = (c) => {
    const left = categorySpotsLeft(c);
    return left == null ? "" : left === 0 ? " (completo)" : ` (quedan ${left})`;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center" style={{ backgroundColor: "rgba(0,0,0,0.7)" }} onClick={() => { if (!sending) onClose(); }}>
      <div
        role="dialog"
        aria-modal="true"
        aria-label={`Inscripción a ${tournament.name}`}
        className="w-full sm:max-w-md max-h-[92vh] overflow-y-auto rounded-t-3xl sm:rounded-2xl px-5 pt-4 sm:p-6"
        style={{ backgroundColor: "#0b1c24", color: "#e2e8f0", ...neonStyle(BRAND.cyan), paddingBottom: "calc(env(safe-area-inset-bottom) + 1.25rem)", ...F.body }}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="w-10 h-1 rounded-full mx-auto mb-4 sm:hidden" style={{ backgroundColor: "#1e3a45" }} />
        <div className="flex items-center justify-between gap-3 mb-4">
          <div className="flex items-center gap-3">
            <Logo size={40} />
            <span className="text-teal-600 text-lg">×</span>
            <OrganizerAvatar organizer={organizer} size={44} />
          </div>
          <button type="button" onClick={onClose} disabled={sending} className="text-teal-400 hover:text-lime-400 text-xl leading-none p-1" aria-label="Cerrar">✕</button>
        </div>

        <p className="text-xs text-teal-400 mb-0.5">{organizer?.name || "Organizador"}</p>
        <h2 className="text-xl mb-1" style={F.display}>{tournament.name.toUpperCase()}</h2>
        <div className="flex items-center gap-2 flex-wrap mb-5">
          <TournamentTypeTag tournament={tournament} />
          {/* Día y hora en que se juega, para que el jugador sepa cuándo le toca antes de anotarse */}
          <span className="text-sm font-semibold text-lime-400">{formatDateLong(tournament.date)}{tournamentStartTime(tournament) ? ` · ${formatHour(tournamentStartTime(tournament))}` : ""}</span>
        </div>

        {done ? (
          <div className="text-center py-4">
            <div className="w-14 h-14 rounded-full mx-auto mb-3 flex items-center justify-center text-2xl" style={{ ...neonStyle(BRAND.lime, true), color: BRAND.lime }}>✓</div>
            <p className="text-base font-semibold mb-1">¡Listo!</p>
            <p className="text-sm text-teal-200 mb-5">Tu inscripción está pendiente de confirmación del organizador.</p>
            <button type="button" onClick={onClose} className="w-full py-3 rounded-full font-semibold" style={{ backgroundColor: BRAND.lime, color: "#14181f" }}>Listo</button>
          </div>
        ) : (
          <form onSubmit={submit} className="space-y-4" noValidate>
            {categories.length > 1 ? (
              <div>
                <label className={label} htmlFor="insc-cat">Categoría</label>
                <select id="insc-cat" value={categoryId} onChange={(e) => setCategoryId(e.target.value)} className={input} style={inputStyle} required>
                  <option value="">Elegí la categoría…</option>
                  {categories.map((c) => <option key={c.id} value={c.id} disabled={categorySpotsLeft(c) === 0}>{c.name}{categoryStartLabel(c) ? ` · ${categoryStartLabel(c)}` : ""}{spotsText(c)}</option>)}
                </select>
              </div>
            ) : category && (
              <p className="text-sm">Categoría: <span className="font-semibold text-lime-400">{category.name}</span><span className="text-teal-400">{spotsText(category)}</span></p>
            )}
            {categoryStartLabel(category) && (
              <p className="text-sm -mt-2">Empieza: <span className="font-semibold text-lime-400">{categoryStartLabel(category)}</span></p>
            )}

            {[[jugador1, setJugador1, 1], ...(individual ? [] : [[jugador2, setJugador2, 2]])].map(([j, setJ, n]) => {
              const telOk = normalizeArPhone(j.tel);
              if (n === 1 && usoMiCuenta) {
                return (
                  <div key={n} className="rounded-xl p-3 flex items-center justify-between gap-3" style={{ border: `1px solid ${BRAND.lime}55` }}>
                    <div className="min-w-0">
                      <p className="text-xs text-teal-400">{individual ? "Te anotás vos" : "Jugador 1: vos"}</p>
                      <p className="font-semibold truncate">{nombreJugador(j)}</p>
                      <p className="text-xs text-teal-500">{formatArPhone(telOk)}</p>
                    </div>
                    <button type="button" onClick={() => cambiarAnotarOtros(true)} className="shrink-0 text-xs underline text-teal-300">Anotar a otros</button>
                  </div>
                );
              }
              return (
                <fieldset key={n} className="rounded-xl p-3 space-y-2" style={{ border: `1px solid ${BRAND.cyan}40` }}>
                  <legend className="px-1 text-xs text-teal-300">{individual ? "Tus datos" : `Jugador ${n}`}{n === 1 && yo && anotarOtros && <button type="button" onClick={() => cambiarAnotarOtros(false)} className="ml-2 underline text-lime-400">Anotarme yo</button>}</legend>
                  <div className="grid grid-cols-2 gap-2">
                    <div>
                      <label className={label} htmlFor={`insc-ap${n}`}>Apellido</label>
                      <input id={`insc-ap${n}`} value={j.apellido} onChange={(e) => setJ({ ...j, apellido: e.target.value })} autoComplete={n === 1 ? "family-name" : "off"} maxLength={40} className={input} style={inputStyle} placeholder={n === 1 ? "Ej: Pérez" : "Ej: López"} />
                    </div>
                    <div>
                      <label className={label} htmlFor={`insc-no${n}`}>Nombre</label>
                      <input id={`insc-no${n}`} value={j.nombre} onChange={(e) => setJ({ ...j, nombre: e.target.value })} autoComplete={n === 1 ? "given-name" : "off"} maxLength={40} className={input} style={inputStyle} placeholder={n === 1 ? "Ej: Juan" : "Ej: Martín"} />
                    </div>
                  </div>
                  <div>
                    <label className={label} htmlFor={`insc-tel${n}`}>Teléfono (WhatsApp)</label>
                    <input id={`insc-tel${n}`} type="tel" inputMode="tel" autoComplete={n === 1 ? "tel" : "off"} value={j.tel} onChange={(e) => setJ({ ...j, tel: e.target.value })} className={input} style={inputStyle} placeholder="Ej: 3446 123456" />
                    {j.tel && !telOk && <p className="text-[11px] mt-1 text-amber-400">Con característica, sin el 0 ni el 15. Ej: 11 2345 6789</p>}
                  </div>
                </fieldset>
              );
            })}
            {!individual && (
              <div>
                <p className={label}>¿A quién le escribe el organizador por WhatsApp?</p>
                <div className="flex gap-2">
                  {[1, 2].map((n) => {
                    const j = n === 1 ? jugador1 : jugador2;
                    const texto = nombreJugador(j) || `Jugador ${n}`;
                    return (
                      <button key={n} type="button" aria-pressed={contacto === n} onClick={() => setContacto(n)}
                        className="flex-1 min-w-0 py-2 px-2 rounded-full text-sm font-semibold border truncate"
                        style={contacto === n ? { backgroundColor: BRAND.lime, color: "#14181f", borderColor: BRAND.lime } : { borderColor: "#475569", color: "#cbd5e1" }}>
                        {texto}
                      </button>
                    );
                  })}
                </div>
              </div>
            )}

            {askAvailability && (
              <fieldset className="rounded-xl p-3 space-y-2" style={{ border: `1px solid ${BRAND.cyan}40` }}>
                <legend className="px-1 text-xs text-teal-300">Disponibilidad horaria de la pareja</legend>
                <p className="text-[11px] text-teal-500">Marcá los días que pueden jugar y en qué horario.</p>
                {playDates.map((d) => {
                  const day = availability[d.date] || { on: false, from: d.from, to: d.to }; // un día agregado con el formulario abierto
                  return (
                    <div key={d.date} className="flex flex-wrap items-center gap-2">
                      <label className="flex items-center gap-2 w-28 text-sm">
                        <input type="checkbox" checked={day.on} onChange={(e) => setDay(d.date, { on: e.target.checked })} className="w-4 h-4" />
                        {formatDateShort(d.date)}
                      </label>
                      {day.on ? (
                        <span className="flex items-center gap-1">
                          <input type="time" lang="es-AR" value={day.from} onChange={(e) => setDay(d.date, { from: e.target.value })} className="px-2 py-1.5 rounded border text-sm" style={inputStyle} aria-label={`Desde, ${formatDateShort(d.date)}`} />
                          <span className="text-xs text-teal-500">a</span>
                          <input type="time" lang="es-AR" value={day.to} onChange={(e) => setDay(d.date, { to: e.target.value })} className="px-2 py-1.5 rounded border text-sm" style={inputStyle} aria-label={`Hasta, ${formatDateShort(d.date)}`} />
                        </span>
                      ) : (
                        <span className="text-xs text-teal-600">No pueden</span>
                      )}
                    </div>
                  );
                })}
                {chosenDays.length === 0 && <p className="text-xs text-amber-400">Marcá al menos un día.</p>}
                <div className="pt-2">
                  <p className="text-sm mb-1.5">Si clasifican, ¿pueden jugar el primer cruce de llave el mismo día que terminan la zona?</p>
                  <div className="flex gap-2">
                    {[[true, "Sí"], [false, "No"]].map(([value, text]) => (
                      <button
                        key={text}
                        type="button"
                        aria-pressed={sameDayBracket === value}
                        onClick={() => setSameDayBracket(value)}
                        className="flex-1 py-2 rounded-full text-sm font-semibold border"
                        style={sameDayBracket === value ? { backgroundColor: BRAND.lime, color: "#14181f", borderColor: BRAND.lime } : { borderColor: "#475569", color: "#cbd5e1" }}
                      >
                        {text}
                      </button>
                    ))}
                  </div>
                </div>
              </fieldset>
            )}

            {/* Honeypot: fuera de pantalla y fuera del orden de tabulación */}
            <div aria-hidden="true" style={{ position: "absolute", left: "-10000px", width: 1, height: 1, overflow: "hidden" }}>
              <label htmlFor="insc-web">No completar</label>
              <input id="insc-web" name="website" tabIndex={-1} autoComplete="off" value={website} onChange={(e) => setWebsite(e.target.value)} />
            </div>

            {((!usoMiCuenta && (jugador1.apellido || jugador1.nombre)) || jugador2.apellido || jugador2.nombre) && !datosOk && !full && (
              <p className="text-sm text-amber-400">Completá apellido, nombre y teléfono de {individual ? "quien se inscribe" : "los dos jugadores"}.</p>
            )}
            {full && <p className="text-sm text-amber-400">El cupo de esta categoría ya está completo.</p>}
            {error && <p className="text-sm text-red-400" role="alert">{error}</p>}

            <button type="submit" disabled={!ready || sending} className="w-full py-3.5 rounded-full font-semibold text-base disabled:opacity-40" style={{ backgroundColor: BRAND.lime, color: "#14181f" }}>
              {sending ? "Enviando…" : "Enviar inscripción"}
            </button>
            <p className="text-[11px] text-teal-600 text-center">{individual ? "Tu teléfono solo lo ven" : "Sus teléfonos solo los ven"} el organizador del torneo y Smash Point, para avisar{individual ? "te" : "les"} de {individual ? "tus" : "sus"} partidos.</p>
          </form>
        )}
      </div>
    </div>
  );
}

/* Botón "Inscribirme" según el estado de las inscripciones del torneo (no se muestra si están cerradas) */
function RegisterButton({ tournament, onRegister, className = "", full = false }) {
  const status = registrationStatus(tournament);
  if (status === "cerrado") return null;
  if (status === "cerradas") {
    // El organizador cerró las inscripciones: cartel en lugar del botón
    return (
      <span className={`${full ? "w-full" : ""} inline-block text-center px-4 py-2.5 rounded-full text-sm font-semibold ${className}`} style={{ ...F.body, border: "1px solid #f8717166", color: "#fca5a5", backgroundColor: "#f8717114" }}>
        Inscripciones cerradas
      </span>
    );
  }
  const complete = status === "completo";
  return (
    <button
      type="button"
      disabled={complete}
      onClick={(e) => { e.stopPropagation(); onRegister(tournament); }}
      className={`${full ? "w-full" : ""} px-4 py-2.5 rounded-full text-sm font-semibold transition disabled:opacity-60 ${className}`}
      style={complete ? { ...F.body, border: "1px solid #475569", color: "#94a3b8" } : { ...F.body, backgroundColor: BRAND.lime, color: "#14181f", boxShadow: `0 0 14px ${BRAND.lime}55` }}
    >
      {complete ? "Cupo completo" : "Inscribirme"}
    </button>
  );
}

function OpenRegistrationsBadge({ tournament }) {
  if (registrationStatus(tournament) !== "abierto") return null;
  return (
    <span className="inline-block px-2.5 py-0.5 rounded-full text-[10px] sm:text-xs font-bold uppercase tracking-wide" style={{ ...F.body, color: BRAND.lime, border: `1px solid ${BRAND.lime}80`, backgroundColor: BRAND.lime + "1a" }}>
      ● Inscripciones abiertas
    </span>
  );
}

/* "Cartel" inclinado estilo cancha/vidriera, para títulos de sección con más pegada visual
   (ej: "ZONA A", "CANCHA 1", la fecha). Envuelve el contenido dos veces para poder inclinar
   el fondo sin inclinar el texto de adentro. */
function SkewPill({ color, textColor = "#14181f", className = "", children }) {
  return (
    <span className={`inline-block ${className}`} style={{ transform: "skewX(-8deg)" }}>
      <span
        className="inline-block px-3 py-1.5 rounded font-extrabold uppercase tracking-wide text-sm"
        style={{ backgroundColor: color, color: textColor, transform: "skewX(8deg)" }}
      >
        {children}
      </span>
    </span>
  );
}

function Badge({ status }) {
  const styles = {
    [STATUS.PROXIMO]: { backgroundColor: "#164e63", color: "#a5f3fc" },
    [STATUS.EN_CURSO]: { backgroundColor: "#9fe022", color: "#14181f" },
    [STATUS.FINALIZADO]: { backgroundColor: "#334155", color: "#cbd5e1" },
  };
  return (
    <span className="px-3 py-1 rounded-full text-xs font-semibold" style={{ ...F.body, ...styles[status] }}>
      {status === STATUS.EN_CURSO ? "● EN VIVO" : status}
    </span>
  );
}

/* En la llave, un lugar vacío es "Libre (bye)" solo si nunca va a llegar nadie (bye=false: está
   esperando al ganador de un partido sin jugar, y dice "A definir") */
function PairName({ id, pairsById, bye = true, placeholder = null, origin = null }) {
  if (id === null) return <span className="italic opacity-50">{bye ? "Libre (bye)" : placeholder || "A definir"}</span>;
  if (!id) return <span className="italic opacity-50">A definir</span>;
  // origin: de dónde viene a la llave ("1A" = 1° del Grupo A), como en los cuadros de los circuitos
  return <span>{origin && <span className="font-mono text-[10px] font-bold opacity-60 mr-1">{origin}</span>}{pairsById[id]?.name || "—"}</span>;
}

/* "#27": número del partido dentro de su categoría (ver categoryMatchNumbers) */
function MatchNumber({ n }) {
  if (!n) return null;
  return <span className="font-mono text-[10px] opacity-60">#{n}</span>;
}

/* Igual que PairName, pero para partidos de GRUPO: ahí "null" nunca es un bye (eso solo existe
   en la llave final), sino un cruce de ganadores/perdedores que todavía no tiene pareja asignada. */
function GroupPairName({ id, pairsById }) {
  if (!id) return <span className="italic opacity-50">A definir</span>;
  return <span>{pairsById[id]?.name || "—"}</span>;
}

/* Muestra el resultado set por set en modo solo lectura, ej: "6-4 · 3-6 · 10-7".
   Si se pasa winnerIsA=false, invierte cada set para que el número de la pareja ganadora
   aparezca siempre primero, así el criterio de lectura es siempre el mismo (ganador-perdedor). */
function SetsSummary({ sets, winnerIsA }) {
  const played = (sets || []).filter((s) => s && s.a != null && s.b != null);
  if (played.length === 0) return <span className="opacity-50">vs</span>;
  return (
    <span>
      {played.map((s) => (winnerIsA === false ? `${s.b}-${s.a}` : `${s.a}-${s.b}`)).join(" · ")}
    </span>
  );
}

/* Resultado de un partido en modo lectura, set a set y con el ganador primero. Un W.O. se muestra
   con el resultado con que se computa y la marca: "6-0 · 6-0 · WO" (o "7-0 · WO" en un Americano a 7). */
function MatchResultLabel({ match, winnerIsA, format }) {
  if (match && match.walkover) {
    return <span><SetsSummary sets={effectiveSets(match, format)} winnerIsA={match.walkover === match.pairA ? false : true} /> · <span className="text-amber-400 font-semibold">WO</span></span>;
  }
  // Retiro: el marcador completado a favor del rival, con la marca RET ("6-3 · 6-1 · RET")
  if (match && match.retired) {
    return <span><SetsSummary sets={effectiveSets(match, format)} winnerIsA={match.retired === match.pairA ? false : true} /> · <span className="text-red-400 font-semibold">RET</span></span>;
  }
  return <SetsSummary sets={countedSets(match, format)} winnerIsA={winnerIsA} />;
}

/* Tilde que marca a la pareja ganadora de un partido, para que se vea de un vistazo sin tener que leer el resultado */
function WinnerCheck() {
  return <span className="text-lime-400 shrink-0" aria-label="Ganador" style={{ fontWeight: 900 }}>✓</span>;
}

/* Etiqueta de estado de un partido en la tabla de horarios: Finalizado (auto), En curso (manual) o Pendiente */
function MatchStatusBadge({ status }) {
  const map = {
    finalizado: { label: "Finalizado", color: "#9fe022" },
    en_curso: { label: "En curso", color: "#fb923c" },
    pendiente: { label: "Pendiente", color: "#64748b" },
  };
  const s = map[status] || map.pendiente;
  return (
    <span
      className="text-[9px] font-bold uppercase tracking-wide px-2 py-0.5 rounded-full whitespace-nowrap"
      style={{ backgroundColor: s.color + "22", color: s.color }}
    >
      {s.label}
    </span>
  );
}

/* Tabla de posiciones completa de un grupo: PJ, PG, PP, sets a favor/en contra y diferencia,
   games a favor/en contra y diferencia, super tie-breaks ganados, y puntos */
const GROUP_COLORS = ["#9fe022", "#38bdf8", "#fb923c", "#e879f9", "#22d3ee", "#fbbf24", "#f87171", "#a78bfa"];

function StandingsTable({ group, pairsById, format, accentColor = "#9fe022", highlightCount = 2 }) {
  const table = computeStandings(group, pairsById, format);
  return (
    <div className="rounded-lg border overflow-hidden" style={{ borderColor: accentColor + "40" }}>
      {table.map((row, i) => {
        // La pareja eliminada por el organizador nunca se marca como clasificada
        const qualifies = i < highlightCount && !row.eliminated;
        const ds = row.setsF - row.setsC;
        const dg = row.gamesF - row.gamesC;
        return (
          <div
            key={row.pairId}
            className={`px-3 py-2 ${row.eliminated ? "opacity-60" : ""}`}
            style={{
              backgroundColor: i % 2 === 0 ? "transparent" : "rgba(255,255,255,0.03)",
              borderLeft: qualifies ? `3px solid ${accentColor}` : "3px solid transparent",
              borderTop: i === 0 ? "none" : "1px solid rgba(255,255,255,0.06)",
            }}
          >
            <div className="flex items-start justify-between gap-2">
              <div className="flex items-center gap-2 min-w-0">
                <span
                  className="w-6 h-6 rounded-full flex items-center justify-center text-[11px] font-extrabold shrink-0"
                  style={qualifies ? { backgroundColor: accentColor, color: "#14181f" } : { backgroundColor: "#ffffff14", color: "#94a3b8" }}
                >
                  {i + 1}
                </span>
                <span className={`text-sm ${qualifies ? "font-semibold" : ""} ${row.eliminated ? "line-through decoration-red-400/60" : ""}`} style={qualifies ? { color: accentColor } : undefined}>
                  <PairName id={row.pairId} pairsById={pairsById} />
                </span>
                {row.eliminated && <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full shrink-0" style={{ backgroundColor: "#f8717122", color: "#f87171", ...F.body }}>{row.ret ? "RET · ELIMINADA" : "ELIMINADA"}</span>}
                {row.byDraw && !row.eliminated &&<span className="text-[9px] text-teal-500 shrink-0" style={F.body} title="Empate en sets, games y resultado entre sí: el lugar se definió por sorteo">(sorteo)</span>}
              </div>
              <span className="text-sm font-semibold shrink-0" style={{ color: accentColor }}>{row.pts} pts</span>
            </div>
            <div className="text-[11px] text-teal-500 mt-1 flex flex-wrap gap-x-3 gap-y-0.5" style={F.body}>
              <span>PJ {row.pj}</span>
              <span>PG {row.pg}</span>
              <span>PP {row.pp}</span>
              <span>Sets {row.setsF}-{row.setsC} ({ds >= 0 ? "+" : ""}{ds})</span>
              <span>Games {row.gamesF}-{row.gamesC} ({dg >= 0 ? "+" : ""}{dg})</span>
              {row.stb > 0 && <span>STB {row.stb}</span>}
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* Referencia chica de qué significa cada abreviatura de la tabla de posiciones */
function StandingsLegend() {
  const items = [
    ["PJ", "Partidos Jugados"], ["PG", "Partidos Ganados"], ["PP", "Partidos Perdidos"],
    ["STB", "Super Tie-Breaks Ganados"],
  ];
  return (
    <p className="text-[11px] text-teal-600 mt-4" style={F.body}>
      {items.map(([abbr, full], i) => (
        <span key={abbr}>
          <span className="text-teal-500">{abbr}</span> = {full}{i < items.length - 1 ? " · " : ""}
        </span>
      ))}
    </p>
  );
}

/* Muestra día, hora y cancha de un partido si ya tiene horario asignado */
function ScheduleLabel({ schedule, wrap = false }) {
  const courtLabel = useCourtName();
  if (!schedule) return null;
  return (
    <span className={`text-[11px] text-teal-500 ${wrap ? "" : "whitespace-nowrap"}`} style={F.body}>
      {formatDateShort(schedule.date)} · {schedule.time}hs · {courtLabel(schedule.court)}
    </span>
  );
}

/* Llave dibujada como cuadro: una columna por ronda y cada partido centrado entre los dos que lo
   alimentan, unidos con las líneas de los cruces. Es una grilla con una fila por partido de la
   primera ronda, todas de la misma altura (la del partido más alto), y cada partido de la ronda r
   ocupa 2^r filas. */
const BRACKET_GAP_X = 28; // espacio entre rondas, donde van las líneas
const BRACKET_GAP_Y = 12;
const BRACKET_LINE = "rgba(148,163,184,0.55)";
function BracketGrid({ rounds, header, renderMatch, champion = null, colWidth = 236 }) {
  const rows = rounds[0]?.length || 1;
  const half = BRACKET_GAP_X / 2;
  const columns = rounds.length + (champion ? 1 : 0);
  return (
    <div className="overflow-x-auto pb-4">
      <div
        className="grid"
        style={{ columnGap: BRACKET_GAP_X, rowGap: BRACKET_GAP_Y, gridTemplateColumns: `repeat(${columns}, ${colWidth}px)`, gridTemplateRows: `auto repeat(${rows}, 1fr)` }}
      >
        {/* Campeón: después de la final, unido con su línea */}
        {champion && (
          <div className="relative flex items-center min-w-0" style={{ gridColumn: rounds.length + 1, gridRow: `2 / span ${rows}` }}>
            <span aria-hidden="true" className="absolute" style={{ left: -BRACKET_GAP_X, width: BRACKET_GAP_X, top: "50%", borderTop: `1.5px solid ${BRACKET_LINE}` }} />
            <div className="w-full min-w-0">{champion}</div>
          </div>
        )}
        {rounds.map((_, ri) => <div key={`h${ri}`} className="mb-1" style={{ gridColumn: ri + 1, gridRow: 1 }}>{header(ri)}</div>)}
        {rounds.map((round, ri) => round.map((m, mi) => {
          const span = 2 ** ri;
          return (
            <div key={m.id} className="relative flex items-center min-w-0" style={{ gridColumn: ri + 1, gridRow: `${mi * span + 2} / span ${span}` }}>
              {ri > 0 && (
                <>
                  {/* Las dos líneas que llegan de los partidos anteriores (a la altura del centro de
                      cada uno: un cuarto y tres cuartos de este lugar, descontando el espacio entre
                      filas) y la que baja de una a otra */}
                  <span
                    aria-hidden="true"
                    className="absolute"
                    style={{ left: -BRACKET_GAP_X, width: half, top: `calc(25% - ${BRACKET_GAP_Y / 4}px)`, bottom: `calc(25% - ${BRACKET_GAP_Y / 4}px)`, borderTop: `1.5px solid ${BRACKET_LINE}`, borderRight: `1.5px solid ${BRACKET_LINE}`, borderBottom: `1.5px solid ${BRACKET_LINE}` }}
                  />
                  {/* Y la que entra a este partido */}
                  <span aria-hidden="true" className="absolute" style={{ left: -half, width: half, top: "50%", borderTop: `1.5px solid ${BRACKET_LINE}` }} />
                </>
              )}
              <div className="w-full min-w-0">{renderMatch(m, ri, mi)}</div>
            </div>
          );
        }))}
      </div>
    </div>
  );
}

/* Recuadro del campeón al final de la llave (el ganador de la final, o "A definir") */
function BracketChampion({ name }) {
  return (
    <div className="rounded-lg p-3 text-sm text-center" style={{ ...F.body, backgroundColor: BRAND.lime + "14", border: `1.5px solid ${BRAND.lime}` }}>
      <p className="text-[11px] font-bold uppercase tracking-wide" style={{ color: BRAND.lime }}>🏆 Campeón</p>
      <p className={`mt-1 ${name ? "font-semibold" : "italic opacity-50"}`}>{name || "A definir"}</p>
    </div>
  );
}

/* En un grupo de 4 (sorteo + cruce de ganadores/perdedores), indica de qué instancia es cada partido */
function groupMatchStageLabel(group, match) {
  if (group.format !== "bracket4") return null;
  const idx = group.matches.findIndex((m) => m.id === match.id);
  if (idx === 0) return "Partido 1";
  if (idx === 1) return "Partido 2";
  if (match.stage === "ganadores") return "Cruce de ganadores";
  if (match.stage === "perdedores") return "Cruce de perdedores";
  return null;
}

/* Editor de resultado set por set para un partido, según el formato configurado del torneo */
function MatchSetsEditor({ sets, format, onSetScore, partial = false }) {
  const total = format?.setsToPlay ?? DEFAULT_MATCH_FORMAT.setsToPlay;
  const rows = Array.from({ length: total }, (_, i) => (sets && sets[i]) || { a: null, b: null });
  // En los formatos de set único (Americano, Súper 8) se avisa si el set cargado no puede ser un
  // resultado final, y se marca cuando se definió en tie break
  const singleSet = isSingleSetFormat(format);
  const { a: setA, b: setB } = rows[0];
  const singleSetLoaded = singleSet && setA != null && setB != null;
  // Con retiro (partial) el set puede haber quedado cortado: no se avisa como resultado inválido
  const singleSetInvalid = singleSetLoaded && !partial && !singleSetIsValid(setA, setB, format.gamesPerSet);
  const tieAt = format?.gamesPerSet - 1;
  const singleSetNote = !singleSetLoaded || partial ? null
    : singleSetInvalid ? `Revisá el resultado: el set termina cuando alguien llega a ${format.gamesPerSet} (en ${tieAt}-${tieAt} se juega tie break y queda ${format.gamesPerSet}-${tieAt}). Hasta corregirlo, el partido no cuenta.`
    : Math.min(setA, setB) === tieAt ? "Definido en tie break" : null;
  // A sets (Clásico): avisa del set que todavía no es un resultado final (en juego o mal tipeado) y
  // del que se cargó de más cuando el partido ya estaba definido. Esos sets no cuentan.
  let multiSetNote = null;
  if (!singleSet && !partial) {
    const f = format || DEFAULT_MATCH_FORMAT;
    const need = f.setsToPlay === 1 ? 1 : Math.floor(f.setsToPlay / 2) + 1;
    let a = 0, b = 0;
    for (let i = 0; i < rows.length && !multiSetNote; i++) {
      const s = rows[i];
      if (s.a == null && s.b == null) continue;
      const label = isSuperTiebreakSet(i, f) ? "El super tie-break" : `El set ${i + 1}`;
      if (a >= need || b >= need) multiSetNote = `${label} no cuenta: el partido ya se definió.`;
      else if (s.a == null || s.b == null) continue;
      else if (!setIsComplete(s, i, f)) multiSetNote = `${label} (${s.a}-${s.b}) todavía no es un resultado final: el partido no cuenta hasta completarlo.`;
      else if (s.a > s.b) a++; else b++;
    }
  }
  return (
    <div className="flex flex-col items-end gap-1">
      <div className="flex flex-wrap gap-2">
        {rows.map((s, i) => {
          const isTiebreak = isSuperTiebreakSet(i, format);
          return (
            <div key={i} className="flex flex-col items-center">
              <span className="text-[10px] text-teal-500 mb-0.5" style={F.body}>
                {isTiebreak ? "STB a 10" : singleSet ? `Set a ${format.gamesPerSet}` : `Set ${i + 1}`}
              </span>
              <div className="flex items-center gap-1">
                <input
                  type="number" inputMode="numeric" pattern="[0-9]*" min="0" max={isTiebreak ? undefined : 9}
                  maxLength={isTiebreak ? 2 : 1}
                  className="w-12 h-10 px-1 rounded border text-center text-base"
                  style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }}
                  value={s.a ?? ""}
                  onChange={(e) => {
                    const raw = e.target.value;
                    const limit = isTiebreak ? 2 : 1;
                    if (raw.length > limit) return;
                    onSetScore(i, "a", raw === "" ? null : Number(raw));
                  }}
                />
                <span className="text-xs text-teal-500">-</span>
                <input
                  type="number" inputMode="numeric" pattern="[0-9]*" min="0" max={isTiebreak ? undefined : 9}
                  maxLength={isTiebreak ? 2 : 1}
                  className="w-12 h-10 px-1 rounded border text-center text-base"
                  style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }}
                  value={s.b ?? ""}
                  onChange={(e) => {
                    const raw = e.target.value;
                    const limit = isTiebreak ? 2 : 1;
                    if (raw.length > limit) return;
                    onSetScore(i, "b", raw === "" ? null : Number(raw));
                  }}
                />
              </div>
            </div>
          );
        })}
      </div>
      {singleSetNote && (
        <span className={`text-[10px] text-right ${singleSetInvalid ? "text-amber-400" : "text-teal-500"}`} style={F.body}>{singleSetNote}</span>
      )}
      {multiSetNote && <span className="text-[10px] text-right text-amber-400 max-w-[16rem]" style={F.body}>{multiSetNote}</span>}
    </div>
  );
}

/* Opción grande de elección múltiple (tipo de torneo, Individual/Por Parejas, games) */
function ChoiceCard({ selected, onClick, title, description, compact = false }) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-pressed={selected}
      className={`text-left rounded-lg border transition ${compact ? "px-4 py-2" : "px-4 py-3"} ${selected ? "border-lime-400" : "border-teal-800 hover:border-teal-500"}`}
      style={{ backgroundColor: selected ? "rgba(159,224,34,0.1)" : "transparent", ...F.body }}
    >
      <span className={`block font-semibold ${compact ? "text-sm" : ""} ${selected ? "text-lime-400" : ""}`}>{title}</span>
      {description && <span className="block text-xs text-teal-400 mt-0.5">{description}</span>}
    </button>
  );
}

const TOURNAMENT_TYPE_DESCRIPTION = {
  clasico: "Zonas + llave final, partidos por sets y grilla de horarios.",
  super8: "8 jugadores u 8 parejas por categoría, a un solo set. Termina en tabla de posiciones.",
  americano: "Zonas + llave final en un solo día, con un set único a 7 o a 9 games.",
};

/* Paso 1: elegir el tipo de torneo. Al cambiar de tipo se limpian las opciones del anterior. */
function TournamentTypeChoice({ config, onChange }) {
  return (
    <div className="grid gap-2">
      {Object.keys(TOURNAMENT_TYPE_LABEL).map((type) => (
        <ChoiceCard
          key={type}
          selected={config.type === type}
          onClick={() => { if (config.type !== type) onChange({ type, super8Mode: null, games: null }); }}
          title={TOURNAMENT_TYPE_LABEL[type]}
          description={TOURNAMENT_TYPE_DESCRIPTION[type]}
        />
      ))}
    </div>
  );
}

/* Paso 2: las preguntas propias de cada tipo (el Clásico no tiene ninguna acá) */
function TournamentTypeOptions({ config, onChange }) {
  const label = "block text-xs text-teal-400 mb-2";
  const gamesChoice = (options, format) => (
    <div className="flex flex-wrap gap-2">
      {options.map((g) => (
        <ChoiceCard key={g} compact selected={config.games === g} onClick={() => onChange({ ...config, games: g })} title={format(g)} />
      ))}
    </div>
  );
  const tiebreakNote = config.games && (
    <p className="text-[11px] text-teal-500 mt-2" style={F.body}>
      En {config.games - 1}-{config.games - 1} se define con tie break a 7 puntos (diferencia de 2) y el set queda {config.games}-{config.games - 1}.
    </p>
  );

  if (config.type === "super8") {
    return (
      <div>
        <p className="text-sm font-semibold mb-3 px-3 py-2 rounded border border-lime-400 text-lime-400" style={{ backgroundColor: "rgba(159,224,34,0.08)", ...F.body }}>
          El Súper 8 se juega a un solo set.
        </p>
        <p className={label} style={F.body}>¿Individual o por parejas?</p>
        <div className="grid sm:grid-cols-2 gap-2 mb-4">
          <ChoiceCard selected={config.super8Mode === "individual"} onClick={() => onChange({ ...config, super8Mode: "individual" })} title="Individual" description="8 jugadores sueltos: cada uno juega una vez con cada otro como compañero." />
          <ChoiceCard selected={config.super8Mode === "parejas"} onClick={() => onChange({ ...config, super8Mode: "parejas" })} title="Por Parejas" description="8 parejas armadas, todas contra todas." />
        </div>
        {config.super8Mode && (
          <div>
            <p className={label} style={F.body}>¿A cuántos games se juega cada partido?</p>
            {gamesChoice(SUPER8_GAMES_OPTIONS, (g) => `${g} games`)}
            {tiebreakNote}
          </div>
        )}
      </div>
    );
  }
  if (config.type === "americano") {
    return (
      <div>
        <p className={label} style={F.body}>¿A cuántos games se juega cada partido?</p>
        {gamesChoice(AMERICANO_GAMES_OPTIONS, (g) => `A${g}`)}
        {tiebreakNote}
      </div>
    );
  }
  return null;
}

/* Formato de partido del Clásico: sets, games por set y tie breaks */
function ClassicMatchFormatFields({ format, onChange }) {
  const f = format || DEFAULT_MATCH_FORMAT;
  const [gamesText, setGamesText] = useState(String(f.gamesPerSet));
  return (
    <div className="flex flex-wrap gap-4 items-end">
      <div>
        <label className="block text-xs text-teal-400 mb-1" style={F.body}>Sets</label>
        <select
          value={f.setsToPlay}
          onChange={(e) => onChange({ ...f, setsToPlay: Number(e.target.value) })}
          className="px-3 py-2 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }}
        >
          <option value={2}>2 sets directos</option>
          <option value={3}>Al mejor de 3</option>
        </select>
      </div>
      <div>
        <label className="block text-xs text-teal-400 mb-1" style={F.body}>Games por set</label>
        <input
          type="number" min="1" inputMode="numeric"
          value={gamesText}
          onChange={(e) => setGamesText(e.target.value)}
          onBlur={() => {
            const n = Number(gamesText);
            const valid = gamesText.trim() !== "" && n >= 1;
            const final = valid ? n : f.gamesPerSet;
            setGamesText(String(final));
            if (final !== f.gamesPerSet) onChange({ ...f, gamesPerSet: final });
          }}
          className="w-20 px-3 py-2 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }}
        />
      </div>
      <label className="flex items-center gap-2 text-sm" style={F.body}>
        <input type="checkbox" checked={f.setTiebreak} onChange={(e) => onChange({ ...f, setTiebreak: e.target.checked })} />
        Tie break a 7 puntos dentro del set
      </label>
      {f.setsToPlay >= 3 && <label className="flex items-center gap-2 text-sm" style={F.body}>
        <input type="checkbox" checked={f.finalSuperTiebreak} onChange={(e) => onChange({ ...f, finalSuperTiebreak: e.target.checked })} />
        Super tie-break a 10 en el set decisivo
      </label>}
    </div>
  );
}

/* Nombre del tipo de torneo: "Clásico", "Súper 8 Individual", "Americano"... */
function tournamentTypeName(t) {
  const { type, super8Mode } = tournamentConfig(t);
  return type === "super8" && super8Mode ? `${TOURNAMENT_TYPE_LABEL.super8} ${SUPER8_MODE_LABEL[super8Mode]}` : TOURNAMENT_TYPE_LABEL[type];
}

/* Etiqueta con el tipo de torneo para las tarjetas: "Clásico", "Súper 8 Individual · 6 games",
   "Americano · A7". Cada tipo tiene su color. */
const TOURNAMENT_TYPE_COLOR = { clasico: "#38bdf8", super8: "#e879f9", americano: "#fb923c" };

function TournamentTypeTag({ tournament, short = false }) {
  const size = short ? "px-2 py-0.5 text-[9px]" : "px-2.5 py-0.5 text-[10px] sm:text-xs";
  if (isInfoOnly(tournament)) {
    return (
      <span className={`inline-block rounded-full font-bold uppercase tracking-wide whitespace-nowrap ${size}`} style={{ ...F.body, color: "#e2e8f0", border: "1px solid #94a3b880", backgroundColor: "#94a3b81a" }}>
        Solo información
      </span>
    );
  }
  const { type, games } = tournamentConfig(tournament);
  const color = TOURNAMENT_TYPE_COLOR[type];
  const detail = type === "americano" && games ? ` · A${games}` : type === "super8" && games ? ` · ${games} games` : "";
  // short: solo el tipo, para tarjetas angostas (el detalle está en el torneo)
  return (
    <span className={`inline-block rounded-full font-bold uppercase tracking-wide ${short ? "whitespace-nowrap" : ""} ${size}`} style={{ ...F.body, color, border: `1px solid ${color}80`, backgroundColor: color + "1a" }}>
      {short ? TOURNAMENT_TYPE_LABEL[type] : `${tournamentTypeName(tournament)}${detail}`}
    </span>
  );
}

/* Tipo de torneo en una línea: "Súper 8 Individual · un solo set a 6 games · ..." */
function tournamentTypeSummary(t) {
  return `${tournamentTypeName(t)} · ${formatSummary(t.matchFormat)}`;
}

/* Panel para ver y cambiar el tipo de torneo y su configuración después de creado. Los cambios se
   preparan en un borrador y se aplican con "Guardar". */
function TournamentTypeEditor({ tournament, update }) {
  const [open, setOpen] = useState(false);
  const [config, setConfig] = useState(() => tournamentConfig(tournament));
  const [classicFormat, setClassicFormat] = useState(() => (isSingleSetFormat(tournament.matchFormat) ? { ...DEFAULT_MATCH_FORMAT } : tournament.matchFormat || { ...DEFAULT_MATCH_FORMAT }));
  const blocked = tournamentConfigChangeBlocked(tournament, config);
  const hasResults = tournamentHasScores(tournament);

  const start = () => {
    setConfig(tournamentConfig(tournament));
    setClassicFormat(isSingleSetFormat(tournament.matchFormat) ? { ...DEFAULT_MATCH_FORMAT } : tournament.matchFormat || { ...DEFAULT_MATCH_FORMAT });
    setOpen(true);
  };
  const save = () => {
    if (!tournamentConfigIsComplete(config) || blocked) return;
    const next = withTournamentConfig(tournament, config);
    update(config.type === "clasico" ? { ...next, matchFormat: classicFormat } : next);
    setOpen(false);
  };

  return (
    <div className="border border-teal-800 rounded-lg p-4 mb-6">
      <div className="flex justify-between items-center flex-wrap gap-2">
        <div>
          <p className="text-sm font-semibold" style={F.body}>Tipo de torneo</p>
          <p className="text-xs text-teal-400" style={F.body}>{tournamentTypeSummary(tournament)}</p>
        </div>
        <button type="button" onClick={() => (open ? setOpen(false) : start())} className="text-sm text-teal-300 hover:text-lime-400" style={F.body}>
          {open ? "Cancelar" : "Editar"}
        </button>
      </div>

      {open && (
        <div className="mt-4 space-y-4">
          <TournamentTypeChoice config={config} onChange={setConfig} />
          <TournamentTypeOptions config={config} onChange={setConfig} />
          {config.type === "clasico" && <ClassicMatchFormatFields format={classicFormat} onChange={setClassicFormat} />}
          {blocked && (
            <p className="text-xs text-amber-400" style={F.body}>
              Hay categorías con partidos ya armados en otro formato. Para este cambio, primero reiniciá sus grupos o partidos.
            </p>
          )}
          {!blocked && hasResults && (
            <p className="text-[11px] text-amber-400" style={F.body}>
              Ya hay resultados cargados: si cambiás el formato, esos resultados se van a leer con el formato nuevo.
            </p>
          )}
          <button
            type="button"
            onClick={save}
            disabled={!tournamentConfigIsComplete(config) || blocked}
            className="px-4 py-2 rounded font-semibold text-sm disabled:opacity-40" style={{ backgroundColor: "#9fe022", color: "#14181f" }}
          >
            Guardar
          </button>
        </div>
      )}
    </div>
  );
}

/* Interruptor sí/no */
function Toggle({ checked, onChange, label, description }) {
  return (
    <label className="flex items-start gap-3 cursor-pointer select-none" style={F.body}>
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        onClick={() => onChange(!checked)}
        className="relative w-11 h-6 rounded-full shrink-0 mt-0.5 transition"
        style={{ backgroundColor: checked ? BRAND.lime : "#1e3a45", boxShadow: checked ? `0 0 10px ${BRAND.lime}66` : "none" }}
      >
        <span className="absolute top-0.5 w-5 h-5 rounded-full bg-white transition-all" style={{ left: checked ? "1.375rem" : "0.125rem" }} />
      </button>
      <span>
        <span className="block text-sm font-semibold">{label}</span>
        {description && <span className="block text-xs text-teal-400">{description}</span>}
      </span>
    </label>
  );
}

/* Inscripciones online de un torneo: el interruptor y el cupo de cada categoría (vacío = sin límite;
   el Súper 8 es siempre de 8). rows: [{ key, name, fixed, value }] */
function RegistrationSettings({ open, onOpenChange, rows, onCupoChange }) {
  return (
    <div className="rounded-lg border border-teal-800 p-3 space-y-3">
      <Toggle
        checked={open}
        onChange={onOpenChange}
        label="Inscripciones abiertas"
        description="Los jugadores se anotan solos desde la página pública y vos aceptás o rechazás cada inscripción."
      />
      {open && rows.length > 0 && (
        <div>
          <p className="text-xs text-teal-400 mb-2" style={F.body}>Cupo por categoría (cuentan todas las parejas anotadas; vacío = sin límite)</p>
          <div className="space-y-1.5">
            {rows.map((r) => (
              <div key={r.key} className="flex items-center justify-between gap-3 text-sm" style={F.body}>
                <span className="truncate">{r.name}</span>
                {r.fixed ? (
                  <span className="text-xs text-teal-500">{r.fixed}</span>
                ) : (
                  <input
                    type="number" min="1" inputMode="numeric"
                    value={r.value}
                    onChange={(e) => onCupoChange(r.key, e.target.value)}
                    placeholder="Sin límite"
                    className="w-28 px-2 py-1.5 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }}
                  />
                )}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* Texto del campo de cupo → número entero positivo, o null (sin límite) */
function parseCupo(text) {
  const n = Number(text);
  return String(text).trim() !== "" && Number.isInteger(n) && n > 0 ? n : null;
}

/* Ventana emergente centrada sobre la pantalla */
function Modal({ title, onClose, children }) {
  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);
  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center p-4 overflow-y-auto" style={{ backgroundColor: "rgba(0,0,0,0.7)" }} onClick={onClose}>
      <div
        role="dialog"
        aria-modal="true"
        aria-label={title}
        className="w-full max-w-lg rounded-xl border border-teal-800 p-5 sm:p-6 my-4 sm:my-auto"
        style={{ backgroundColor: "#1b2027", color: "#e2e8f0" }}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex justify-between items-start gap-3 mb-4">
          <h2 className="text-lg" style={F.display}>{title}</h2>
          <button type="button" onClick={onClose} className="text-teal-400 hover:text-lime-400 text-lg leading-none" aria-label="Cerrar">✕</button>
        </div>
        {children}
      </div>
    </div>
  );
}

/* Creación de torneo paso a paso:
   1. Tipo de torneo (Clásico, Súper 8 o Americano).
   2. Nombre, fecha y circuito, más las preguntas propias del tipo elegido.
   3. Categorías que va a tener el torneo (después se pueden agregar o quitar desde el torneo). */
function CreateTournamentWizard({ circuits, onCreate, onClose }) {
  const [step, setStep] = useState(1);
  const [config, setConfig] = useState({ type: null, super8Mode: null, games: null });
  const [name, setName] = useState("");
  const [date, setDate] = useState("");
  const [circuitId, setCircuitId] = useState("");
  const [categoryNames, setCategoryNames] = useState([]);
  const [categoryText, setCategoryText] = useState("");
  const [registrationOpen, setRegistrationOpen] = useState(false);
  const [cupos, setCupos] = useState({}); // { [nombre de categoría]: texto del cupo }
  // Americano: se juega en un solo día, así que la grilla se arma con estos tres datos
  const [courtsText, setCourtsText] = useState("2");
  const [startTime, setStartTime] = useState("09:00");
  const [intervalText, setIntervalText] = useState("40");
  // Súper 8: null = todavía no lo tocó, se usa el valor sugerido según el tipo (Individual o Parejas)
  const [super8CourtsChosen, setSuper8CourtsChosen] = useState(null);
  const super8 = config.type === "super8";
  const super8Courts = Math.min(super8CourtsChosen ?? super8DefaultCourts(config.super8Mode), super8MaxCourts(config.super8Mode));
  const americano = config.type === "americano";
  const courts = Number(courtsText), interval = Number(intervalText);
  const scheduleReady = !americano || (Number.isInteger(courts) && courts >= 1 && startTime && Number.isInteger(interval) && interval >= 10);

  const addCategoryName = () => {
    const n = categoryText.trim();
    if (!n) return;
    if (!categoryNames.some((c) => c.toLowerCase() === n.toLowerCase())) setCategoryNames([...categoryNames, n]);
    setCategoryText("");
  };
  const step2Ready = name.trim() && date && tournamentConfigIsComplete(config) && scheduleReady;
  // Si quedó un nombre escrito sin tocar "Agregar", también se crea
  const pending = categoryText.trim();
  const finalNames = pending && !categoryNames.some((c) => c.toLowerCase() === pending.toLowerCase()) ? [...categoryNames, pending] : categoryNames;
  const create = () => {
    if (!step2Ready || finalNames.length === 0) return;
    // Súper 8: las canchas elegidas acá; se pueden cambiar después en sus partidos
    const schedule = americano ? { courtsCount: courts, matchDurationMinutes: interval, playDates: [{ date, from: startTime, to: "23:59" }] }
      : super8 ? { courtsCount: super8Courts } : null;
    onCreate({
      name: name.trim(), date, circuitId: config.type === "clasico" ? circuitId || null : null, config, schedule,
      categories: finalNames.map((n) => ({ name: n, cupo: super8 ? null : parseCupo(cupos[n] ?? "") })),
      inscripcionesAbiertas: registrationOpen,
    });
    onClose();
  };

  const input = { backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" };
  const primary = "px-4 py-2 rounded font-semibold text-sm disabled:opacity-40";
  const primaryStyle = { backgroundColor: "#9fe022", color: "#14181f", ...F.body };
  const back = (to) => <button type="button" onClick={() => setStep(to)} className="text-sm text-teal-400 hover:text-lime-400" style={F.body}>← Atrás</button>;

  return (
    <Modal title={`Nuevo torneo · Paso ${step} de 3`} onClose={onClose}>
      {step === 1 && (
        <div>
          <p className="text-sm text-teal-300 mb-3" style={F.body}>¿Qué tipo de torneo vas a organizar?</p>
          <TournamentTypeChoice config={config} onChange={setConfig} />
          <div className="flex justify-end mt-5">
            <button type="button" disabled={!config.type} onClick={() => setStep(2)} className={primary} style={primaryStyle}>Siguiente</button>
          </div>
        </div>
      )}

      {step === 2 && (
        <div>
          <p className="text-xs text-lime-400 mb-3 font-semibold" style={F.body}>{TOURNAMENT_TYPE_LABEL[config.type]}</p>
          <label className="block text-xs text-teal-400 mb-1" style={F.body}>Nombre del torneo</label>
          <input value={name} onChange={(e) => setName(e.target.value)} autoFocus className="w-full mb-3 px-3 py-2 rounded border outline-none focus:border-lime-400" style={input} />
          <div className="flex flex-wrap gap-3 mb-4">
            <div>
              <label className="block text-xs text-teal-400 mb-1" style={F.body}>Fecha</label>
              <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="px-3 py-2 rounded border outline-none focus:border-lime-400" style={input} />
            </div>
            {config.type === "clasico" && (
              <div>
                <label className="block text-xs text-teal-400 mb-1" style={F.body}>Circuito (opcional)</label>
                <select value={circuitId} onChange={(e) => setCircuitId(e.target.value)} className="px-3 py-2 rounded border text-sm" style={input}>
                  <option value="">Sin circuito (torneo independiente)</option>
                  {circuits.map((c) => <option key={c.id} value={c.id}>{c.name} {c.year}</option>)}
                </select>
              </div>
            )}
          </div>
          <TournamentTypeOptions config={config} onChange={setConfig} />
          {super8 && config.super8Mode && (
            <div className="mt-4">
              <Super8CourtsField courts={super8Courts} individual={config.super8Mode === "individual"} onChange={setSuper8CourtsChosen} />
              <p className="text-[11px] text-teal-600 -mt-2" style={F.body}>Se puede cambiar después en los partidos del torneo.</p>
            </div>
          )}
          {americano && (
            <div className="mt-4">
              <p className="block text-xs text-teal-400 mb-2" style={F.body}>Horarios del día</p>
              <div className="flex flex-wrap gap-3">
                <div>
                  <label className="block text-[11px] text-teal-500 mb-1" style={F.body}>Canchas</label>
                  <input type="number" min="1" inputMode="numeric" value={courtsText} onChange={(e) => setCourtsText(e.target.value)} className="w-20 px-3 py-2 rounded border outline-none focus:border-lime-400" style={input} />
                </div>
                <div>
                  <label className="block text-[11px] text-teal-500 mb-1" style={F.body}>Horario de arranque</label>
                  <input type="time" lang="es-AR" value={startTime} onChange={(e) => setStartTime(e.target.value)} className="px-3 py-2 rounded border outline-none focus:border-lime-400" style={input} />
                </div>
                <div>
                  <label className="block text-[11px] text-teal-500 mb-1" style={F.body}>Tiempo entre partidos (min)</label>
                  <input type="number" min="10" step="5" inputMode="numeric" value={intervalText} onChange={(e) => setIntervalText(e.target.value)} className="w-24 px-3 py-2 rounded border outline-none focus:border-lime-400" style={input} />
                </div>
              </div>
              <p className="text-[11px] text-teal-600 mt-2" style={F.body}>Cada cancha arranca un partido nuevo cada {interval >= 10 ? interval : "…"} minutos. Se puede ajustar después en Configuración.</p>
            </div>
          )}
          <div className="flex justify-between items-center mt-5">
            {back(1)}
            <button type="button" disabled={!step2Ready} onClick={() => setStep(3)} className={primary} style={primaryStyle}>Siguiente</button>
          </div>
        </div>
      )}

      {step === 3 && (
        <div>
          <p className="text-sm text-teal-300 mb-1" style={F.body}>¿Qué categorías va a tener el torneo?</p>
          <p className="text-xs text-teal-500 mb-3" style={F.body}>
            {super8
              ? `Cada categoría admite exactamente 8 ${config.super8Mode === "individual" ? "jugadores" : "parejas"}. `
              : ""}
            {super8 ? "Los inscriptos" : "Las parejas"} se cargan después, a medida que se anotan. Más adelante también podés agregar o quitar categorías.
          </p>
          <div className="flex gap-2 mb-3">
            <input
              value={categoryText}
              onChange={(e) => setCategoryText(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") addCategoryName(); }}
              placeholder="Ej: 4ta Caballeros"
              autoFocus
              className="flex-1 min-w-0 px-3 py-2 rounded border outline-none focus:border-lime-400" style={input}
            />
            <button type="button" onClick={addCategoryName} className="px-4 py-2 rounded font-semibold text-sm" style={primaryStyle}>Agregar</button>
          </div>
          <div className="flex flex-wrap gap-2 min-h-[2rem]">
            {categoryNames.map((c, i) => {
              const color = GROUP_COLORS[i % GROUP_COLORS.length];
              return (
                <span key={c} className="flex items-center gap-2 px-3 py-1 rounded-full text-sm border" style={{ backgroundColor: color + "14", color, borderColor: color + "40", ...F.body }}>
                  {c}
                  <button type="button" onClick={() => setCategoryNames(categoryNames.filter((x) => x !== c))} aria-label={`Quitar ${c}`} className="opacity-70 hover:opacity-100">✕</button>
                </span>
              );
            })}
            {categoryNames.length === 0 && <p className="text-xs opacity-60" style={F.body}>Agregá al menos una categoría.</p>}
          </div>
          <div className="mt-4">
            <RegistrationSettings
              open={registrationOpen}
              onOpenChange={setRegistrationOpen}
              rows={categoryNames.map((n) => ({ key: n, name: n, fixed: super8 ? "8 (Súper 8)" : null, value: cupos[n] ?? "" }))}
              onCupoChange={(key, text) => setCupos({ ...cupos, [key]: text })}
            />
          </div>
          <div className="flex justify-between items-center mt-5">
            {back(2)}
            <button type="button" disabled={finalNames.length === 0} onClick={create} className={primary} style={primaryStyle}>Crear torneo</button>
          </div>
        </div>
      )}
    </Modal>
  );
}

/* Panel de canchas disponibles y fechas puntuales en que se juega el torneo */
function CourtsAndDatesEditor({ tournament, onChange }) {
  const [newDate, setNewDate] = useState("");
  const [newFrom, setNewFrom] = useState("09:00");
  const [newTo, setNewTo] = useState("22:00");
  const [courtsText, setCourtsText] = useState(String(tournament.courtsCount ?? 4));
  // Las sedes también cambian la cantidad de canchas: el campo sigue al valor guardado
  useEffect(() => { setCourtsText(String(tournament.courtsCount ?? 4)); }, [tournament.courtsCount]);
  const [durationText, setDurationText] = useState(String(tournament.matchDurationMinutes ?? DEFAULT_MATCH_DURATION));
  const dates = tournament.playDates || [];
  const singleDay = tournamentType(tournament) === "americano"; // el Americano se juega en un solo día
  const classic = tournamentType(tournament) === "clasico";
  const venues = tournament.venues || [];

  const addDate = () => {
    if (!newDate || dates.some((d) => d.date === newDate)) return;
    const added = { date: newDate, from: newFrom, to: newTo, ...(classic ? { useAuto: true } : {}) };
    const next = [...dates, added].sort((a, b) => (a.date < b.date ? -1 : 1));
    onChange({ ...tournament, playDates: classic ? withAutoDayUses(next) : next });
    setNewDate("");
  };
  const removeDate = (date) => {
    const next = dates.filter((d) => d.date !== date);
    onChange({ ...tournament, playDates: classic ? withAutoDayUses(next) : next });
  };
  const updateDateRange = (date, side, value) => {
    onChange({ ...tournament, playDates: dates.map((d) => (d.date === date ? { ...d, [side]: value } : d)) });
  };
  // Elegido a mano: ya no lo recalcula la app
  const setDayUse = (date, use) => {
    onChange({ ...tournament, playDates: dates.map((d) => (d.date === date ? { ...d, use, useAuto: false } : d)) });
  };

  return (
    <div className="border border-teal-800 rounded-lg p-4 mb-6">
      <p className="text-sm font-semibold mb-3" style={F.body}>{singleDay ? "Canchas y horario del día" : "Canchas y fechas del torneo"}</p>
      <div className="flex flex-wrap gap-4 items-end mb-4">
        {venues.length > 0 ? (
          <div>
            <p className="block text-xs text-teal-400 mb-1" style={F.body}>Cantidad de canchas</p>
            <p className="px-3 py-2 text-sm font-semibold" style={F.body}>{tournament.courtsCount} <span className="text-xs text-teal-500 font-normal">(suma de las sedes)</span></p>
          </div>
        ) : (
          <div>
            <label className="block text-xs text-teal-400 mb-1" style={F.body}>Cantidad de canchas</label>
            <input
              type="number" min="1" inputMode="numeric"
              value={courtsText}
              onChange={(e) => setCourtsText(e.target.value)}
              onBlur={() => {
                const n = Number(courtsText);
                const valid = courtsText.trim() !== "" && n >= 1;
                const final = valid ? n : (tournament.courtsCount ?? 4);
                setCourtsText(String(final));
                if (final !== tournament.courtsCount) onChange({ ...tournament, courtsCount: final });
              }}
              className="w-20 px-3 py-2 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }}
            />
          </div>
        )}
        <div>
          <label className="block text-xs text-teal-400 mb-1" style={F.body}>{singleDay ? "Tiempo entre partidos (min)" : "Duración de partido (min)"}</label>
          <input
            type="number" min="10" step="5" inputMode="numeric"
            value={durationText}
            onChange={(e) => setDurationText(e.target.value)}
            onBlur={() => {
              const n = Number(durationText);
              const valid = durationText.trim() !== "" && n >= 10;
              const final = valid ? n : (tournament.matchDurationMinutes ?? DEFAULT_MATCH_DURATION);
              setDurationText(String(final));
              if (final !== tournament.matchDurationMinutes) onChange({ ...tournament, matchDurationMinutes: final });
            }}
            className="w-24 px-3 py-2 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }}
          />
        </div>
        {classic && (
          <div>
            <label className="block text-xs text-teal-400 mb-1" style={F.body}>Llave: entre partidos de una pareja</label>
            <select
              value={tournament.bracketRestMinutes || DEFAULT_BRACKET_REST}
              onChange={(e) => onChange({ ...tournament, bracketRestMinutes: Number(e.target.value) })}
              title="Tiempo mínimo entre que empieza un partido de llave de una pareja y empieza el siguiente (también desde su último partido de grupos)"
              className="px-3 py-2 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }}
            >
              {BRACKET_REST_OPTIONS.map((min) => <option key={min} value={min}>{formatRest(min)}{min === DEFAULT_BRACKET_REST ? " (recomendado)" : ""}</option>)}
            </select>
          </div>
        )}
      </div>
      {classic && <VenuesField tournament={tournament} onChange={onChange} />}
      {classic && venues.length >= 2 && (
        <label className="flex items-start gap-2 text-sm mb-4 cursor-pointer" style={F.body}>
          <input type="checkbox" className="mt-1" checked={groupsInOneVenue(tournament)} onChange={(e) => onChange({ ...tournament, groupsOneVenue: e.target.checked })} />
          <span>
            Cada grupo juega en una sola sede
            <span className="block text-[11px] text-teal-600">Todos los partidos de un grupo en la misma sede (y si se puede, en la misma cancha). Si alguno no entra ahí, va a otra sede y te avisamos. Se aplica al generar o rearmar los horarios.</span>
          </span>
        </label>
      )}
      <label className="block text-xs text-teal-400 mb-1" style={F.body}>{singleDay ? "Día y horario en que se juega" : "Fechas y horario en que se juega cada una"}</label>
      {classic && dates.length > 0 && (
        <p className="text-[11px] text-teal-600 mb-2" style={F.body}>Grupos: ahí se arman los horarios de los grupos y la inscripción pide disponibilidad. Llaves: ahí se juega la llave. Ambos: las dos cosas.</p>
      )}
      <div className="space-y-2 mb-4">
        {dates.map((d) => (
          <div key={d.date} className="border border-teal-800 rounded-lg px-3 py-3 text-sm" style={F.body}>
            <div className="flex items-center justify-between gap-2 mb-2">
              <span className="text-teal-200 font-medium">{formatDateShort(d.date)}</span>
              <span className="flex items-center gap-3">
                {classic && (
                  <select
                    value={dayUse(d)}
                    onChange={(e) => setDayUse(d.date, e.target.value)}
                    aria-label={`Para qué es el ${formatDateShort(d.date)}`}
                    className="px-2 py-1 rounded border text-xs" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }}
                  >
                    {DAY_USES.map(([value, label]) => <option key={value} value={value}>{label}</option>)}
                  </select>
                )}
                <button type="button" onClick={() => removeDate(d.date)} className="text-red-400 text-xs">Quitar ✕</button>
              </span>
            </div>
            <div className="flex items-center gap-2">
              <input type="time" lang="es-AR" value={d.from} onChange={(e) => updateDateRange(d.date, "from", e.target.value)} className="flex-1 min-w-0 px-2 py-1.5 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }} />
              <span className="text-xs text-teal-500 shrink-0">a</span>
              <input type="time" lang="es-AR" value={d.to} onChange={(e) => updateDateRange(d.date, "to", e.target.value)} aria-invalid={!!(d.from && d.to && d.to <= d.from)} className="flex-1 min-w-0 px-2 py-1.5 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }} />
            </div>
            {d.from && d.to && d.to <= d.from && <p className="text-xs text-amber-400 mt-1" style={F.body}>Ese día no tiene turnos: tiene que terminar después de que empieza. Si se juega hasta medianoche, poné 23:59.</p>}
          </div>
        ))}
        {dates.length === 0 && <p className="text-xs opacity-60" style={F.body}>Todavía no agregaste fechas.</p>}
      </div>
      {!(singleDay && dates.length > 0) && <div className="border-t border-teal-800 pt-3 space-y-2">
        <div>
          <label className="block text-xs text-teal-400 mb-1" style={F.body}>Fecha nueva</label>
          <input
            type="date"
            value={newDate}
            onChange={(e) => setNewDate(e.target.value)}
            className="w-full px-3 py-2 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }}
          />
        </div>
        <div className="flex gap-2">
          <div className="flex-1 min-w-0">
            <label className="block text-xs text-teal-400 mb-1" style={F.body}>Desde</label>
            <input type="time" lang="es-AR" value={newFrom} onChange={(e) => setNewFrom(e.target.value)} className="w-full px-2 py-2 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }} />
          </div>
          <div className="flex-1 min-w-0">
            <label className="block text-xs text-teal-400 mb-1" style={F.body}>Hasta</label>
            <input type="time" lang="es-AR" value={newTo} onChange={(e) => setNewTo(e.target.value)} className="w-full px-2 py-2 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }} />
          </div>
        </div>
        <button type="button" onClick={addDate} className="w-full px-3 py-2 rounded font-semibold text-sm" style={{ backgroundColor: "#9fe022", color: "#14181f" }}>
          Agregar fecha
        </button>
      </div>}
      {tournamentType(tournament) === "clasico" && dates.length > 0 && tournament.categories.length > 0 && (
        <CategoryStartsEditor tournament={tournament} onChange={onChange} />
      )}
    </div>
  );
}

/* Clásico: varias sedes, cada una con sus canchas. La cantidad de canchas del torneo pasa a ser la
   suma, numeradas de corrido para armar los horarios, y en pantalla se muestran con su sede (ver
   courtName). Sin sedes, el torneo usa solo "Cantidad de canchas", como siempre.
   Cada sede se elige de la lista de Complejos (complexId: de ahí sale el logo de la imagen del
   fixture) o, con "Otra sede…", se escribe a mano. */
function VenuesField({ tournament, onChange }) {
  const venues = tournament.venues || [];
  const dates = tournament.playDates || [];
  const complexes = React.useContext(ComplexesContext);
  const sortedComplexes = [...complexes].sort((a, b) => a.name.localeCompare(b.name, "es"));
  const chooseComplex = (v, complexId) => {
    const c = complexes.find((x) => x.id === complexId);
    update(v.id, c ? { complexId: c.id, name: c.name } : { complexId: null, name: v.complexId ? "" : v.name });
  };
  const input = { backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" };
  const save = (next) => {
    const clean = next.map((v) => ({ ...v, courts: Math.max(1, Number(v.courts) || 1) }));
    onChange({ ...tournament, venues: clean.length > 0 ? clean : null, courtsCount: clean.length > 0 ? clean.reduce((s, v) => s + v.courts, 0) : tournament.courtsCount });
  };
  const update = (id, patch) => save(venues.map((v) => (v.id === id ? { ...v, ...patch } : v)));
  // Una sede arranca antes (o termina después) que el horario del torneo ese día: se amplía el día y
  // las sedes que seguían el horario del torneo pasan a tener sus días con el horario de antes, así
  // no se corren solas
  const widenDay = (date, from, to) => {
    const day = dates.find((d) => d.date === date);
    if (!day) return;
    const nextDates = dates.map((d) => (d.date === date ? { ...d, from: from < d.from ? from : d.from, to: to > d.to ? to : d.to } : d));
    const nextVenues = venues.map((v) => (v.days ? v : { ...v, days: dates.map((d) => ({ date: d.date, from: d.from, to: d.to })) }));
    onChange({ ...tournament, playDates: nextDates, venues: nextVenues });
  };
  const start = () => save([{ id: uid(), name: "Sede 1", courts: tournament.courtsCount || 1 }, { id: uid(), name: "Sede 2", courts: 2 }]);
  const scheduled = (tournament.categories || []).some((c) => (c.groups || []).some((g) => g.matches.some((m) => m.schedule)) || (c.bracket || []).some((r) => r.some((m) => m.schedule)));

  if (venues.length === 0) {
    return (
      <button type="button" onClick={start} className="text-xs text-teal-400 underline mb-4" style={F.body}>
        ¿Se juega en uno o más complejos? Cargar sedes
      </button>
    );
  }
  return (
    <div className="mb-4">
      <label className="block text-xs text-teal-400 mb-1" style={F.body}>Sedes y sus canchas</label>
      <div className="space-y-2">
        {venues.map((v) => (
          <div key={v.id} className="flex items-center gap-2 flex-wrap text-sm" style={F.body}>
            <select value={v.complexId || ""} onChange={(e) => chooseComplex(v, e.target.value)} className="flex-1 min-w-[9rem] px-2 py-1.5 rounded border text-sm" style={input}>
              <option value="">Otra sede…</option>
              {sortedComplexes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
            {!v.complexId && <input value={v.name} onChange={(e) => update(v.id, { name: e.target.value })} placeholder="Nombre de la sede" className="flex-1 min-w-[9rem] px-2 py-1.5 rounded border text-sm" style={input} />}
            <label className="text-xs text-teal-400 flex items-center gap-1">
              Canchas
              <input type="number" min="1" inputMode="numeric" value={v.courts} onChange={(e) => update(v.id, { courts: e.target.value })} className="w-16 px-2 py-1.5 rounded border text-sm" style={input} />
            </label>
            <button type="button" onClick={() => save(venues.filter((x) => x.id !== v.id))} className="text-red-400 text-xs">Quitar ✕</button>
            {dates.length > 0 && <VenueDaysField venue={v} dates={dates} onChange={(days) => update(v.id, { days })} onWidenDay={widenDay} />}
          </div>
        ))}
      </div>
      <button type="button" onClick={() => save([...venues, { id: uid(), name: `Sede ${venues.length + 1}`, courts: 1 }])} className="mt-2 text-xs font-semibold text-lime-400">+ Agregar sede</button>
      {scheduled && <p className="text-[11px] text-amber-400 mt-1" style={F.body}>Si cambiás sedes o canchas con horarios ya armados, tocá "Rearmar horarios" para reubicar los partidos.</p>}
    </div>
  );
}

/* Qué días y en qué horario se usa una sede (venue.days, ver courtIsOpen). "Todos los días" = sin
   days: la sede sigue los días y horarios del torneo, también los que se agreguen después. */
function VenueDaysField({ venue, dates, onChange, onWidenDay }) {
  const input = { backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" };
  const all = !venue.days;
  const dayOf = (date) => (venue.days || []).find((d) => d.date === date);
  const setDay = (date, patch) => {
    const base = dates.find((d) => d.date === date);
    const current = dayOf(date) || { date, from: base.from, to: base.to };
    const next = (venue.days || []).filter((d) => d.date !== date);
    if (patch) next.push({ ...current, ...patch });
    onChange(next.sort((a, b) => (a.date < b.date ? -1 : 1)));
  };
  return (
    <div className="w-full pl-1 pb-2 text-xs" style={F.body}>
      <label className="inline-flex items-center gap-1.5 text-teal-400 cursor-pointer">
        <input
          type="checkbox" checked={all}
          onChange={(e) => onChange(e.target.checked ? null : dates.map((d) => ({ date: d.date, from: d.from, to: d.to })))}
        />
        Todos los días, en el horario del torneo
      </label>
      {!all && (
        <div className="mt-1.5 space-y-1.5">
          {dates.map((d) => {
            const own = dayOf(d.date);
            return (
              <div key={d.date} className="flex items-center gap-2 flex-wrap">
                <label className="inline-flex items-center gap-1.5 w-24 cursor-pointer text-teal-200">
                  <input type="checkbox" checked={!!own} onChange={(e) => setDay(d.date, e.target.checked ? {} : null)} />
                  {formatDateShort(d.date)}
                </label>
                {own ? (
                  <>
                    <input type="time" lang="es-AR" value={own.from} onChange={(e) => setDay(d.date, { from: e.target.value })} className="px-1.5 py-1 rounded border text-xs" style={input} />
                    <span className="text-teal-500">a</span>
                    <input type="time" lang="es-AR" value={own.to} onChange={(e) => setDay(d.date, { to: e.target.value })} className="px-1.5 py-1 rounded border text-xs" style={input} />
                    {own.from && own.to && own.to <= own.from && <span className="text-amber-400">Tiene que terminar después de que empieza (hasta medianoche: 23:59).</span>}
                    {(own.from < d.from || own.to > d.to) && own.from < own.to && (
                      <span className="text-amber-400">
                        El torneo ese día va de {d.from} a {d.to}.{" "}
                        <button type="button" onClick={() => onWidenDay(d.date, own.from, own.to)} className="underline font-semibold text-lime-400">
                          Ampliar el {formatDateShort(d.date)} a {own.from < d.from ? own.from : d.from}–{own.to > d.to ? own.to : d.to}
                        </button>
                        <span className="block text-teal-600">Las demás sedes quedan en su horario de ahora.</span>
                      </span>
                    )}
                  </>
                ) : (
                  <span className="text-teal-600">No se usa</span>
                )}
              </div>
            );
          })}
          {venue.days.length === 0 && <p className="text-amber-400">Así esta sede no se usa ningún día.</p>}
        </div>
      )}
    </div>
  );
}

/* Pestaña Llaves, arriba de todo: el estado de la llave de cada categoría (se toca para verla) y
   "Publicar todas" para las que siguen en borrador */
function BracketsOverview({ tournament, activeId, onSelect, onUpdateTournament }) {
  const format = tournament.matchFormat;
  const cats = tournament.categories.filter((c) => !isSuper8(c));
  const status = (c) => {
    if (!c.bracket) return { text: "Sin armar", color: "#64748b" };
    const pending = c.groups.filter((g) => !(g.matches.length > 0 && g.matches.every((m) => matchIsPlayed(m, format)))).length;
    const wait = c.bracketIsSkeleton ? ` · faltan ${pending} grupo${pending === 1 ? "" : "s"}` : "";
    if (!c.bracketPublished) return { text: `Borrador${wait}`, color: "#a78bfa" };
    const { rounds, winners, byes } = walkBracket(c.bracket, format);
    const champion = winners[rounds.length - 1]?.[0];
    if (champion) return { text: `🏆 ${categoryEntitiesById(c)[champion]?.name || "Campeón"}`, color: "#9fe022" };
    const played = rounds.flatMap((r, ri) => r.filter((m, mi) => !isByeMatch(byes, ri, mi)));
    const done = played.filter((m) => matchIsPlayed(m, format)).length;
    return { text: done > 0 ? `En juego · ${done}/${played.length} partidos` : `Publicada${wait}`, color: done > 0 ? "#fb923c" : "#38bdf8" };
  };
  const drafts = cats.filter((c) => c.bracket && !c.bracketPublished);
  const publishAll = () => onUpdateTournament({ ...tournament, categories: tournament.categories.map((c) => (drafts.includes(c) ? { ...c, bracketPublished: true } : c)) });
  return (
    <div className="mb-5" style={F.body}>
      <div className="flex items-center justify-between gap-3 flex-wrap mb-2">
        <p className="text-sm uppercase tracking-wide text-teal-400">Llaves del torneo</p>
        {drafts.length > 0 && (
          <button type="button" onClick={publishAll} className="px-3 py-1.5 rounded font-semibold text-xs" style={{ backgroundColor: "#a78bfa", color: "#14181f" }}>
            Publicar todas ({drafts.length})
          </button>
        )}
      </div>
      <div className="grid gap-2" style={{ gridTemplateColumns: "repeat(auto-fill, minmax(11rem, 1fr))" }}>
        {cats.map((c) => {
          const ci = tournament.categories.indexOf(c);
          const color = GROUP_COLORS[ci % GROUP_COLORS.length];
          const st = status(c);
          const on = c.id === activeId;
          return (
            <button key={c.id} type="button" onClick={() => onSelect(c.id)} className="text-left rounded-lg px-3 py-2 border transition"
              style={{ borderColor: on ? color : color + "40", backgroundColor: on ? color + "1f" : "transparent" }}>
              <span className="block text-sm font-semibold" style={{ color }}>{c.name}</span>
              <span className="block text-[11px] truncate" style={{ color: st.color }}>{st.text}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

/* Pestaña Llaves, arriba de cada categoría: "La llave arranca", hora y sede de la final y publicar.
   Si la llave todavía no tiene resultados, al cambiar el arranque o la final sus horarios se
   vuelven a armar solos; si ya tiene, se guarda el cambio y se avisa que hay que rearmar. */
function BracketSettingsBar({ tournament, category, onUpdateTournament }) {
  const dates = tournament.playDates || [];
  const input = { backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" };
  const venues = tournament.venues || [];
  const groupDays = dates.filter((d) => !isBracketDay(d));
  const bracketDays = dates.filter(isBracketDay).sort((a, b) => (a.date < b.date ? -1 : 1));
  const lastBracketDay = bracketDays[bracketDays.length - 1];
  const finalTimes = lastBracketDay ? dayTimeSlots(lastBracketDay, tournament.matchDurationMinutes || DEFAULT_MATCH_DURATION) : [];
  const hasResults = (category.bracket || []).flat().some(matchHasScore);

  const change = (patch) => {
    let c = { ...category, ...patch };
    let t = { ...tournament, categories: tournament.categories.map((x) => (x.id === c.id ? c : x)) };
    if (c.bracket && !hasResults && tournamentUsesSchedule(tournament)) {
      // Sin los horarios viejos de esta llave (si no, se toman como ocupados) y armados de nuevo
      c = { ...c, bracket: c.bracket.map((round) => round.map((m) => ({ ...m, schedule: null }))) };
      t = { ...t, categories: t.categories.map((x) => (x.id === c.id ? c : x)) };
      c = autoScheduleBracket(t, c);
      t = { ...t, categories: t.categories.map((x) => (x.id === c.id ? c : x)) };
    }
    onUpdateTournament(t);
  };
  const setStart = (p) => { const s = { ...(category.bracketStart || {}), ...p }; change({ bracketStart: s.date ? s : null }); };
  const setFinal = (p) => { const f = { ...(category.bracketFinal || {}), ...p }; change({ bracketFinal: f.time || f.venueId ? f : null }); };
  const published = !!category.bracketPublished;

  return (
    <div className="rounded-lg border border-teal-800 p-3 mb-4 text-sm space-y-3" style={F.body}>
      <div className="flex items-center justify-between gap-3 flex-wrap">
        <span>
          Llave de <strong>{category.name}</strong>:{" "}
          {!category.bracket ? <span className="text-teal-500">todavía sin armar</span>
            : published ? <span className="text-lime-400 font-semibold">publicada</span>
            : <span className="font-semibold" style={{ color: "#a78bfa" }}>borrador (los jugadores todavía no la ven)</span>}
        </span>
        {category.bracket && (published ? (
          <button type="button" onClick={() => onUpdateTournament(publishBracketSchedule(tournament, category.id, false))} className="text-xs text-teal-400 hover:text-lime-400">Volver a borrador</button>
        ) : (
          <button type="button" onClick={() => onUpdateTournament(publishBracketSchedule(tournament, category.id))} className="px-3 py-1.5 rounded font-semibold text-xs" style={{ backgroundColor: "#a78bfa", color: "#14181f" }}>Publicar llave</button>
        ))}
      </div>
      {tournamentUsesSchedule(tournament) && dates.length > 0 && (
        <div className="flex items-center gap-x-5 gap-y-2 flex-wrap">
          {groupDays.length > 0 && (
            <span className="flex items-center gap-2" title="La primera ronda de esta llave se puede jugar ese día desde esa hora, aunque sea un día de grupos; desde la segunda ronda, todas las llaves van a los días de llaves">
              <span className="text-xs text-teal-400">La llave arranca</span>
              <select value={category.bracketStart?.date || ""} onChange={(e) => setStart({ date: e.target.value || null })} aria-label="Día en que arranca la llave" className="px-2 py-1.5 rounded border text-sm" style={input}>
                <option value="">Con las demás</option>
                {groupDays.map((d) => <option key={d.date} value={d.date}>{formatDateShort(d.date)}</option>)}
              </select>
              <input type="time" lang="es-AR" value={category.bracketStart?.time || ""} disabled={!category.bracketStart?.date} onChange={(e) => setStart({ time: e.target.value || null })} aria-label="Hora en que arranca la llave" className="px-2 py-1.5 rounded border text-sm disabled:opacity-40" style={input} />
            </span>
          )}
          {lastBracketDay && (
            <span className="flex items-center gap-2" title={`La final va el ${formatDateShort(lastBracketDay.date)}; las semis, antes y en la misma sede. En automática, las finales se reparten en las últimas 3 horas del día.`}>
              <span className="text-xs text-teal-400">Final ({formatDateShort(lastBracketDay.date)})</span>
              <select value={category.bracketFinal?.time || ""} onChange={(e) => setFinal({ time: e.target.value || null })} aria-label="Hora de la final" className="px-2 py-1.5 rounded border text-sm" style={input}>
                <option value="">Hora automática</option>
                {finalTimes.map((t) => <option key={t} value={t}>{t}</option>)}
              </select>
              {venues.length > 0 && (
                <select value={category.bracketFinal?.venueId || ""} onChange={(e) => setFinal({ venueId: e.target.value || null })} aria-label="Sede de la final" className="px-2 py-1.5 rounded border text-sm" style={input}>
                  <option value="">Sede automática</option>
                  {venues.map((v) => <option key={v.id} value={v.id}>{v.name}</option>)}
                </select>
              )}
            </span>
          )}
        </div>
      )}
      {hasResults && <p className="text-[11px] text-amber-400">La llave ya tiene resultados: si cambiás el arranque o la final, tocá "Rearmar horarios" en Horarios para reubicar lo que falta jugar.</p>}
    </div>
  );
}

/* Clásico: día y hora de inicio de cada categoría. Se ven en la inscripción y en la página del
   torneo, y "Generar horarios" no le asigna partidos a una categoría antes de ese momento. */
function CategoryStartsEditor({ tournament, onChange }) {
  const dates = tournament.playDates || [];
  const input = { backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" };
  const setStart = (categoryId, patch) => {
    onChange({
      ...tournament,
      categories: tournament.categories.map((c) => {
        if (c.id !== categoryId) return c;
        const start = { ...(c.start || {}), ...patch };
        return { ...c, start: start.date ? start : null };
      }),
    });
  };
  return (
    <div className="border-t border-teal-800 pt-3 mt-4">
      <label className="block text-xs text-teal-400 mb-1" style={F.body}>Inicio de cada categoría (opcional)</label>
      <p className="text-[11px] text-teal-600 mb-2" style={F.body}>
        Se muestra en la inscripción y en la página del torneo. Al generar horarios, la categoría no juega antes de ese día y hora.
        {" "}Cuándo arranca la llave y la hora y sede de cada final se eligen en la pestaña Llaves.
      </p>
      <div className="space-y-3">
        {tournament.categories.map((c) => (
          <div key={c.id} className="flex items-center gap-x-4 gap-y-2 flex-wrap text-sm" style={F.body}>
            <span className="flex-1 min-w-[7rem] text-teal-200">{c.name}</span>
            <span className="flex items-center gap-2">
              <select value={c.start?.date || ""} onChange={(e) => setStart(c.id, { date: e.target.value || null })} aria-label={`Inicio de ${c.name}`} className="px-2 py-1.5 rounded border text-sm" style={input}>
                <option value="">Sin día fijo</option>
                {dates.map((d) => <option key={d.date} value={d.date}>{formatDateShort(d.date)}</option>)}
              </select>
              <input type="time" lang="es-AR" value={c.start?.time || ""} disabled={!c.start?.date} onChange={(e) => setStart(c.id, { time: e.target.value || null })} className="px-2 py-1.5 rounded border text-sm disabled:opacity-40" style={input} />
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

/* Disponibilidad de una pareja: qué fechas del torneo puede jugar y en qué rango horario cada una */
function PairAvailabilityEditor({ pair, playDates, onChange }) {
  const [open, setOpen] = useState(false);
  const availByDate = Object.fromEntries((pair.availability || []).map((a) => [a.date, a]));

  const toggleDate = (d) => {
    const current = pair.availability || [];
    if (availByDate[d.date]) {
      onChange(current.filter((a) => a.date !== d.date));
    } else {
      onChange([...current, { date: d.date, from: d.from, to: d.to }]);
    }
  };
  const updateRange = (date, side, value) => {
    onChange((pair.availability || []).map((a) => (a.date === date ? { ...a, [side]: value } : a)));
  };

  if (playDates.length === 0) {
    return <p className="text-xs opacity-50 mt-1" style={F.body}>Cargá fechas del torneo (en Configuración) para definir disponibilidad.</p>;
  }

  return (
    <div className="mt-2">
      <button type="button" onClick={() => setOpen((v) => !v)} className="text-xs text-teal-400 hover:text-lime-400" style={F.body}>
        {open ? "Ocultar disponibilidad" : `Disponibilidad (${(pair.availability || []).length}/${playDates.length} días)`}
      </button>
      {open && (
        <div className="mt-2 space-y-2">
          <p className="text-[11px] text-teal-600" style={F.body}>
            Esta disponibilidad solo se usa para agendar los partidos de grupos. La cancha la asigna el sistema; solo elegís día y horario.
            Si no marcás ningún día, se toma como disponible todos los días del torneo.
          </p>
          {playDates.map((d) => {
            const a = availByDate[d.date];
            return (
              <div key={d.date} className="flex items-center gap-2 flex-wrap text-sm" style={F.body}>
                <label className="flex items-center gap-1 w-24">
                  <input type="checkbox" checked={!!a} onChange={() => toggleDate(d)} />
                  {formatDateShort(d.date)}
                </label>
                {a && (
                  <>
                    <input type="time" lang="es-AR" value={a.from} onChange={(e) => updateRange(d.date, "from", e.target.value)} className="px-2 py-1 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }} />
                    <span className="text-xs text-teal-500">a</span>
                    <input type="time" lang="es-AR" value={a.to} onChange={(e) => updateRange(d.date, "to", e.target.value)} className="px-2 py-1 rounded border text-sm" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }} />
                  </>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* Transmisiones en vivo: un link por cancha y por día (el de Beelup cambia en cada transmisión).
   tournament.streams = { "2026-10-17": { "1": "https://...", "2": "https://..." } } */
const streamOf = (t, date, court) => t?.streams?.[date]?.[court] || null;
const linkValido = (url) => typeof url === "string" && /^https:\/\/\S+$/.test(url) && url.length <= 500;

/* Editor de los links del día, en Horarios (se abre y se cierra para no tapar la planilla) */
function StreamLinksEditor({ tournament, date, courts, onSave }) {
  const delDia = tournament.streams?.[date] || {};
  const cargados = courts.filter((c) => delDia[c]).length;
  const [abierto, setAbierto] = useState(false);
  const [textos, setTextos] = useState({});
  const [error, setError] = useState("");
  useEffect(() => { setTextos({}); setError(""); }, [date]);
  const valor = (c) => textos[c] ?? delDia[c] ?? "";
  const guardar = (c) => {
    const url = valor(c).trim();
    if ((delDia[c] || "") === url) return;
    if (url && !linkValido(url)) { setError(`${courtName(tournament, c)}: pegá el link completo (empieza con https://).`); return; }
    setError("");
    const dia = { ...delDia };
    if (url) dia[c] = url; else delete dia[c];
    const streams = { ...(tournament.streams || {}), [date]: dia };
    if (Object.keys(dia).length === 0) delete streams[date];
    onSave(streams);
  };
  return (
    <div className="mb-3 rounded-lg border border-teal-800" style={{ ...F.body, backgroundColor: "rgba(8,18,24,0.5)" }}>
      <button type="button" onClick={() => setAbierto(!abierto)} aria-expanded={abierto} className="w-full flex items-center justify-between gap-2 px-3 py-2 text-sm text-left">
        <span><span style={{ color: "#f87171" }}>●</span> Transmisiones en vivo del {formatDateShort(date)}</span>
        <span className="text-xs text-teal-400">{cargados > 0 ? `${cargados} de ${courts.length} canchas` : "sin links"} {abierto ? "▲" : "▼"}</span>
      </button>
      {abierto && (
        <div className="px-3 pb-3 space-y-2">
          <p className="text-[11px] text-teal-500">Pegá el link de la transmisión de cada cancha (Beelup u otro). Se ve en la página pública del torneo, arriba de los horarios de ese día. Para sacarlo, borralo.</p>
          {courts.map((c) => (
            <label key={c} className="grid grid-cols-[6.5rem_minmax(0,1fr)] items-center gap-2 text-xs">
              <span className="text-teal-300 truncate">{courtName(tournament, c)}</span>
              <input type="url" inputMode="url" value={valor(c)} onChange={(e) => setTextos({ ...textos, [c]: e.target.value })} onBlur={() => guardar(c)} placeholder="https://beelup.com/..." className="w-full min-w-0 px-2 py-1.5 rounded border text-xs" style={{ backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" }} />
            </label>
          ))}
          {error && <p role="alert" className="text-xs text-red-300">{error}</p>}
        </div>
      )}
    </div>
  );
}

/* Botones "▶ Cancha 1" de las transmisiones de un día (vista pública) */
function StreamLinks({ tournament, date }) {
  const delDia = tournament.streams?.[date] || {};
  const canchas = Object.keys(delDia).filter((c) => linkValido(delDia[c])).sort((a, b) => Number(a) - Number(b));
  if (canchas.length === 0) return null;
  // "En vivo" solo el día de los partidos; otro día el link queda (puede ser la grabación)
  const enVivo = date === todayISO() && tournamentStatusOf(tournament) !== STATUS.FINALIZADO;
  return (
    <div className="flex flex-wrap items-center gap-2 mb-2" style={F.body}>
      <span className="text-xs font-bold uppercase tracking-wide" style={{ color: "#f87171" }}>{enVivo ? "● En vivo" : "Transmisiones"}</span>
      {canchas.map((c) => (
        <a key={c} href={delDia[c]} target="_blank" rel="noopener noreferrer" className="px-3 py-1 rounded-full text-xs font-semibold border" style={{ borderColor: "#f8717199", color: "#fecaca", backgroundColor: "#f871711a" }}>
          ▶ {courtName(tournament, Number(c))}
        </a>
      ))}
    </div>
  );
}

/* Tarjeta chica de un partido dentro de una celda de la planilla (canchas x horarios). Arrastrable
   para moverla a otra celda; el color/borde cambia según esté finalizada, en borrador o en choque. */
function GridMatchCard({ m, format, pairsById, conflict, offAvailability = [], onDragStart, onClear, onResult, onMove, onLive }) {
  const status = m.placeholder ? "pendiente" : matchDisplayStatus(m, format);
  const finished = status === "finalizado";
  const live = status === "en_curso";
  const border = conflict ? "#f87171" : m.draft ? "#a78bfa" : finished ? "#9fe022" : live ? "#fb923c" : "#38bdf8";
  const bg = conflict ? "#f8717122" : m.draft ? "#a78bfa1a" : finished ? "#9fe0221a" : live ? "#fb923c22" : "#38bdf81a";
  return (
    <div
      draggable={!!onDragStart}
      onDragStart={onDragStart}
      className="rounded-md px-2 py-1.5 mb-1 text-[11px] leading-tight relative"
      style={{ ...F.body, border: `1.5px ${m.draft ? "dashed" : "solid"} ${border}`, backgroundColor: bg, cursor: onDragStart ? "grab" : "default" }}
      title={conflict ? "Choque: hay más de un partido en este horario y cancha" : undefined}
    >
      <button
        type="button"
        onClick={onClear}
        className="absolute top-0.5 right-1 text-[10px] opacity-50 hover:opacity-100"
        title="Quitar horario"
      >✕</button>
      <div className="flex items-center gap-1 flex-wrap pr-3">
        <span className="text-teal-500 truncate">{m.number ? `#${m.number} · ` : ""}{m.categoryName}{m.label ? ` · ${m.label}` : ""}</span>
        {conflict && <span className="text-[9px] font-bold" style={{ color: "#f87171" }}>⚠ CHOQUE</span>}
        {m.draft && <span className="text-[9px] font-bold" style={{ color: "#a78bfa" }}>BORRADOR</span>}
        {finished && <span className="text-[9px] font-bold" style={{ color: "#9fe022" }}>✓</span>}
        {live && <span className="text-[9px] font-bold" style={{ color: "#fb923c" }}>● EN CURSO</span>}
      </div>
      {m.placeholder ? (
        <p className="italic opacity-70 truncate">{m.placeholder}</p>
      ) : (
        <>
          <p className="truncate"><PairName id={m.pairA} pairsById={pairsById} /></p>
          <p className="truncate opacity-60">vs <PairName id={m.pairB} pairsById={pairsById} /></p>
          {offAvailability.length > 0 && (
            <p className="text-[10px] font-semibold" style={{ color: "#fbbf24" }} title="Este horario está fuera de la disponibilidad que eligió la pareja al inscribirse">
              ⚠ Fuera de la disponibilidad de {offAvailability.map((pid) => pairsById[pid]?.name || "una pareja").join(" y ")}
            </p>
          )}
          {onResult && (
            <button type="button" onClick={onResult} className="mt-0.5 text-[10px] underline text-teal-300 hover:text-lime-400">
              {finished ? <span className="font-mono"><MatchResultLabel format={format} match={m} winnerIsA={matchWinnerId(m, format) === m.pairA} /> ✎</span> : "+ Resultado"}
            </button>
          )}
        </>
      )}
      {onMove && !finished && (
        <button type="button" onClick={onMove} className="mt-0.5 ml-2 text-[10px] underline text-teal-300 hover:text-lime-400">⇄ Mover</button>
      )}
      {onLive && !finished && !m.placeholder && (
        <button type="button" onClick={() => onLive(live ? null : "en_curso")} className="mt-0.5 ml-2 text-[10px] underline" style={{ color: live ? "#94a3b8" : "#fb923c" }}>{live ? "Quitar en curso" : "▶ En curso"}</button>
      )}
    </div>
  );
}

/* Mover un partido sin arrastrar (en el celular arrastrar no funciona): se elige día, horario y
   cancha. Si ese lugar ya tiene un partido, los dos se intercambian de lugar. */
function MoveMatchModal({ m, tournament, matches, pairsById, update, onClose }) {
  const playDates = tournament.playDates || [];
  const duration = tournament.matchDurationMinutes || DEFAULT_MATCH_DURATION;
  const [date, setDate] = useState(m.schedule?.date || playDates[0]?.date || "");
  const dateInfo = playDates.find((d) => d.date === date);
  const times = dateInfo ? dayTimeSlots(dateInfo, duration) : [];
  const [time, setTime] = useState(m.schedule?.time && times.includes(m.schedule.time) ? m.schedule.time : times[0] || "");
  const [court, setCourt] = useState(m.schedule?.court || 1);
  const occupantAt = (c) => matches.find((x) => x.key !== m.key && x.schedule && x.schedule.date === date && x.schedule.time === time && x.schedule.court === c);
  const occupant = occupantAt(court);
  // Cancha cuya sede no se usa en ese día y horario: se ve, pero no se puede elegir
  const isClosed = (c) => !!time && !courtIsOpen(tournament, c, date, timeToMinutes(time), duration);
  const same = m.schedule && m.schedule.date === date && m.schedule.time === time && m.schedule.court === court;
  const describe = (x) => (x.placeholder ? x.placeholder : `${pairsById[x.pairA]?.name || "—"} vs ${pairsById[x.pairB]?.name || "—"}`);
  const input = { backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" };

  const move = () => {
    if (!date || !time || same || isClosed(court)) return;
    const target = { date, time, court };
    let next = tournament;
    if (occupant) next = withMatchSchedule(next, occupant.categoryId, occupant.location, occupant.matchId, m.schedule || null);
    next = withMatchSchedule(next, m.categoryId, m.location, m.matchId, target);
    update(next);
    onClose();
  };
  const unschedule = () => { update(withMatchSchedule(tournament, m.categoryId, m.location, m.matchId, null)); onClose(); };

  return (
    <Modal title="Mover partido" onClose={onClose}>
      <p className="text-xs text-teal-500 mb-1" style={F.body}>{m.number ? `#${m.number} · ` : ""}{m.categoryName}{m.label ? ` · ${m.label}` : ""}</p>
      <p className="text-sm mb-4" style={F.body}>{describe(m)}</p>
      {playDates.length === 0 ? (
        <p className="text-sm text-amber-400" style={F.body}>Primero cargá el día y horario del torneo en Configuración.</p>
      ) : (
        <div className="space-y-3">
          {playDates.length > 1 && (
            <div>
              <label className="block text-xs text-teal-400 mb-1" style={F.body}>Día</label>
              <select value={date} onChange={(e) => { setDate(e.target.value); const d = playDates.find((x) => x.date === e.target.value); setTime(d ? dayTimeSlots(d, duration)[0] || "" : ""); }} className="w-full px-3 py-2.5 rounded border text-base" style={input}>
                {playDates.map((d) => <option key={d.date} value={d.date}>{formatDateShort(d.date)}</option>)}
              </select>
            </div>
          )}
          <div>
            <label className="block text-xs text-teal-400 mb-1" style={F.body}>Horario</label>
            <select value={time} onChange={(e) => setTime(e.target.value)} className="w-full px-3 py-2.5 rounded border text-base" style={input}>
              {times.map((t) => <option key={t} value={t}>{t}hs</option>)}
            </select>
          </div>
          <div>
            <label className="block text-xs text-teal-400 mb-1" style={F.body}>Cancha</label>
            <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
              {courtsOfDay(tournament, date).map((c) => (
                <ChoiceCard key={c} compact selected={court === c} onClick={() => setCourt(c)} title={courtName(tournament, c)} description={isClosed(c) ? "Sede cerrada a esa hora" : occupantAt(c) ? "Ocupada" : "Libre"} />
              ))}
            </div>
          </div>
          {isClosed(court) && (
            <p className="text-xs text-amber-400" style={F.body}>{(tournament.venues || [])[courtVenueIndex(tournament, court)]?.name || "Esa sede"} no se usa ese día a esa hora: elegí otra cancha u otro horario.</p>
          )}
          {occupant && !same && !isClosed(court) && (
            <p className="text-xs text-amber-400" style={F.body}>
              Ahí está {describe(occupant)}: {m.schedule ? `se intercambian de lugar (ese pasa a las ${m.schedule.time}hs, ${courtName(tournament, m.schedule.court)}).` : "queda sin horario."}
            </p>
          )}
          <div className="flex gap-2 flex-wrap pt-1">
            <button type="button" disabled={!time || same || isClosed(court)} onClick={move} className="flex-1 px-4 py-2.5 rounded font-semibold text-sm disabled:opacity-40" style={{ backgroundColor: "#9fe022", color: "#14181f", ...F.body }}>
              {occupant && !same ? "Intercambiar" : "Mover acá"}
            </button>
            {m.schedule && (
              <button type="button" onClick={unschedule} className="px-4 py-2.5 rounded text-sm border border-red-400 text-red-400" style={F.body}>Quitar horario</button>
            )}
          </div>
        </div>
      )}
    </Modal>
  );
}

/* Botones de W.O. y retiro (RET) de un partido, con su "Deshacer". El RET se carga después del
   marcador hasta donde se jugó: el resto se completa solo a favor del rival y la pareja que se
   retira queda eliminada. */
function MatchOutcomeButtons({ m, nameA, nameB, onWalkover, onRetired, className = "" }) {
  return (
    <div className={`flex gap-x-3 gap-y-1 flex-wrap ${className}`} style={F.body}>
      {m.walkover ? (
        <button type="button" onClick={() => onWalkover(null)} className="text-teal-400 underline">Deshacer WO</button>
      ) : m.retired ? (
        <button type="button" onClick={() => onRetired(null)} className="text-teal-400 underline">Deshacer RET</button>
      ) : (
        <>
          <button type="button" onClick={() => onWalkover(m.pairA)} className="text-amber-400 underline">WO {nameA}</button>
          <button type="button" onClick={() => onWalkover(m.pairB)} className="text-amber-400 underline">WO {nameB}</button>
          <button type="button" onClick={() => onRetired(m.pairA)} className="text-red-400 underline" title="Retiro por lesión: cargá primero el marcador hasta donde se jugó">RET {nameA}</button>
          <button type="button" onClick={() => onRetired(m.pairB)} className="text-red-400 underline" title="Retiro por lesión: cargá primero el marcador hasta donde se jugó">RET {nameB}</button>
        </>
      )}
    </div>
  );
}

/* Ventanita para cargar el resultado de un partido desde la grilla de horarios */
/* Otro partido sin terminar "en curso" en la misma cancha: antes de poner este, se pregunta dónde se
   juega (el organizador pudo cambiarlo de cancha o adelantarlo). Devuelve ese otro partido, o null. */
function liveConflict(matches, m, format) {
  if (!m?.schedule) return null;
  return matches.find((x) => x.key !== m.key && x.liveStatus === "en_curso" && !x.placeholder && !matchIsPlayed(x, format) && x.schedule && x.schedule.court === m.schedule.court) || null;
}

function LiveCourtModal({ m, tournament, matches, pairsById, update, onOpenResult, onClose }) {
  const format = tournament.matchFormat;
  const orig = m.schedule.court;
  const courts = courtsOfDay(tournament, m.schedule.date, matches.filter((x) => x.schedule));
  const liveAt = (c) => matches.find((x) => x.key !== m.key && x.liveStatus === "en_curso" && !x.placeholder && !matchIsPlayed(x, format) && x.schedule && x.schedule.court === c);
  const current = liveAt(orig);
  const numero = (x) => (x.number ? `#${x.number}` : "anterior");
  const describe = (x) => `${x.number ? `#${x.number} · ` : ""}${x.placeholder || `${pairsById[x.pairA]?.name || "—"} vs ${pairsById[x.pairB]?.name || "—"}`}`;
  // Al pasarlo a otra cancha, si ahí había otro partido en ese mismo horario, se intercambian de cancha
  const occupantAt = (c) => matches.find((x) => x.key !== m.key && x.schedule && x.schedule.date === m.schedule.date && x.schedule.time === m.schedule.time && x.schedule.court === c);
  const enOtra = (c) => {
    let next = tournament;
    const occ = occupantAt(c);
    if (occ) next = withMatchSchedule(next, occ.categoryId, occ.location, occ.matchId, { ...occ.schedule, court: orig });
    next = withMatchSchedule(next, m.categoryId, m.location, m.matchId, { ...m.schedule, court: c });
    next = withMatchLiveStatus(next, m.categoryId, m.location, m.matchId, "en_curso");
    update(next);
    onClose();
  };
  const reemplazar = () => {
    let next = withMatchLiveStatus(tournament, current.categoryId, current.location, current.matchId, null);
    next = withMatchLiveStatus(next, m.categoryId, m.location, m.matchId, "en_curso");
    update(next);
    onClose();
  };
  const otras = courts.filter((c) => c !== orig);
  return (
    <Modal title="¿En qué cancha se juega?" onClose={onClose}>
      <p className="text-xs text-teal-500 mb-1" style={F.body}>{m.categoryName}{m.label ? ` · ${m.label}` : ""}</p>
      <p className="text-sm mb-3" style={F.body}>{describe(m)}</p>
      {current && (
        <p className="text-sm mb-4 rounded-lg px-3 py-2" style={{ ...F.body, color: "#fdba74", border: "1px solid #fb923c66", backgroundColor: "#fb923c14" }}>
          En {courtName(tournament, orig)} todavía figura en curso el {describe(current)}.
        </p>
      )}
      {otras.length > 0 && (
        <div className="mb-4">
          <p className="text-xs uppercase tracking-wide text-teal-400 mb-2" style={F.body}>Se juega en otra cancha</p>
          <div className="grid grid-cols-2 gap-2">
            {otras.map((c) => {
              const ocupada = liveAt(c);
              const occ = occupantAt(c);
              return ocupada ? (
                <div key={c} className="rounded-lg border border-slate-700 px-3 py-2 text-xs text-slate-500" style={F.body}>
                  <span className="block font-semibold">{courtName(tournament, c)}</span>En curso: {describe(ocupada)}
                </div>
              ) : (
                <ChoiceCard key={c} compact selected={false} onClick={() => enOtra(c)} title={courtName(tournament, c)} description={occ ? `Libre ahora · el ${describe(occ)} pasa a ${courtName(tournament, orig)}` : "Libre"} />
              );
            })}
          </div>
        </div>
      )}
      {current && (
        <div className="space-y-2 mb-2">
          <p className="text-xs uppercase tracking-wide text-teal-400" style={F.body}>Se juega en {courtName(tournament, orig)}</p>
          {onOpenResult && (
            <button type="button" onClick={() => onOpenResult(current)} className="w-full px-3 py-2 rounded-lg text-sm font-semibold text-left" style={{ ...F.body, backgroundColor: BRAND.lime, color: "#14181f" }}>
              El {numero(current)} ya terminó: cargar su resultado
            </button>
          )}
          <button type="button" onClick={reemplazar} className="w-full px-3 py-2 rounded-lg text-sm border border-orange-400 text-orange-300 text-left" style={F.body}>
            Sacarle "en curso" al {numero(current)} y empezar este
          </button>
        </div>
      )}
      <button type="button" onClick={onClose} className="mt-2 text-sm text-teal-400 hover:text-lime-400" style={F.body}>Cancelar</button>
    </Modal>
  );
}

function MatchResultModal({ m, pairsById, format, onSetScore, onWalkover, onRetired, onClose }) {
  const nameA = pairsById[m.pairA]?.name || "—", nameB = pairsById[m.pairB]?.name || "—";
  return (
    <Modal title="Resultado" onClose={onClose}>
      <p className="text-xs text-teal-500 mb-2" style={F.body}>{m.number ? `#${m.number} · ` : ""}{m.categoryName}{m.label ? ` · ${m.label}` : ""}</p>
      <p className="text-sm mb-4" style={F.body}>{nameA} <span className="text-teal-500">vs</span> {nameB}</p>
      {m.walkover ? (
        <p className="text-sm text-amber-400 mb-3" style={F.body}>WO: no se presentó {m.walkover === m.pairA ? nameA : nameB}.</p>
      ) : (
        <>
          {m.retired && <p className="text-sm text-red-400 mb-2" style={F.body}>RET: se retiró {m.retired === m.pairA ? nameA : nameB}. El resto del partido se completa a favor del rival.</p>}
          <div className="flex justify-start mb-3"><MatchSetsEditor sets={m.sets} format={format} onSetScore={onSetScore} partial={!!m.retired} /></div>
        </>
      )}
      <MatchOutcomeButtons m={m} nameA={nameA} nameB={nameB} onWalkover={onWalkover} onRetired={onRetired} className="text-xs mb-5" />
      <button type="button" onClick={onClose} className="px-4 py-2 rounded font-semibold text-sm" style={{ backgroundColor: "#9fe022", color: "#14181f", ...F.body }}>Listo</button>
    </Modal>
  );
}

/* Resultado, WO y "en curso" de un partido de la grilla, y ventanas de resultado y mover: lo que
   comparten la grilla de horarios y la pantalla "En cancha". */
function useMatchActions(tournament, update) {
  const pairsById = useMemo(() => {
    const map = {};
    tournament.categories.forEach((c) => Object.assign(map, categoryEntitiesById(c)));
    return map;
  }, [tournament.categories]);
  const matches = useMemo(() => collectScheduleableMatches(tournament), [tournament]);
  const [resultKey, setResultKey] = useState(null);
  const [moveKey, setMoveKey] = useState(null);
  const [liveKey, setLiveKey] = useState(null); // partido a poner "en curso" con otro en curso en su cancha
  const resultMatch = resultKey ? matches.find((m) => m.key === resultKey) : null;
  const moveMatch = moveKey ? matches.find((m) => m.key === moveKey) : null;
  const liveMatch = liveKey ? matches.find((m) => m.key === liveKey) : null;

  const change = (m, fn) => update(withMatchResult(tournament, m.categoryId, m.location, m.matchId, fn));
  const setLive = (m, liveStatus) => {
    if (liveStatus === "en_curso" && liveConflict(matches, m, tournament.matchFormat)) { setLiveKey(m.key); return; }
    update(withMatchLiveStatus(tournament, m.categoryId, m.location, m.matchId, liveStatus));
  };

  const modals = (
    <>
      {resultMatch && !resultMatch.placeholder && (
        <MatchResultModal
          m={resultMatch}
          pairsById={pairsById}
          format={tournament.matchFormat}
          onSetScore={(setIndex, side, value) => change(resultMatch, (x) => ({ ...x, sets: withSetScore(x.sets, setIndex, side, value) }))}
          onWalkover={(pairId) => change(resultMatch, (x) => ({ ...x, walkover: pairId, retired: null, sets: pairId ? [] : x.sets, liveStatus: null }))}
          onRetired={(pairId) => change(resultMatch, (x) => ({ ...x, retired: pairId, walkover: null, liveStatus: null }))}
          onClose={() => setResultKey(null)}
        />
      )}
      {moveMatch && <MoveMatchModal m={moveMatch} tournament={tournament} matches={matches} pairsById={pairsById} update={update} onClose={() => setMoveKey(null)} />}
      {liveMatch && <LiveCourtModal m={liveMatch} tournament={tournament} matches={matches} pairsById={pairsById} update={update} onOpenResult={(x) => { setLiveKey(null); setResultKey(x.key); }} onClose={() => setLiveKey(null)} />}
    </>
  );
  return { pairsById, matches, openResult: (m) => setResultKey(m.key), openMove: (m) => setMoveKey(m.key), setLive, modals };
}

/* Pantalla "En cancha", pensada para usar desde el celular durante el torneo: lo que se está
   jugando ahora, los próximos partidos en orden y los terminados, con botones grandes para
   marcar "en curso", cargar el resultado o mover el partido de horario/cancha. */
function OnCourtView({ tournament, update }) {
  const { pairsById, matches, openResult, openMove, setLive, modals } = useMatchActions(tournament, update);
  const [showAllNext, setShowAllNext] = useState(false);
  const [showDone, setShowDone] = useState(false);

  const real = matches.filter((m) => !m.draft || m.schedule);
  const done = real.filter((m) => !m.placeholder && matchIsPlayed(m, tournament.matchFormat)).filter((m) => m.schedule).sort(compareBySchedule).reverse();
  const live = real.filter((m) => !m.placeholder && !matchIsPlayed(m, tournament.matchFormat) && m.liveStatus === "en_curso")
    .sort((a, b) => (a.schedule?.court || 99) - (b.schedule?.court || 99));
  const upcoming = real.filter((m) => m.schedule && !matchIsPlayed(m, tournament.matchFormat) && m.liveStatus !== "en_curso").sort(compareBySchedule);
  const unscheduled = real.filter((m) => !m.schedule && !m.placeholder && !matchIsPlayed(m, tournament.matchFormat));
  const shownNext = showAllNext ? upcoming : upcoming.slice(0, 8);

  const card = (m, kind) => {
    const hasResult = !m.placeholder && matchIsPlayed(m, tournament.matchFormat);
    const w = hasResult ? matchWinnerId(m, tournament.matchFormat) : null;
    const name = (id) => <span className={w === id ? "text-lime-400 font-semibold" : ""}>{pairsById[id]?.name || "—"}</span>;
    const accent = kind === "live" ? "#fb923c" : kind === "done" ? "#9fe022" : "#38bdf8";
    const btn = "flex-1 min-w-[6.5rem] px-3 py-2.5 rounded-lg text-sm font-semibold";
    return (
      <div key={m.key} className="rounded-xl p-3" style={{ backgroundColor: accent + "0f", border: `1px solid ${accent}40`, borderLeft: `4px solid ${accent}`, ...F.body }}>
        <div className="flex items-center gap-2 text-xs mb-1 flex-wrap">
          {m.schedule
            ? <span className="font-bold" style={{ color: accent }}>{m.schedule.time}hs · {courtName(tournament, m.schedule.court)}</span>
            : <span className="font-bold text-amber-400">Sin horario</span>}
          <span className="text-teal-500 truncate">{m.number ? `#${m.number} · ` : ""}{m.categoryName}{m.label ? ` · ${m.label}` : ""}</span>
          {m.schedule && (tournament.playDates || []).length > 1 && <span className="text-teal-600">{formatDateShort(m.schedule.date)}</span>}
        </div>
        {m.placeholder ? (
          <p className="italic opacity-70 text-sm mb-2">{m.placeholder}</p>
        ) : (
          <p className="text-base leading-snug mb-2">{name(m.pairA)} <span className="text-xs text-teal-500">vs</span> {name(m.pairB)}</p>
        )}
        {hasResult && <p className="font-mono text-sm text-teal-300 mb-2"><MatchResultLabel format={tournament.matchFormat} match={m} winnerIsA={w === m.pairA} /></p>}
        <div className="flex gap-2 flex-wrap">
          {!m.placeholder && !hasResult && (kind === "live" ? (
            <button type="button" onClick={() => setLive(m, null)} className={`${btn} border border-orange-400 text-orange-300`}>Quitar en curso</button>
          ) : (
            <button type="button" onClick={() => setLive(m, "en_curso")} className={`${btn} border border-orange-400 text-orange-300`}>En curso</button>
          ))}
          {!m.placeholder && (
            <button type="button" onClick={() => openResult(m)} className={btn} style={{ backgroundColor: "#9fe022", color: "#14181f" }}>
              {hasResult ? "Editar resultado" : "Cargar resultado"}
            </button>
          )}
          {!hasResult && <button type="button" onClick={() => openMove(m)} className={`${btn} border border-teal-600 text-teal-300`}>Mover</button>}
        </div>
      </div>
    );
  };

  const section = (title, count, color) => (
    <h3 className="text-xs uppercase tracking-wide font-bold mb-2 mt-6 first:mt-0" style={{ color, ...F.body }}>{title} ({count})</h3>
  );

  if (real.length === 0) {
    return <p className="opacity-60 text-sm" style={F.body}>Todavía no hay partidos armados. Cargá los grupos en cada categoría.</p>;
  }

  return (
    <div>
      {modals}
      {section("Jugando ahora", live.length, "#fb923c")}
      {live.length === 0
        ? <p className="text-sm opacity-60" style={F.body}>Ningún partido marcado "en curso".</p>
        : <div className="space-y-3">{live.map((m) => card(m, "live"))}</div>}

      {section("Próximos", upcoming.length, "#38bdf8")}
      {upcoming.length === 0
        ? <p className="text-sm opacity-60" style={F.body}>No quedan partidos con horario por jugar.</p>
        : <div className="space-y-3">{shownNext.map((m) => card(m, "next"))}</div>}
      {upcoming.length > shownNext.length && (
        <button type="button" onClick={() => setShowAllNext(true)} className="mt-3 text-sm text-teal-300 underline" style={F.body}>Ver los {upcoming.length} próximos</button>
      )}

      {unscheduled.length > 0 && (
        <>
          {section("Sin horario", unscheduled.length, "#fbbf24")}
          <div className="space-y-3">{unscheduled.map((m) => card(m, "next"))}</div>
        </>
      )}

      {section("Terminados", done.length, "#9fe022")}
      {done.length > 0 && (
        showDone
          ? <div className="space-y-3">{done.map((m) => card(m, "done"))}</div>
          : <button type="button" onClick={() => setShowDone(true)} className="text-sm text-teal-300 underline" style={F.body}>Ver terminados</button>
      )}
    </div>
  );
}

/* Grilla completa de horarios (admin): planilla tipo canchas x horarios con arrastrar y soltar.
   Reemplaza la vieja lista: bloquea/reubica automáticamente los choques de cancha y marca visualmente
   los partidos finalizados, ya que no queda un orden lineal como en una lista. */
/* Grilla completa en una ventana emergente ("Abrir grilla"): todos los días, con las canchas en
   columnas y las horas en filas, para ver todo de un vistazo. Solo lectura: tocar un partido abre
   la ventanita de resultado. Pensada para 4 o 5 canchas; con más, se desliza de costado con la
   columna de horas fija. */
function ScheduleGridOverlay({ tournament, matches, pairsById, onOpenResult, onClose }) {
  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);
  const duration = tournament.matchDurationMinutes || DEFAULT_MATCH_DURATION;
  const scheduled = matches.filter((m) => m.schedule);
  const closed = closedCourtSlots(tournament);
  const categoryColor = Object.fromEntries(tournament.categories.map((c, i) => [c.id, GROUP_COLORS[i % GROUP_COLORS.length]]));
  const shortName = (id) => pairsById[id]?.name || "A definir";

  const cell = (m) => {
    const status = matchDisplayStatus(m, tournament.matchFormat);
    const color = status === "finalizado" ? "#9fe022" : status === "en_curso" ? "#fb923c" : categoryColor[m.categoryId];
    const w = matchIsPlayed(m, tournament.matchFormat) ? matchWinnerId(m, tournament.matchFormat) : null;
    return (
      <button
        key={m.key}
        type="button"
        onClick={() => !m.placeholder && onOpenResult(m)}
        className="w-full text-left rounded px-1.5 py-1 text-[10px] leading-tight"
        style={{ border: `1.5px ${m.draft ? "dashed" : "solid"} ${color}`, backgroundColor: color + "1a", ...F.body }}
      >
        <span className="block font-bold truncate" style={{ color: categoryColor[m.categoryId] }}>{m.number ? `#${m.number} · ` : ""}{m.categoryName} · {m.label}</span>
        {m.placeholder && !(m.pairA && m.pairB) ? (
          <span className="block italic text-teal-400">{m.placeholder}</span>
        ) : (
          <>
            <span className={`block truncate ${w === m.pairA ? "text-lime-400 font-semibold" : "text-slate-200"}`}>{shortName(m.pairA)}</span>
            <span className={`block truncate ${w === m.pairB ? "text-lime-400 font-semibold" : "text-slate-200"}`}>{shortName(m.pairB)}</span>
          </>
        )}
        {matchIsPlayed(m, tournament.matchFormat) && <span className="block font-mono text-teal-300 truncate"><MatchResultLabel match={m} format={tournament.matchFormat} winnerIsA={w == null ? null : w === m.pairA} /></span>}
        {status === "en_curso" && <span className="block font-bold" style={{ color: "#fb923c" }}>● EN CURSO</span>}
        {pairsOutsideAvailability(tournament, m).length > 0 && (
          <span className="block font-bold truncate" style={{ color: "#fbbf24" }} title={`Fuera de la disponibilidad de ${pairsOutsideAvailability(tournament, m).map(shortName).join(" y ")}`}>⚠ Fuera de disponibilidad</span>
        )}
      </button>
    );
  };

  return (
    <div className="fixed inset-0 z-40 flex flex-col" style={{ backgroundColor: "#0b1c24", color: "#e2e8f0" }} role="dialog" aria-modal="true" aria-label="Grilla de horarios">
      <div className="flex items-center justify-between gap-3 px-4 py-3 border-b border-teal-900">
        <h2 className="text-base sm:text-lg" style={F.display}>GRILLA · {tournament.name.toUpperCase()}</h2>
        <button type="button" onClick={onClose} className="text-teal-400 hover:text-lime-400 text-xl leading-none p-1" aria-label="Cerrar">✕</button>
      </div>
      <div className="flex-1 overflow-auto p-3 sm:p-4">
        {(tournament.playDates || []).length === 0 && <p className="opacity-60 text-sm" style={F.body}>Todavía no hay fechas cargadas.</p>}
        {(tournament.playDates || []).map((dateInfo, di) => {
          const dateColor = GROUP_COLORS[di % GROUP_COLORS.length];
          const times = dayTimeSlots(dateInfo, duration);
          // Partidos de ese día con un horario que no cae en la grilla (cambió el arranque o la duración)
          const extraTimes = [...new Set(scheduled.filter((m) => m.schedule.date === dateInfo.date && !times.includes(m.schedule.time)).map((m) => m.schedule.time))];
          const allTimes = [...times, ...extraTimes].sort();
          // Solo las canchas de las sedes que se usan ese día
          const courts = courtsOfDay(tournament, dateInfo.date, scheduled);
          return (
            <section key={dateInfo.date} className="mb-6">
              <div className="mb-2"><SkewPill color={dateColor}>{formatDateShort(dateInfo.date)}</SkewPill></div>
              <div className="overflow-x-auto rounded-lg border" style={{ borderColor: dateColor + "33" }}>
                <table className="border-collapse w-full" style={{ minWidth: 56 + courts.length * 140 }}>
                  <thead>
                    <tr>
                      <th className="sticky left-0 z-10 text-left text-[11px] text-teal-500 px-2 py-1.5 w-14" style={{ ...F.body, backgroundColor: "#0b1c24" }}>Hora</th>
                      {courts.map((court) => (
                        <th key={court} className="text-center text-[11px] font-extrabold uppercase tracking-wide px-1 py-1.5" style={{ ...F.body, color: dateColor }}>{courtName(tournament, court)}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {allTimes.map((time) => (
                      <tr key={time} style={{ borderTop: `1px solid ${dateColor}22` }}>
                        <td className="sticky left-0 z-10 text-[11px] text-teal-400 align-top px-2 py-1.5 whitespace-nowrap font-semibold" style={{ ...F.body, backgroundColor: "#0b1c24" }}>{time}</td>
                        {courts.map((court) => {
                          const here = matchesAtSlot(scheduled, dateInfo.date, time, court, null);
                          return (
                            <td key={court} className="align-top p-1" style={{ width: 140, borderLeft: `1px solid ${dateColor}14`, ...(here.length > 1 ? { backgroundColor: "#f8717122" } : closed.has(`${dateInfo.date}|${time}|${court}`) ? { backgroundColor: "#0f172a99" } : {}) }}>
                              <div className="space-y-1">{here.map(cell)}</div>
                            </td>
                          );
                        })}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>
          );
        })}
      </div>
    </div>
  );
}

/* Imágenes del fixture para redes (ver fixtureImage.js): una por sede y por día, con vista previa,
   Descargar y, en el celular, Compartir (para subirla directo a una historia o a WhatsApp) */
function FixtureImagesModal({ tournament, matches, pairsById, onClose }) {
  const complexes = React.useContext(ComplexesContext);
  const pages = useMemo(() => fixturePages(tournament, matches, pairsById, complexes), [tournament, matches, pairsById, complexes]);
  // El torneo cambia seguido (por ejemplo, al volver cada guardado): las imágenes se vuelven a
  // dibujar solo si cambió lo que muestran
  const pagesKey = JSON.stringify(pages);
  const [images, setImages] = useState(null); // [{ page, url, blob }]

  useEffect(() => {
    let cancelled = false;
    const pages = JSON.parse(pagesKey);
    (async () => {
      try {
        await Promise.all([document.fonts.load("40px 'Archivo Black'"), document.fonts.load("600 40px 'Work Sans'"), document.fonts.load("700 40px 'Work Sans'")]);
      } catch { /* sin las fuentes se dibuja igual */ }
      const brand = await loadImage(logoMarkUrl);
      const logos = {};
      for (const pg of pages) if (pg.logoUrl && !(pg.logoUrl in logos)) logos[pg.logoUrl] = await loadImage(pg.logoUrl);
      const out = [];
      for (const pg of pages) {
        const canvas = document.createElement("canvas");
        drawFixture(canvas, pg, tournament.name, logos[pg.logoUrl] || null, brand);
        const blob = await new Promise((res) => canvas.toBlob(res, "image/png"));
        if (blob) out.push({ page: pg, url: URL.createObjectURL(blob), blob });
      }
      if (cancelled) out.forEach((o) => URL.revokeObjectURL(o.url));
      else setImages(out);
    })();
    return () => { cancelled = true; };
  }, [pagesKey, tournament.name]);
  useEffect(() => () => { (images || []).forEach((o) => URL.revokeObjectURL(o.url)); }, [images]);

  const canShare = typeof navigator !== "undefined" && !!navigator.canShare;
  const share = async (o) => {
    const file = new File([o.blob], fixtureFileName(o.page), { type: "image/png" });
    if (!navigator.canShare({ files: [file] })) return;
    try { await navigator.share({ files: [file], title: tournament.name }); } catch { /* la cerró sin compartir */ }
  };

  return (
    <Modal title="Imágenes para redes" onClose={onClose}>
      <p className="text-xs text-teal-400 mb-4" style={F.body}>Una imagen por sede y por día (formato historia, 1080×1920), con los partidos que ya tienen horario.</p>
      {!images ? (
        <p className="text-sm text-teal-300" style={F.body}>Armando las imágenes…</p>
      ) : images.length === 0 ? (
        <p className="text-sm opacity-70" style={F.body}>Todavía no hay partidos con horario.</p>
      ) : (
        <div className="grid grid-cols-2 gap-4">
          {images.map((o) => (
            <div key={o.url} className="min-w-0">
              <img src={o.url} alt={`Fixture ${o.page.venueName} ${fixtureDateLabel(o.page.date)}`} className="w-full rounded-lg border border-teal-800" />
              <p className="text-[11px] text-teal-300 mt-1 truncate" style={F.body}>
                {o.page.venueName || tournament.name} · {fixtureDateLabel(o.page.date)}{o.page.pages > 1 ? ` (${o.page.page}/${o.page.pages})` : ""}
              </p>
              <div className="flex gap-2 mt-1 flex-wrap">
                <a href={o.url} download={fixtureFileName(o.page)} className="px-3 py-1.5 rounded font-semibold text-xs" style={{ backgroundColor: "#9fe022", color: "#14181f" }}>Descargar</a>
                {canShare && <button type="button" onClick={() => share(o)} className="px-3 py-1.5 rounded font-semibold text-xs border border-teal-600 text-teal-200">Compartir</button>}
              </div>
            </div>
          ))}
        </div>
      )}
    </Modal>
  );
}

/* Avisos de la pestaña Horarios (y de la tira de resumen del torneo): [{ key, text, day?, categoryId? }],
   donde day / categoryId dicen a dónde lleva "Ver". También devuelve los partidos de grupos puestos en
   un horario en que alguna de sus parejas dijo que no puede: { [key]: [pairId] }. */
function scheduleAlerts(tournament, matches) {
  const scheduled = matches.filter((m) => m.schedule);
  const duration = tournament.matchDurationMinutes || DEFAULT_MATCH_DURATION;
  const courtsCount = tournament.courtsCount || 4;
  const playDates = tournament.playDates || [];
  // Partidos con un horario que ya no entra en la grilla (por ejemplo porque cambió el horario de
  // arranque, la duración o la cantidad de canchas): no se ven en ninguna celda
  const gridSlots = new Set();
  playDates.forEach((d) => {
    dayTimeSlots(d, duration).forEach((time) => {
      for (let c = 1; c <= courtsCount; c++) gridSlots.add(`${d.date}|${time}|${c}`);
    });
  });
  const offGrid = scheduled.filter((m) => !matchIsPlayed(m, tournament.matchFormat) && m.liveStatus !== "en_curso" && !gridSlots.has(`${m.schedule.date}|${m.schedule.time}|${m.schedule.court}`));
  // Partidos en una sede que ese día (o a esa hora) no se usa
  const atClosed = matchesAtClosedCourts(tournament, scheduled.filter((m) => !matchIsPlayed(m, tournament.matchFormat) && m.liveStatus !== "en_curso"));
  // Partidos de grupos puestos (a mano) en un horario en que alguna de las parejas no puede
  const offAvailability = Object.fromEntries(scheduled.map((m) => [m.key, pairsOutsideAvailability(tournament, m)]).filter(([, ids]) => ids.length > 0));
  const offAvailabilityCount = Object.keys(offAvailability).length;
  const capacityNotice = bracketCapacityNotice(tournament);
  const splitGroups = groupsSplitAcrossVenues(tournament);
  const sameDayNotices = sameDayBracketNotices(tournament);

  const firstOf = (list) => list.slice().sort(compareBySchedule)[0];
  const alerts = [];
  if (offGrid.length > 0) alerts.push({ key: "offgrid", text: `${offGrid.length === 1 ? "Hay 1 partido" : `Hay ${offGrid.length} partidos`} con un horario que ya no entra en la grilla (cambió el horario, las canchas o la duración). Tocá "Rearmar horarios" para volver a ubicarlos.` });
  if (atClosed.length > 0) alerts.push({ key: "closed", day: firstOf(atClosed).schedule.date, text: `${atClosed.length === 1 ? "Hay 1 partido" : `Hay ${atClosed.length} partidos`} en una sede que ese día o a esa hora no se usa (${[...new Set(atClosed.map((m) => (tournament.venues || [])[courtVenueIndex(tournament, m.schedule.court)]?.name))].join(", ")}). Movelos a mano o tocá "Rearmar horarios".` });
  if (capacityNotice) alerts.push({ key: "capacity", text: capacityNotice });
  // "6TA FEM Grupo B": la categoría es la de nombre más largo que coincide (no "6TA")
  const splitCategory = splitGroups.length > 0
    ? tournament.categories.filter((c) => splitGroups[0].startsWith(`${c.name} `)).sort((a, b) => b.name.length - a.name.length)[0]
    : null;
  if (splitGroups.length > 0) alerts.push({ key: "split", categoryId: splitCategory?.id, text: `${splitGroups.length === 1 ? "Un grupo quedó" : `${splitGroups.length} grupos quedaron`} en más de una sede porque no entraba${splitGroups.length === 1 ? "" : "n"} en una sola: ${splitGroups.join(", ")}. Podés moverlos a mano en la planilla.` });
  sameDayNotices.forEach((text) => alerts.push({ key: `sameday-${text}`, text }));
  // Una pareja en dos partidos a la vez (por ejemplo, después de mover uno a mano). Si los dos ya se
  // jugaron no se avisa: ya pasó.
  const played = (m) => matchIsPlayed(m, tournament.matchFormat);
  const startOf = (s) => Date.parse(`${s.date}T00:00:00Z`) / 60000 + timeToMinutes(s.time);
  const byPair = {};
  scheduled.forEach((m) => [m.pairA, m.pairB].filter(Boolean).forEach((pid) => (byPair[`${m.categoryId}|${pid}`] = byPair[`${m.categoryId}|${pid}`] || []).push(m)));
  const overlapped = [];
  Object.values(byPair).forEach((list) => {
    list.sort(compareBySchedule);
    for (let i = 1; i < list.length; i++) {
      if (startOf(list[i].schedule) - startOf(list[i - 1].schedule) < duration && !(played(list[i]) && played(list[i - 1]))) overlapped.push(list[i]);
    }
  });
  if (overlapped.length > 0) {
    const first = firstOf(overlapped);
    alerts.push({ key: "overlap", day: first.schedule.date, categoryId: first.categoryId, text: `${overlapped.length === 1 ? "Hay 1 pareja" : `Hay ${overlapped.length} parejas`} con dos partidos a la vez (${[...new Set(overlapped.map((m) => m.categoryName))].join(", ")}; por ejemplo #${first.number || "?"} el ${formatDateShort(first.schedule.date)} a las ${first.schedule.time}). Mové uno de los dos.` });
  }
  // Llave: un partido que empieza antes de que termine el que lo alimenta, o sin el descanso
  const rest = Math.max(tournament.bracketRestMinutes || DEFAULT_BRACKET_REST, duration);
  const shortRest = [];
  (tournament.categories || []).forEach((c) => {
    if (!c.bracket) return;
    const { byes } = walkBracket(c.bracket, tournament.matchFormat);
    const nums = categoryMatchNumbers(c);
    c.bracket.forEach((round, ri) => ri > 0 && round.forEach((m, mi) => {
      if (!m.schedule || isByeMatch(byes, ri, mi)) return;
      [2 * mi, 2 * mi + 1].forEach((fi) => {
        const child = c.bracket[ri - 1][fi];
        if (!child?.schedule || isByeMatch(byes, ri - 1, fi) || (played(m) && played(child))) return;
        const gap = startOf(m.schedule) - startOf(child.schedule);
        if (gap < rest) shortRest.push({ c, m, child, gap, nums });
      });
    }));
  });
  if (shortRest.length > 0) {
    const { c, m, child, gap, nums } = shortRest.sort((a, b) => a.gap - b.gap)[0]; // primero el más grave
    alerts.push({ key: "rest", day: m.schedule.date, categoryId: c.id, text: `${shortRest.length === 1 ? "Hay 1 partido" : `Hay ${shortRest.length} partidos`} de llave ${gap < duration ? "que se superpone" : `sin el descanso de ${formatRest(rest)}`} con el partido que lo alimenta: por ejemplo, en ${c.name}, el #${nums.get(m.id) || "?"} (${formatDateShort(m.schedule.date)} ${m.schedule.time}) y el #${nums.get(child.id) || "?"} (${formatDateShort(child.schedule.date)} ${child.schedule.time}). Movelo o tocá "Rearmar horarios".` });
  }
  if (offAvailabilityCount > 0) {
    const first = firstOf(scheduled.filter((m) => offAvailability[m.key]));
    alerts.push({ key: "avail", day: first.schedule.date, categoryId: first.categoryId, text: `${offAvailabilityCount === 1 ? "Hay 1 partido" : `Hay ${offAvailabilityCount} partidos`} en un horario en que alguna de las parejas dijo que no puede (marcados en la planilla). Si ya lo hablaste con ellas, no hace falta hacer nada.` });
  }
  return { alerts, offAvailability };
}

function ScheduleAdminView({ tournament, update, onGoConfig }) {
  const [notice, setNotice] = useState(null);
  const [gridOpen, setGridOpen] = useState(false);
  const [fixtureOpen, setFixtureOpen] = useState(false);
  // Resultado y mover se hacen en ventanitas (sirven también en el celular, donde arrastrar no anda)
  const { pairsById, matches, openResult, openMove, setLive, modals } = useMatchActions(tournament, update);
  const scheduled = matches.filter((m) => m.schedule);
  const unscheduled = matches.filter((m) => !m.schedule);
  const duration = tournament.matchDurationMinutes || DEFAULT_MATCH_DURATION;
  const courtsCount = tournament.courtsCount || 4;
  const playDates = tournament.playDates || [];

  const editSchedule = (m, schedule) => { update(withMatchSchedule(tournament, m.categoryId, m.location, m.matchId, schedule)); };
  const clearSchedule = (m) => { update(withMatchSchedule(tournament, m.categoryId, m.location, m.matchId, null)); setNotice(null); };

  const [confirmingReschedule, setConfirmingReschedule] = useState(false);
  const reschedule = () => { update(rescheduleTournament(tournament)); setConfirmingReschedule(false); setNotice(null); };

  const closed = closedCourtSlots(tournament);
  // Avisos (ver scheduleAlerts) y partidos de grupos fuera de la disponibilidad de una pareja
  const { alerts, offAvailability } = useMemo(() => scheduleAlerts(tournament, matches), [tournament, matches]);
  const offAvailabilityCount = Object.keys(offAvailability).length;

  const draftCategories = tournament.categories.filter((c) => c.bracket && !c.bracketPublished && (c.bracket || []).some((round) => round.some((m) => m.pairA && m.pairB && m.schedule)));

  const onDragStartMatch = (key) => (e) => { e.dataTransfer.setData("text/plain", key); };

  const onDropOnCell = (dateInfo, time, court) => (e) => {
    e.preventDefault();
    const key = e.dataTransfer.getData("text/plain");
    const m = matches.find((mm) => mm.key === key);
    if (!m) return;
    const occupants = matchesAtSlot(scheduled, dateInfo.date, time, court, key);
    if (occupants.length > 0) {
      const nextTime = minutesToTime(timeToMinutes(time) + duration);
      const free = findNextFreeSlotOnCourt(scheduled, dateInfo, court, nextTime, duration, key, closed);
      if (free) {
        editSchedule(m, free);
        setNotice(`Ese horario ya estaba ocupado en ${courtName(tournament, court)}. Ubiqué el partido en ${formatDateShort(free.date)} · ${free.time}hs · ${courtName(tournament, free.court)}.`);
      } else {
        setNotice(`${courtName(tournament, court)} ya está ocupada a esa hora y no quedan horarios libres en esa cancha para ese día. No se movió el partido.`);
      }
    } else {
      editSchedule(m, { date: dateInfo.date, time, court });
      setNotice(null);
    }
  };

  const onDropOnTray = (e) => {
    e.preventDefault();
    const key = e.dataTransfer.getData("text/plain");
    const m = matches.find((mm) => mm.key === key);
    if (m) clearSchedule(m);
  };

  const [alertsOpen, setAlertsOpen] = useState(false);

  // Un día a la vez (arranca hoy si es un día del torneo) y filtros por sede y por categoría
  const [chosenDay, setDay] = useState(() => (playDates.some((d) => d.date === todayISO()) ? todayISO() : playDates[0]?.date || null));
  const dayIndex = Math.max(0, playDates.findIndex((d) => d.date === chosenDay));
  const dateInfo = playDates[dayIndex] || null;
  const [venueFilter, setVenueFilter] = useState(""); // índice de sede, "" = todas
  const [categoryFilter, setCategoryFilter] = useState(""); // id de categoría, "" = todas
  const venues = tournament.venues || [];
  const inCategory = (m) => !categoryFilter || m.categoryId === categoryFilter;
  const trayMatches = unscheduled.filter(inCategory);
  const goTo = (a) => { if (a.day) setDay(a.day); if (a.categoryId) setCategoryFilter(a.categoryId); };

  // Canchas, sedes y fechas se cargan en Configuración: acá, en una línea
  const configSummary = [
    venues.length > 0 ? `${venues.length} sede${venues.length === 1 ? "" : "s"}` : null,
    `${courtsCount} cancha${courtsCount === 1 ? "" : "s"}`,
    playDates.length > 0 ? (playDates.length === 1 ? formatDateShort(playDates[0].date) : `${formatDateShort(playDates[0].date)} a ${formatDateShort(playDates[playDates.length - 1].date)}`) : "sin fechas",
    `${duration} min por partido`,
  ].filter(Boolean).join(" · ");

  const pill = "px-3 py-1.5 rounded-full text-xs border whitespace-nowrap";
  const selectStyle = { backgroundColor: "#eef2f2", color: "#111827", borderColor: "#94a3b8" };

  return (
    <div>
      {gridOpen && <ScheduleGridOverlay tournament={tournament} matches={matches} pairsById={pairsById} onOpenResult={openResult} onClose={() => setGridOpen(false)} />}
      {fixtureOpen && <FixtureImagesModal tournament={tournament} matches={matches} pairsById={pairsById} onClose={() => setFixtureOpen(false)} />}
      {modals}

      <button type="button" onClick={onGoConfig} className="w-full flex items-center justify-between gap-3 flex-wrap px-4 py-2.5 mb-4 rounded-lg border border-teal-800 hover:border-teal-500 text-left" style={F.body}>
        <span className="text-xs text-teal-300">🏟 {configSummary}</span>
        <span className="text-xs text-lime-400 font-semibold">Cambiar en Configuración →</span>
      </button>

      {matches.length === 0 ? (
        <p className="opacity-60 text-sm" style={F.body}>Todavía no hay partidos con ambas parejas definidas (cargá grupos o llave en alguna categoría).</p>
      ) : (
        <>
          <div className="flex gap-2 flex-wrap items-center mb-2">
            <button
              type="button"
              onClick={() => update(autoSchedule(tournament))}
              disabled={playDates.length === 0}
              title="Completa los partidos de grupos sin horario (se repite solo apenas se cierra un grupo)"
              className="px-4 py-2 rounded font-semibold text-sm disabled:opacity-40" style={{ backgroundColor: "#9fe022", color: "#14181f" }}
            >
              Generar horarios de grupos
            </button>
            {scheduled.length > 0 && (confirmingReschedule ? (
              <span className="text-xs" style={F.body}>
                <span className="text-teal-300 mr-2">Se borran los horarios de los partidos que no se jugaron y se vuelven a asignar. ¿Confirmás?</span>
                <button type="button" onClick={reschedule} className="text-lime-400 font-semibold mr-2">Sí, rearmar</button>
                <button type="button" onClick={() => setConfirmingReschedule(false)} className="text-teal-400">Cancelar</button>
              </span>
            ) : (
              <button type="button" disabled={playDates.length === 0} onClick={() => setConfirmingReschedule(true)} title="Vuelve a ubicar desde cero todo lo que no se jugó, incluida la llave" className="px-4 py-2 rounded font-semibold text-sm border border-lime-400 text-lime-400 disabled:opacity-40" style={F.body}>
                Rearmar horarios
              </button>
            ))}
            <span className="flex-1" />
            {tournamentType(tournament) === "clasico" && scheduled.length > 0 && (
              <button type="button" onClick={() => setFixtureOpen(true)} className="px-3 py-2 rounded-full font-semibold text-xs flex items-center gap-1.5" style={{ ...F.body, ...neonStyle(BRAND.lime), color: BRAND.ink, backgroundColor: "rgba(8,18,24,0.7)" }}>
                📸 Imágenes para redes
              </button>
            )}
            <button type="button" onClick={() => setGridOpen(true)} className="px-3 py-2 rounded-full font-semibold text-xs flex items-center gap-1.5" style={{ ...F.body, ...neonStyle(BRAND.cyan), color: BRAND.ink, backgroundColor: "rgba(8,18,24,0.7)" }}>
              ▦ Pantalla completa
            </button>
          </div>
          <p className="text-[11px] text-teal-600 mb-4" style={F.body}>Arrastrá las tarjetas para reubicarlas, o tocá "⇄ Mover". "Rearmar" vuelve a ubicar todo lo que no se jugó: usalo si cambiaste fechas, sedes o canchas.</p>

          {alerts.length > 0 && (
            <div className="mb-4 rounded-lg border" style={{ ...F.body, borderColor: "#fbbf2460", backgroundColor: "#fbbf2410" }}>
              <button type="button" onClick={() => setAlertsOpen(!alertsOpen)} className="w-full flex items-center justify-between px-3 py-2 text-sm font-semibold" style={{ color: "#fbbf24" }}>
                <span>⚠ {alerts.length === 1 ? "1 aviso" : `${alerts.length} avisos`}</span>
                <span className="text-xs">{alertsOpen ? "Ocultar ▴" : "Ver ▾"}</span>
              </button>
              {alertsOpen && (
                <ul className="px-3 pb-3 space-y-2">
                  {alerts.map((a) => (
                    <li key={a.key} className="text-xs leading-snug" style={{ color: "#fcd34d" }}>
                      {a.text}
                      {(a.day || a.categoryId) && <button type="button" onClick={() => goTo(a)} className="ml-1 underline font-semibold text-lime-400">Ver</button>}
                    </li>
                  ))}
                </ul>
              )}
            </div>
          )}

          {draftCategories.length > 0 && (
            <div className="mb-4 flex flex-col gap-2">
              {draftCategories.map((c) => (
                <div key={c.id} className="flex items-center justify-between gap-3 flex-wrap px-3 py-2 rounded border" style={{ borderColor: "#a78bfa60", backgroundColor: "#a78bfa14" }}>
                  <span className="text-xs" style={{ ...F.body, color: "#a78bfa" }}>
                    La llave de <strong>{c.name}</strong> tiene horarios en borrador, todavía no visibles para los jugadores.
                  </span>
                  <button
                    type="button"
                    onClick={() => update(publishBracketSchedule(tournament, c.id))}
                    className="text-xs font-semibold px-3 py-1.5 rounded"
                    style={{ backgroundColor: "#a78bfa", color: "#14181f" }}
                  >
                    Publicar horarios de la llave
                  </button>
                </div>
              ))}
            </div>
          )}

          {notice && (
            <div className="mb-4 px-3 py-2 rounded text-xs border" style={{ ...F.body, borderColor: "#fb923c60", backgroundColor: "#fb923c14", color: "#fb923c" }}>
              {notice}
            </div>
          )}

          {!dateInfo ? (
            <p className="opacity-60 text-sm mb-6" style={F.body}>Cargá al menos una fecha en <button type="button" onClick={onGoConfig} className="underline text-lime-400">Configuración</button> para poder armar la planilla.</p>
          ) : (
            <>
              <div className="flex items-center gap-2 flex-wrap mb-3" style={F.body}>
                {playDates.map((d, di) => {
                  const on = d.date === dateInfo.date;
                  const color = GROUP_COLORS[di % GROUP_COLORS.length];
                  const count = scheduled.filter((m) => m.schedule.date === d.date && inCategory(m)).length;
                  return (
                    <button key={d.date} type="button" onClick={() => setDay(d.date)} className={pill} style={on ? { backgroundColor: color, borderColor: color, color: "#14181f", fontWeight: 700 } : { borderColor: color + "60", color }}>
                      {formatDateShort(d.date)} <span className="opacity-70">· {count}</span>
                    </button>
                  );
                })}
                <span className="flex-1" />
                {venues.length >= 2 && (
                  <select value={venueFilter} onChange={(e) => setVenueFilter(e.target.value)} aria-label="Sede" className="px-2 py-1.5 rounded border text-xs" style={selectStyle}>
                    <option value="">Todas las sedes</option>
                    {venues.map((v, i) => <option key={v.id} value={i}>{v.name}</option>)}
                  </select>
                )}
                {tournament.categories.length >= 2 && (
                  <select value={categoryFilter} onChange={(e) => setCategoryFilter(e.target.value)} aria-label="Categoría" className="px-2 py-1.5 rounded border text-xs" style={selectStyle}>
                    <option value="">Todas las categorías</option>
                    {tournament.categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                )}
              </div>

              <StreamLinksEditor tournament={tournament} date={dateInfo.date} courts={courtsOfDay(tournament, dateInfo.date, scheduled)} onSave={(streams) => update({ ...tournament, streams })} />
              <div className="lg:flex lg:items-start lg:gap-4">
                <div className="flex-1 min-w-0 mb-6">
                  <ScheduleDayGrid
                    tournament={tournament} dateInfo={dateInfo} dateColor={GROUP_COLORS[dayIndex % GROUP_COLORS.length]}
                    scheduled={scheduled} trayMatches={trayMatches} closed={closed} pairsById={pairsById} offAvailability={offAvailability}
                    venueFilter={venueFilter === "" ? null : Number(venueFilter)} inCategory={inCategory}
                    onDropOnCell={onDropOnCell} onDragStartMatch={onDragStartMatch} onAssign={editSchedule} onClear={clearSchedule}
                    onResult={openResult} onMove={openMove} onLive={setLive} onNotice={setNotice}
                  />
                  <div className="flex flex-wrap gap-3 mt-3 text-[11px]" style={F.body}>
                    {[["#38bdf8", "Fase de grupos", false], ["#a78bfa", "Llave (borrador)", true], ["#fb923c", "En curso", false], ["#9fe022", "Finalizado", false], ["#f87171", "Choque", false], ...(offAvailabilityCount > 0 ? [["#fbbf24", "⚠ Fuera de disponibilidad", false]] : [])].map(([color, label, dashed]) => (
                      <span key={label} className="flex items-center gap-1.5">
                        <span className="w-3 h-3 rounded-sm inline-block" style={{ border: `1.5px ${dashed ? "dashed" : "solid"} ${color}`, backgroundColor: color + "22" }} />
                        {label}
                      </span>
                    ))}
                  </div>
                </div>

                {/* Sin horario: al costado y fijo mientras se recorre la planilla (en el celular, abajo).
                    Soltar acá una tarjeta le quita el horario. */}
                <aside
                  onDragOver={(e) => e.preventDefault()} onDrop={onDropOnTray}
                  className="lg:w-64 shrink-0 lg:sticky lg:top-4 lg:max-h-[calc(100vh-2rem)] lg:overflow-y-auto rounded-xl border border-teal-800 p-3 mb-6"
                  style={F.body}
                >
                  <p className="text-sm font-semibold text-teal-200 mb-1">Sin horario ({trayMatches.length})</p>
                  <p className="text-[11px] text-teal-600 mb-2">Arrastralos a la planilla o tocá "Ubicar". Soltá acá una tarjeta para sacarle el horario.</p>
                  {trayMatches.length === 0 && <p className="text-xs text-lime-400">Todos los partidos{categoryFilter ? " de esta categoría" : ""} tienen horario ✓</p>}
                  <div className="space-y-1.5">
                    {trayMatches.map((m) => (
                      <div key={m.key} draggable onDragStart={onDragStartMatch(m.key)} className="rounded-md px-2 py-1.5 text-[11px] leading-tight border cursor-grab" style={{ borderColor: m.draft ? "#a78bfa" : "#38bdf866", borderStyle: m.draft ? "dashed" : "solid" }}>
                        <p className="text-teal-500 truncate">{m.number ? `#${m.number} · ` : ""}{m.categoryName}{m.label ? ` · ${m.label}` : ""}</p>
                        {m.placeholder && !(m.pairA && m.pairB)
                          ? <p className="italic opacity-70 truncate">{m.placeholder}</p>
                          : <p className="truncate"><PairName id={m.pairA} pairsById={pairsById} /> <span className="opacity-60">vs</span> <PairName id={m.pairB} pairsById={pairsById} /></p>}
                        <button type="button" onClick={() => openMove(m)} className="mt-0.5 text-[10px] underline text-teal-300 hover:text-lime-400">Ubicar</button>
                      </div>
                    ))}
                  </div>
                </aside>
              </div>
            </>
          )}
        </>
      )}
    </div>
  );
}

/* Planilla de un día de la pestaña Horarios: en la compu, horas x canchas (arrastrar y soltar); en
   el celular, cancha por cancha. Con filtro de sede solo muestra sus canchas; con filtro de
   categoría, los partidos de las demás se ven como "Ocupado" (la cancha no está libre). */
function ScheduleDayGrid({ tournament, dateInfo, dateColor, scheduled, trayMatches, closed, pairsById, offAvailability, venueFilter, inCategory, onDropOnCell, onDragStartMatch, onAssign, onClear, onResult, onMove, onLive, onNotice }) {
  const duration = tournament.matchDurationMinutes || DEFAULT_MATCH_DURATION;
  const times = dayTimeSlots(dateInfo, duration);
  // Solo las canchas de las sedes que se usan ese día (y de la sede elegida)
  const courts = courtsOfDay(tournament, dateInfo.date, scheduled).filter((c) => venueFilter == null || courtVenueIndex(tournament, c) === venueFilter);
  const busyCard = (m) => (
    <div key={m.key} className="rounded-md px-2 py-1.5 mb-1 text-[10px] text-slate-500 border border-slate-700" style={F.body}>Ocupado · {m.categoryName}</div>
  );
  const card = (m, conflict, draggable) => (inCategory(m)
    ? <GridMatchCard key={m.key} m={m} format={tournament.matchFormat} pairsById={pairsById} conflict={conflict} offAvailability={offAvailability[m.key]} onDragStart={draggable ? onDragStartMatch(m.key) : undefined} onClear={() => onClear(m)} onResult={() => onResult(m)} onMove={() => onMove(m)} onLive={onLive ? (st) => onLive(m, st) : undefined} />
    : busyCard(m));

  if (courts.length === 0) return <p className="opacity-60 text-sm" style={F.body}>Ninguna cancha de esta sede se usa ese día.</p>;
  return (
    <>
      <div className="hidden sm:block overflow-x-auto">
        <table className="border-collapse w-full" style={{ minWidth: 64 + courts.length * 130 }}>
          <thead>
            <tr>
              <th className="sticky left-0 z-10 text-left text-[11px] text-teal-500 pb-1 pr-2 w-16" style={{ ...F.body, backgroundColor: "#0b1c24" }}>Hora</th>
              {courts.map((court) => (
                <th key={court} className="text-center text-[11px] font-extrabold uppercase tracking-wide px-1 pb-1" style={{ ...F.body, color: dateColor }}>
                  {courtName(tournament, court)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {times.map((time) => (
              <tr key={time}>
                <td className="sticky left-0 z-10 text-[11px] text-teal-500 align-top pt-2 pr-2 whitespace-nowrap" style={{ ...F.body, backgroundColor: "#0b1c24" }}>{time}</td>
                {courts.map((court) => {
                  const cellMatches = matchesAtSlot(scheduled, dateInfo.date, time, court, null);
                  const conflict = cellMatches.length > 1;
                  const isClosed = closed.has(`${dateInfo.date}|${time}|${court}`);
                  // Su sede no se usa a esa hora: sin "+ Asignar" ni soltar partidos
                  if (cellMatches.length === 0 && isClosed) {
                    return (
                      <td key={court} className="align-middle p-1 border text-center text-[10px] text-slate-500" style={{ ...F.body, borderColor: dateColor + "22", minWidth: 130, backgroundColor: "#0f172a66" }} title="Esta sede no se usa a esa hora">
                        Sede cerrada
                      </td>
                    );
                  }
                  return (
                    <td
                      key={court}
                      onDragOver={(e) => e.preventDefault()}
                      onDrop={onDropOnCell(dateInfo, time, court)}
                      className="align-top p-1 border"
                      style={{ borderColor: dateColor + "22", minWidth: 130, ...(isClosed ? { backgroundColor: "#0f172a66" } : {}) }}
                    >
                      {cellMatches.length === 0 ? (
                        <select
                          value=""
                          onChange={(e) => { const m = trayMatches.find((u) => u.key === e.target.value); if (m) onAssign(m, { date: dateInfo.date, time, court }); }}
                          className="w-full text-[10px] px-1 py-1.5 rounded border border-dashed opacity-60"
                          style={{ backgroundColor: "transparent", borderColor: dateColor + "60", color: "#94a3b8" }}
                        >
                          <option value="">+ Asignar partido</option>
                          {trayMatches.map((u) => <option key={u.key} value={u.key}>{u.categoryName} · {u.label}</option>)}
                        </select>
                      ) : (
                        cellMatches.map((m) => card(m, conflict, true))
                      )}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {/* En el celular: cancha por cancha, en una columna (la tabla no entra a lo ancho) */}
      <div className="sm:hidden space-y-4">
        {courts.map((court) => {
          const courtMatches = scheduled.filter((m) => m.schedule.date === dateInfo.date && m.schedule.court === court).sort(compareBySchedule);
          return (
            <div key={court} className="rounded-xl border p-3" style={{ borderColor: dateColor + "40" }}>
              <p className="text-xs font-extrabold uppercase tracking-wide mb-2" style={{ ...F.body, color: dateColor }}>{courtName(tournament, court)}</p>
              {courtMatches.length === 0 && <p className="text-xs opacity-60 mb-2" style={F.body}>Sin partidos.</p>}
              {courtMatches.map((m) => (
                <div key={m.key} className="flex gap-2 items-start">
                  <span className="text-xs font-bold w-11 shrink-0 pt-1.5" style={{ ...F.body, color: dateColor }}>{m.schedule.time}</span>
                  <div className="flex-1 min-w-0">{card(m, matchesAtSlot(scheduled, m.schedule.date, m.schedule.time, court, null).length > 1, false)}</div>
                </div>
              ))}
              {trayMatches.length > 0 && (
                <select
                  value=""
                  onChange={(e) => {
                    const m = trayMatches.find((u) => u.key === e.target.value);
                    const free = m && findNextFreeSlotOnCourt(scheduled, dateInfo, court, dateInfo.from, duration, null, closed);
                    if (free) onAssign(m, free);
                    else if (m) onNotice(`${courtName(tournament, court)} no tiene horarios libres ese día.`);
                  }}
                  className="w-full mt-1 text-sm px-2 py-2 rounded border border-dashed"
                  style={{ backgroundColor: "transparent", borderColor: dateColor + "60", color: "#94a3b8" }}
                >
                  <option value="">+ Agregar partido en el primer horario libre</option>
                  {trayMatches.map((u) => <option key={u.key} value={u.key}>{u.categoryName} · {u.label}</option>)}
                </select>
              )}
            </div>
          );
        })}
      </div>
    </>
  );
}

/* Resultado en formato marcador: una pareja por renglón y los games de cada set en columnas a la
   derecha. La pareja ganadora va en verde y el número ganador de cada set en negrita. Un W.O. se
   muestra con el resultado con que se computa (6-0 6-0) y la marca W.O. en la pareja que no se
   presentó. */
function Scoreboard({ match, pairsById, format }) {
  const sets = effectiveSets(match, format).filter((s) => s && s.a != null && s.b != null);
  const winner = matchWinnerId(match, format);
  const line = (side) => {
    const id = side === "a" ? match.pairA : match.pairB;
    const other = side === "a" ? "b" : "a";
    const won = winner === id;
    // Los nombres largos bajan de renglón (no se cortan); los games quedan arriba, a la derecha
    return (
      <div className="flex items-start gap-2 min-w-0">
        <span className={`flex-1 min-w-0 break-words ${won ? "text-lime-400 font-semibold" : "text-slate-300"}`}>
          {pairsById[id]?.name || "—"}
          {match.walkover === id && <span className="ml-1.5 text-[9px] font-bold text-amber-400">W.O.</span>}
          {match.retired === id && <span className="ml-1.5 text-[9px] font-bold text-red-400">RET</span>}
        </span>
        <span className="flex gap-1 shrink-0 font-mono">
          {sets.map((s, i) => (
            <span key={i} className={`w-5 text-center ${s[side] > s[other] ? "font-extrabold text-slate-100" : "text-slate-400"}`}>{s[side]}</span>
          ))}
        </span>
      </div>
    );
  };
  return (
    <div className="text-sm leading-snug">
      {line("a")}
      {line("b")}
    </div>
  );
}

/* Horarios en modo lectura para la vista pública: una lista compacta por día y horario, dos
   renglones por partido ("C1 · Gómez - Ibáñez vs Rossi - Peralta · 6-3 6-3" y debajo la
   categoría), con un botón "Ahora" que lleva al horario que se está jugando. */
function SchedulePublicView({ tournament }) {
  const pairsById = useMemo(() => {
    const map = {};
    tournament.categories.forEach((c) => Object.assign(map, categoryEntitiesById(c)));
    return map;
  }, [tournament.categories]);

  const categoryColor = useMemo(() => {
    const map = {};
    tournament.categories.forEach((c, ci) => { map[c.id] = GROUP_COLORS[ci % GROUP_COLORS.length]; });
    return map;
  }, [tournament.categories]);

  const scheduled = useMemo(() => collectScheduleableMatches(tournament).filter((m) => m.schedule && !m.draft).sort(compareBySchedule), [tournament]);

  if (scheduled.length === 0) {
    return <p className="opacity-60 text-sm" style={F.body}>Todavía no hay horarios publicados para este torneo.</p>;
  }

  const slotId = (m) => `slot-${m.schedule.date}-${m.schedule.time.replace(":", "")}`;
  // "Ahora": el horario de un partido en curso; si no hay, el primero sin terminar de hoy (o de más adelante).
  // En un torneo finalizado no va (puede quedar algún partido sin resultado cargado)
  const today = todayISO();
  const pending = scheduled.filter((m) => !m.placeholder && !matchIsPlayed(m, tournament.matchFormat));
  const nowMatch = tournamentStatusOf(tournament) === STATUS.FINALIZADO ? null
    : scheduled.find((m) => m.liveStatus === "en_curso" && !matchIsPlayed(m, tournament.matchFormat))
      || pending.find((m) => m.schedule.date >= today)
      || pending[0];
  const goToNow = () => { if (nowMatch) document.getElementById(slotId(nowMatch))?.scrollIntoView({ behavior: "smooth", block: "start" }); };

  const byDate = {};
  scheduled.forEach((m) => { (byDate[m.schedule.date] = byDate[m.schedule.date] || []).push(m); });

  return (
    <div>
      {nowMatch && (
        <button type="button" onClick={goToNow} className="mb-4 px-4 py-2 rounded-full text-sm font-semibold" style={{ backgroundColor: "#fb923c", color: "#14181f", ...F.body }}>
          ● Ahora
        </button>
      )}
      {Object.keys(byDate).sort().map((date, di) => {
        const dateColor = GROUP_COLORS[di % GROUP_COLORS.length];
        const byTime = {};
        byDate[date].forEach((m) => { (byTime[m.schedule.time] = byTime[m.schedule.time] || []).push(m); });
        return (
          <div key={date} className="mb-6">
            <div className="mb-2"><SkewPill color={dateColor}>{formatDateShort(date)}</SkewPill></div>
            <StreamLinks tournament={tournament} date={date} />
            <div className="rounded-xl border divide-y min-w-0" style={{ borderColor: dateColor + "40" }}>
              {Object.keys(byTime).sort().map((time) => (
                <div key={time} id={slotId(byTime[time][0])} className="px-3 py-2 scroll-mt-4 space-y-2.5" style={{ borderColor: dateColor + "22" }}>
                    {byTime[time].map((m, i) => {
                      const hasResult = !m.placeholder && matchIsPlayed(m, tournament.matchFormat);
                      const w = hasResult ? matchWinnerId(m, tournament.matchFormat) : null;
                      const live = !hasResult && m.liveStatus === "en_curso";
                      const name = (id) => <span className={w === id ? "text-lime-400 font-semibold" : ""}>{pairsById[id]?.name || "—"}</span>;
                      // Columna izquierda: la hora (en el primer partido del horario) y el "vs"; a la
                      // derecha, la cancha y la categoría arriba y cada pareja en su propio renglón
                      return (
                        <div key={m.key} className="grid grid-cols-[2.75rem_minmax(0,1fr)] gap-x-2 text-sm" style={F.body}>
                          <span className="text-sm font-extrabold" style={{ color: dateColor }}>{i === 0 ? time : ""}</span>
                          <div className="flex items-baseline gap-2 min-w-0 text-[11px] pt-0.5">
                            <span className="min-w-0 truncate">
                              <span className="font-bold" style={{ color: dateColor }}>{courtName(tournament, m.schedule.court, true)}</span>
                              <span style={{ color: categoryColor[m.categoryId] }}> · {m.number ? `#${m.number} · ` : ""}{m.categoryName}</span>
                              {m.label && <span className="text-teal-500"> · {m.label}</span>}
                            </span>
                            {live && <span className="text-[10px] font-bold shrink-0 ml-auto" style={{ color: "#fb923c" }}>● EN CURSO</span>}
                            {live && streamOf(tournament, date, m.schedule.court) && <a href={streamOf(tournament, date, m.schedule.court)} target="_blank" rel="noopener noreferrer" className="text-[10px] font-bold shrink-0 underline" style={{ color: "#f87171" }}>▶ Ver</a>}
                          </div>
                          {hasResult ? (
                            <><span /><div className="min-w-0 mt-0.5"><Scoreboard match={m} pairsById={pairsById} format={tournament.matchFormat} /></div></>
                          ) : m.placeholder ? (
                            <><span /><span className="italic opacity-70 break-words">{m.placeholder}</span></>
                          ) : (
                            <>
                              <span className="row-span-2 self-center text-xs text-teal-500 text-right pr-1">vs</span>
                              <span className="min-w-0 break-words leading-snug">{name(m.pairA)}</span>
                              <span className="min-w-0 break-words leading-snug">{name(m.pairB)}</span>
                            </>
                          )}
                        </div>
                      );
                    })}
                </div>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* ---------- Vista pública: lista de torneos ---------- */

/* Tabla pública de un circuito: pestañas por categoría con el ranking de jugadores */
function CircuitPublicCard({ circuit, tournaments, accentColor = "#9fe022" }) {
  const [cat, setCat] = useState(circuit.categoryNames[0] || "");
  const standings = useMemo(() => computeCircuitStandings(circuit, tournaments), [circuit, tournaments]);
  const fechas = tournaments.filter((t) => t.circuitId === circuit.id).length;

  return (
    <div className="rounded-xl p-4" style={{ backgroundColor: accentColor + "0d", border: `1px solid ${accentColor}33`, borderTop: `3px solid ${accentColor}` }}>
      <p className="font-semibold" style={F.body}>🏆 {circuit.name} <span className="text-teal-500 text-sm font-normal">· {circuit.year}</span></p>
      <p className="text-xs text-teal-500 mb-3" style={F.body}>{fechas} fecha{fechas !== 1 ? "s" : ""} disputada{fechas !== 1 ? "s" : ""}</p>

      {circuit.categoryNames.length > 1 && (
        <div className="flex gap-2 mb-3 flex-wrap">
          {circuit.categoryNames.map((cn, cni) => {
            const color = GROUP_COLORS[cni % GROUP_COLORS.length];
            return (
              <button
                key={cn}
                onClick={() => setCat(cn)}
                className="px-3 py-1 rounded-full text-xs border font-medium"
                style={cat === cn ? { backgroundColor: color, color: "#14181f", borderColor: color } : { backgroundColor: color + "14", color, borderColor: color + "40" }}
              >
                {cn}
              </button>
            );
          })}
        </div>
      )}

      {(standings[cat] || []).length === 0 ? (
        <p className="text-xs opacity-60" style={F.body}>Todavía no hay puntos cargados en esta categoría.</p>
      ) : (
        <table className="w-full text-sm" style={F.body}>
          <thead><tr className="text-left" style={{ color: accentColor }}><th className="py-1">#</th><th>Jugador</th><th>Fechas</th><th>Pts</th></tr></thead>
          <tbody>
            {standings[cat].map((row, i) => (
              <tr key={row.name} style={{ backgroundColor: i % 2 === 0 ? "transparent" : "rgba(255,255,255,0.03)", borderLeft: i < 3 ? `3px solid ${accentColor}` : "3px solid transparent" }}>
                <td className="py-1 pl-1">{i === 0 ? "🥇" : i === 1 ? "🥈" : i === 2 ? "🥉" : i + 1}</td>
                <td className={i < 3 ? "font-semibold" : ""}>{row.name}</td><td>{row.fechas}</td><td className="font-semibold">{row.points}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

/* Todos los circuitos activos, agrupados por el organizador que los creó */
function CircuitsPublicView({ circuits, tournaments, organizers }) {
  const byOrganizer = {};
  circuits.forEach((c) => { (byOrganizer[c.organizerId] = byOrganizer[c.organizerId] || []).push(c); });

  if (circuits.length === 0) {
    return (
      <div className="px-6 pb-10">
        <p className="opacity-60 text-sm" style={F.body}>Todavía no hay circuitos cargados.</p>
      </div>
    );
  }

  return (
    <div className="px-6 pb-10 space-y-8">
      {Object.entries(byOrganizer).map(([organizerId, list]) => {
        const organizer = organizers.find((o) => o.id === organizerId);
        return (
          <div key={organizerId}>
            <h2 className="text-sm uppercase tracking-wide text-teal-400 mb-3" style={F.body}>{organizer?.name || "Organizador"}</h2>
            <div className="grid gap-4 md:grid-cols-2">
              {list.map((c, ci) => <CircuitPublicCard key={c.id} circuit={c} tournaments={tournaments} accentColor={GROUP_COLORS[ci % GROUP_COLORS.length]} />)}
            </div>
          </div>
        );
      })}
    </div>
  );
}

